INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C1','kor',5,1,'u6',1,'비유적 표현의 뜻 — 어떤 대상을 비슷한 점이 있는 다른 대상에 빗대어 표현하는 것이 비유적 표현이며, 사실을 있는 그대로 적거나 어려운 낱말을 쓰는 것과는 다르다',ARRAY['6국05-02 문학']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C2','kor',5,1,'u6',1,'실제로 그렇다는 말이 아니다 — 얼굴이 홍당무가 됐다는 말은 얼굴이 정말 홍당무로 바뀌었다는 뜻이 아니라, 어떤 모습인지 더 잘 떠오르게 견주어 말한 것이다',ARRAY['6국05-02 문학']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C3','kor',5,1,'u6',1,'빗대어 표현하면 좋은 점 — 빗대어 표현하면 익숙한 대상을 새롭게 느끼게 하고, 장면을 생생하게 떠올리게 하며, 말하는 이의 마음이 잘 전해진다',ARRAY['6국05-02 문학']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C4','kor',5,1,'u6',1,'빗댄 것과 대상의 비슷한 점 — 지우개를 작은 눈사람에 빗댄 까닭은 둘 다 하얗고 지날수록 점점 작아진다는 비슷한 점이 있기 때문이다',ARRAY['6국05-02 문학']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C5','kor',5,1,'u6',1,'비유는 일상 속에도 있다 — 비유는 시에만 있는 것이 아니라 노랫말, 「발이 넓다」 같은 관용어, 「티끌 모아 태산」 같은 속담처럼 일상의 말에도 들어 있다',ARRAY['6국05-02 문학']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C6','kor',5,1,'u6',1,'인상적인 부분의 뜻 — 작품을 읽고 유난히 마음에 남는 부분, 곧 마음이 움직인 곳이 인상적인 부분이며 사람마다 다르고 그 까닭도 저마다 다르다',ARRAY['6국05-04 문학']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C7','kor',5,1,'u6',1,'이 단원의 두 갈래 — 이 단원에서는 비유적 표현을 알고 시 낭송하기와 인상적인 부분을 중심으로 이야기 감상하기를 배운다',ARRAY['6국05-02 문학']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C8','kor',5,1,'u6',2,'시에서 표현하는 대상 찾기 — 시를 읽을 때는 무엇을 무엇에 빗대었는지부터 찾으며, 「내 마음은 유리병」에서 표현하는 대상은 내 마음이고 빗댄 것은 유리병이다',ARRAY['6국05-02 문학']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C9','kor',5,1,'u6',2,'은유법 — 「내 마음은 유리병」처럼 견주는 말 없이 「……은 ……이다」 꼴로 바로 그것이라고 말하며 빗대는 방법이 은유법이다',ARRAY['6국05-02 문학']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C10','kor',5,1,'u6',2,'직유법 — 「우산처럼 기울어」처럼 견주는 말을 써서 두 대상을 직접 견주는 방법이 직유법이며, 견주는 말이 겉으로 드러난다',ARRAY['6국05-02 문학']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C11','kor',5,1,'u6',2,'직유에 쓰이는 견주는 말 — 직유법에는 같이 · 처럼 · 듯이뿐 아니라 「우산 같은 친구」의 같은, 그리고 만큼처럼 견주는 말이 쓰인다',ARRAY['6국05-02 문학']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C12','kor',5,1,'u6',2,'비슷한 점이 있어야 마음에 닿는다 — 비유는 아무것에나 빗대는 것이 아니라 두 대상 사이에 비슷한 점이 있어야 하며, 우산 같은 친구는 제가 젖으면서도 남에게 기울어 주는 모습이 닮았다',ARRAY['6국05-02 문학']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C13','kor',5,1,'u6',2,'꼴이 같아도 은유가 아닐 수 있다 — 「내 동생은 삼 학년이다」와 「내 동생은 작은 태풍이다」는 꼴이 같지만 앞은 사실이고 뒤만 비유이므로, 꼴이 아니라 서로 다른 종류의 두 대상이 겹쳐졌는지를 본다',ARRAY['6국05-02 문학']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C14','kor',5,1,'u6',2,'비유가 아닌 문장 — 「교실에 나무 화분이 있다」처럼 다른 것에 빗대지 않고 사실을 그대로 말한 문장은 비유가 아니며, 다른 것에 빗대었는가가 판별 기준이다',ARRAY['6국05-02 문학']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C15','kor',5,1,'u6',2,'방법을 바꾸면 느낌이 달라진다 — 같은 비유도 직유로 쓰면 조심스럽게 견주고 은유로 쓰면 단번에 겹쳐 놓아, 방법에 따라 느낌이 달라진다',ARRAY['6국05-02 문학']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C16','kor',5,1,'u6',2,'이름을 외우는 것이 목적은 아니다 — 은유법 · 직유법의 이름을 외우는 것보다 시를 읽다가 두 대상을 겹쳐 놓은 표현을 알아보고 그 느낌을 감상하는 것이 먼저다',ARRAY['6국05-02 문학']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C17','kor',5,1,'u6',4,'시의 내용 알기 — 「나는 아직 새벽」의 말하는 이는 자신을 새벽에 빗대어 아직 자라는 중인 시기를 지나고 있다고 말한다',ARRAY['6국05-02 문학']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C18','kor',5,1,'u6',4,'비유적 표현의 뜻 풀기 — 「한낮이길 바라지」는 빨리 다 자라기를 바란다는 뜻이고, 「종달새처럼 크게 울게」는 때가 되면 힘껏 나를 펼치겠다는 뜻이다',ARRAY['6국05-02 문학']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C19','kor',5,1,'u6',4,'그것에 빗댄 까닭 — 자라는 시기를 하루의 시간에 빗댄 것은 자라는 일이 새벽 · 아침 · 한낮처럼 차례대로 오고 건너뛸 수 없다는 점이 닮았기 때문이다',ARRAY['6국05-02 문학']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C20','kor',5,1,'u6',4,'말하는 이의 마음 헤아리기 — 어른들이 벌써 한낮이길 바랄 때 「하지만 나는 아직 새벽」을 되풀이한 데서 재촉받는 것이 서운하고 답답한 마음을 헤아린다',ARRAY['6국05-02 문학']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C21','kor',5,1,'u6',4,'시를 낭송하는 방법 — 시는 분위기를 생각하며, 말하는 이의 처지나 마음을 상상하며, 어울리는 몸짓이나 표정으로, 친구와 번갈아 가며 낭송할 수 있다',ARRAY['6국05-02 문학']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C22','kor',5,1,'u6',4,'낭송할 때 살릴 것 — 낭송할 때는 시의 분위기, 말하는 이의 마음, 되풀이되는 말의 리듬을 살리며, 빠른 속도나 큰 목소리가 목표가 아니다',ARRAY['6국05-02 문학']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C23','kor',5,1,'u6',4,'끊어 읽기 — 어디서 쉬느냐에 따라 힘이 실리는 말이 달라지므로, 되풀이되는 말은 조금 더 천천히, 마음이 실린 말은 한 박자 쉬고 읽는다',ARRAY['6국05-02 문학']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C24','kor',5,1,'u6',4,'시의 분위기에 맞는 낭송 — 재촉받으면서도 스스로를 다독이는 「나는 아직 새벽」은 차분하게, 되풀이되는 말을 조용히 되뇌듯이 낭송하는 것이 어울린다',ARRAY['6국05-02 문학']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C25','kor',5,1,'u6',4,'여러 번 되풀이해 읽기 — 시는 한 번 읽고 끝내는 글이 아니어서 혼자도, 함께도 여러 번 소리 내어 읽을수록 처음에 지나친 뜻이 보이며, 낭송은 결과보다 그 과정이 중요하다',ARRAY['6국05-02 문학']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C26','kor',5,1,'u6',4,'자신과 관련지어 감상하기 — 말하는 이가 자신을 새벽에 빗댄 것처럼 지금의 나를 무엇에 빗댈지 그 까닭과 함께 떠올리면 시가 내 이야기가 되고 나를 조금 더 알게 된다',ARRAY['6국05-02 문학']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C27','kor',5,1,'u6',6,'시로 쓸 대상 고르기 — 시는 거창하거나 화려한 말이 아니라 겪은 일에서 오므로, 내가 직접 보고 겪어서 특징을 떠올릴 수 있는 대상을 고른다',ARRAY['6국05-02 문학']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C28','kor',5,1,'u6',6,'대상을 살펴 떠올리기 — 시로 쓸 대상을 정하면 대상의 특징, 대상과 관련한 경험, 그때의 생각이나 느낌을 함께 떠올린다',ARRAY['6국05-02 문학']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C29','kor',5,1,'u6',6,'보이지 않는 특징 — 겉모습만 보면 비유가 얕아지므로, 사진으로 찍을 수 없는 하는 일이나 태도 같은 보이지 않는 특징도 살핀다',ARRAY['6국05-02 문학']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C30','kor',5,1,'u6',6,'비유를 만드는 차례 — 시로 쓸 대상 → 대상의 특징 → 비유할 대상 → 비슷한 점 → 비유적 표현의 차례로 비유를 만든다',ARRAY['6국05-02 문학']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C31','kor',5,1,'u6',6,'좋은 비유의 조건 — 좋은 비유는 두 대상 사이에 비슷한 점이 있고, 그렇게 빗댄 까닭을 말할 수 있으며, 담고 싶은 뜻이나 마음이 함께 전해진다',ARRAY['6국05-02 문학']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C32','kor',5,1,'u6',6,'비유는 많을수록 좋은 것이 아니다 — 비유를 많이 넣는 것이 목적이 아니라 대상의 특징이 잘 드러나는 비유 하나가 흩어진 비유 여럿보다 오래 남는다',ARRAY['6국05-02 문학']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C33','kor',5,1,'u6',6,'감상 쪽지 쓰기 — 감상 쪽지에는 어느 표현이 왜 좋았는지와 더 좋은 생각을 적으며, 쪽지는 점수를 매기는 것이 아니라 다음 시를 돕는 것이다',ARRAY['6국05-02 문학']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C34','kor',5,1,'u6',6,'같은 대상도 빗대는 것은 저마다 다르다 — 같은 대상을 골라도 무엇에 빗대는지는 사람마다 다르며, 그 차이가 그 사람이 대상을 보는 눈이다',ARRAY['6국05-02 문학']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C35','kor',5,1,'u6',8,'이야기의 내용 알기 — 「할머니의 라디오」에서 재하는 정전이 난 밤 어둠 속에서 할머니의 이야기를 오래 들은 뒤로 라디오 소리가 거슬리지 않게 되었다',ARRAY['6국05-02 문학']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C36','kor',5,1,'u6',8,'이야기 속 비유적 표현 찾기 — 이야기에서도 「오래된 이불처럼」 · 「두꺼운 담요 같았다」처럼 다른 것에 빗대어 그린 표현을 찾을 수 있으며, 사실을 적은 문장은 비유가 아니다',ARRAY['6국05-02 문학']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C37','kor',5,1,'u6',8,'비유가 만드는 느낌 — 「두꺼운 담요 같은 어둠」은 답답하고 조금 무서운 느낌을, 「낮은 강물처럼 흘러온 목소리」는 잔잔하고 마음을 놓게 하는 느낌을 만든다',ARRAY['6국05-02 문학']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C38','kor',5,1,'u6',8,'이야기에서 비유를 쓰면 좋은 점 — 이야기에 비유적 표현을 쓰면 장면이 생생해지고, 설명하지 않아도 인물의 마음이 함께 전해진다',ARRAY['6국05-02 문학']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C39','kor',5,1,'u6',8,'비유 찾기가 목적은 아니다 — 비유적 표현만 골라내다 보면 이야기 전체를 놓치기 쉬우므로, 누가 무엇을 겪었고 마음이 어떻게 달라졌는지를 먼저 살핀다',ARRAY['6국05-02 문학']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C40','kor',5,1,'u6',8,'인상적인 부분 고르기 — 인상적인 부분은 가장 중요한 장면이 아니라 내 마음이 움직인 장면이며, 인물의 말이나 행동 · 사건 · 배경 · 표현 가운데에서 고른다',ARRAY['6국05-04 문학']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C41','kor',5,1,'u6',8,'까닭과 근거를 대며 말하기 — 인상적인 부분을 고른 뒤에는 작품의 어느 대목 때문에 그렇게 느꼈는지 근거를 함께 말하며, 근거를 대면 감상이 내 의견이 된다',ARRAY['6국05-04 문학']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C42','kor',5,1,'u6',8,'내 삶과 이어 감상 나누기 — 작품을 읽고 놓치고 지낸 일은 없었는지처럼 내 삶과 이어 생각을 나누면 작품이 더 오래 남는다',ARRAY['6국05-04 문학']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C43','kor',5,1,'u6',10,'신화의 뜻 — 신화는 아주 오래전부터 입에서 입으로 전해 온 이야기로, 나라가 어떻게 세워졌는지나 세상이 어떻게 생겼는지를 놀라운 사건으로 풀어낸다',ARRAY['6국05-04 문학']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C44','kor',5,1,'u6',10,'신화의 흐름 알기 — 주몽 이야기는 알에서 태어남 → 뛰어난 활 솜씨와 태자의 시기 → 좋은 말을 마련해 떠남 → 자라와 물고기의 도움으로 강을 건너 고구려를 세움의 차례로 흐른다',ARRAY['6국05-04 문학']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C45','kor',5,1,'u6',10,'신화 속 낱말의 뜻 — 도읍은 한 나라의 중앙 정부가 있는 곳, 태자는 임금의 뒤를 이을 아들, 후환은 뒷날 생기는 걱정과 근심, 단연은 여럿 가운데 뚜렷하게라는 뜻이다',ARRAY['6국05-04 문학']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C46','kor',5,1,'u6',10,'신화 속 비유적 표현 — 「그림자처럼 따라다닌 햇빛」 · 「갈대처럼 여윈 말」처럼 신화에도 비유적 표현이 쓰여 장면이 또렷해진다',ARRAY['6국05-02 문학']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C47','kor',5,1,'u6',10,'신화의 특징 — 신화에는 비범한 탄생, 남다른 재주, 시련과 뜻밖의 도움, 나라의 시작이 자주 나타난다',ARRAY['6국05-04 문학']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C48','kor',5,1,'u6',10,'여러 신화의 닮은 점 — 주몽 · 박혁거세 · 프로메테우스 이야기에는 보통 사람과 다른 특별한 인물이 나오고, 놀라운 사건이 일어나며, 무언가의 시작을 설명한다는 닮은 점이 있다',ARRAY['6국05-04 문학']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C49','kor',5,1,'u6',10,'같은 장면도 해석이 갈린다 — 고르는 장면이 사람마다 다를 뿐 아니라 같은 장면을 두고도 다르게 새길 수 있으며, 감상 나누기는 누구의 감상이 맞는지 가리는 일이 아니다',ARRAY['6국05-04 문학']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C50','kor',5,1,'u6',12,'책갈피를 만드는 차례 — 읽은 작품을 고르고 → 비유적 표현을 찾아 → 앞면에 표현, 뒷면에 어울리는 그림을 넣고 → 끈을 묶어 책갈피를 완성한다',ARRAY['6국05-02 문학']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C51','kor',5,1,'u6',12,'책갈피에 담을 표현 — 책갈피에는 한 줄만으로도 장면이 떠오르는 비유적 표현을 고르며, 「오늘은 화요일이다」처럼 사실만 적은 문장은 알맞지 않다',ARRAY['6국05-02 문학']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C52','kor',5,1,'u6',12,'그림은 표현이 만든 장면을 담는다 — 책갈피 뒷면의 그림은 표현을 다시 설명하는 것이 아니라 그 표현이 만든 장면을 담는 것이다',ARRAY['6국05-02 문학']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C53','kor',5,1,'u6',12,'만들 때 살필 것 — 책갈피는 작으므로 표현은 한두 줄만 옮기고 글씨는 또렷하게, 색은 분위기에 맞추며, 가져온 표현이라면 작품 제목과 지은이를 적는다',ARRAY['6국05-02 문학']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C54','kor',5,1,'u6',12,'책갈피를 소개하는 말 — 완성한 책갈피를 소개할 때는 고른 표현과 그것을 고른 까닭을 함께 말한다',ARRAY['6국05-02 문학']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C55','kor',5,1,'u6',12,'빗대어 말하면 스스로 깨닫게 된다 — 「조개와 황새」의 신하가 「싸우지 마십시오」 대신 이야기를 들려준 것처럼, 빗대어 말하면 듣는 사람이 스스로 깨닫게 되므로 비유는 시만의 기술이 아니라 말의 방법이다',ARRAY['6국05-02 문학']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C56','kor',5,1,'u6',12,'이야기에 담긴 뜻 헤아리기 — 「조개와 황새」는 두 나라가 다투면 지켜보던 다른 나라만 이롭다는 뜻을 조개 · 황새 · 어부에 빗대어 담았다',ARRAY['6국05-04 문학']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C57','kor',5,1,'u6',12,'잘 듣는 방법 — 말하는 사람을 보며 귀 기울여 듣고, 정리하며 듣고, 모르는 말은 질문하며 듣고, 이해한 내용이 맞는지 확인하며 들으며, 잘 듣기는 가만히 있는 일이 아니라 움직이는 일이다 (기초 다지기)',ARRAY['기초 다지기(잘 듣는 방법)']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u6-C58','kor',5,1,'u6',12,'피해야 할 듣기 태도 — 내용이 많다고 흘려듣기, 듣고 싶은 부분만 골라 듣기, 실수나 부족한 점만 따지며 듣기, 모르면서 묻지 않고 넘어가기는 피한다 (기초 다지기)',ARRAY['기초 다지기(잘 듣는 방법)']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X01','kor',5,'u6',ARRAY['K5-1-u6-C1']::text[],'비유적 표현을 사실을 있는 그대로 자세히 적는 것이나 어려운 낱말을 많이 쓰는 것으로 여긴다','비슷한 것에 빗대기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X02','kor',5,'u6',ARRAY['K5-1-u6-C2']::text[],'비유적 표현을 실제로 그렇게 바뀌었다는 말로 받아들이거나, 사실이 아니니 거짓말이라고 여긴다','견주어 말한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X03','kor',5,'u6',ARRAY['K5-1-u6-C3']::text[],'빗대어 표현하는 까닭을 글을 길게 늘이거나 어려워 보이게 하려는 것으로 여긴다','새롭게 · 생생하게 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X04','kor',5,'u6',ARRAY['K5-1-u6-C4']::text[],'빗댄 것과 대상의 비슷한 점을 시에 나오지 않는 엉뚱한 점에서 찾는다','시에서 어떻게 그렸나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X05','kor',5,'u6',ARRAY['K5-1-u6-C5']::text[],'비유는 시에만 쓰는 특별한 기술이라 노랫말이나 관용어 · 속담 같은 일상의 말에는 없다고 여긴다','일상의 말에도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X06','kor',5,'u6',ARRAY['K5-1-u6-C6']::text[],'인상적인 부분을 누구에게나 같은 정답이 있는 것이나 글에서 가장 긴 부분으로 여긴다','마음이 움직인 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X07','kor',5,'u6',ARRAY['K5-1-u6-C7']::text[],'이 단원의 공부를 시 한쪽뿐이거나 비유와 관계없는 공부로 여긴다','시 낭송 · 이야기 감상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X08','kor',5,'u6',ARRAY['K5-1-u6-C8']::text[],'시에서 표현하는 대상과 빗댄 것을 서로 바꾸어 여기거나 시 속 낱말 아무것이나 대상으로 고른다','무엇을 무엇에 빗대었나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X09','kor',5,'u6',ARRAY['K5-1-u6-C9']::text[],'견주는 말이 들어간 표현을 은유법으로 여기거나 은유법은 같다고 견주는 방법이라고 여긴다','바로 그것이라고 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X10','kor',5,'u6',ARRAY['K5-1-u6-C10']::text[],'「……은 ……이다」 꼴의 표현을 직유법으로 여기거나 직유법에는 견주는 말이 드러나지 않는다고 여긴다','견주는 말이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X11','kor',5,'u6',ARRAY['K5-1-u6-C11']::text[],'직유법에 쓰이는 말을 같이 · 처럼 · 듯이 셋뿐으로 여겨 「같은」 · 「만큼」을 알아보지 못하거나, 그러나 · 왜냐하면 같은 말을 견주는 말로 고른다','같은 · 만큼도 견주는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X12','kor',5,'u6',ARRAY['K5-1-u6-C12']::text[],'비유는 아무것에나 빗대면 된다고 여기거나 두 대상의 비슷한 점을 살피지 않는다','닮은 점이 있어야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X13','kor',5,'u6',ARRAY['K5-1-u6-C13']::text[],'「……은 ……이다」 꼴이기만 하면 사실을 말한 문장도 모두 은유법이라고 여긴다','서로 다른 두 대상이 겹쳤나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X14','kor',5,'u6',ARRAY['K5-1-u6-C14']::text[],'빗댄 것이 없이 사실을 그대로 말한 문장도 비유로 여기거나 대상이 나오기만 하면 비유라고 여긴다','다른 것에 빗대었나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X15','kor',5,'u6',ARRAY['K5-1-u6-C15']::text[],'직유와 은유는 이름만 다를 뿐 느낌은 언제나 똑같다고 여기거나, 방법을 바꾸면 뜻까지 바뀐다고 여긴다','견주기와 겹치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X16','kor',5,'u6',ARRAY['K5-1-u6-C16']::text[],'은유법 · 직유법의 이름을 외우는 것이 시 공부의 목적이라고 여긴다','알아보고 감상하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X17','kor',5,'u6',ARRAY['K5-1-u6-C17']::text[],'「나는 아직 새벽」의 말하는 이가 이미 다 자랐거나 모든 것이 끝난 시기에 있다고 여긴다','새벽은 하루의 처음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X18','kor',5,'u6',ARRAY['K5-1-u6-C18']::text[],'시의 비유적 표현을 글자 그대로 풀거나 표현과 뜻을 엉뚱하게 짝짓는다','무엇을 빗대었나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X19','kor',5,'u6',ARRAY['K5-1-u6-C19']::text[],'자라는 시기를 하루에 빗댄 까닭을 시간이 짧다거나 날씨와 관계있기 때문으로 여긴다','차례대로 오고 건너뛸 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X20','kor',5,'u6',ARRAY['K5-1-u6-C20']::text[],'말하는 이의 마음을 되풀이되는 말과 관계없이 짐작하거나 빨리 자라게 되어 신난다고 여긴다','「하지만」 뒤를 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X21','kor',5,'u6',ARRAY['K5-1-u6-C21']::text[],'시 낭송은 한 가지 방법뿐이라고 여기거나 시와 관계없는 방법을 낭송 방법으로 고른다','분위기 · 마음 · 몸짓 · 번갈아') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X22','kor',5,'u6',ARRAY['K5-1-u6-C22']::text[],'낭송을 잘하려면 최대한 빠르게, 가장 큰 목소리로 읽으면 된다고 여긴다','분위기 · 마음 · 리듬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X23','kor',5,'u6',ARRAY['K5-1-u6-C23']::text[],'어디서 쉬든 시의 느낌은 똑같다고 여기거나 쉬지 않고 이어 읽어야 잘 읽는 것이라고 여긴다','쉬는 곳에 힘이 실려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X24','kor',5,'u6',ARRAY['K5-1-u6-C24']::text[],'시의 분위기와 관계없이 모든 시를 힘차게 외치거나 우스꽝스럽게 낭송한다','분위기에 맞추어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X25','kor',5,'u6',ARRAY['K5-1-u6-C25']::text[],'시는 한 번 읽으면 충분하다고 여기거나 낭송은 결과만 잘 나오면 된다고 여긴다','여러 번 · 과정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X26','kor',5,'u6',ARRAY['K5-1-u6-C26']::text[],'시를 나와 관계없는 남의 이야기로만 읽거나 나를 빗댈 때 까닭은 없어도 된다고 여긴다','지금의 나는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X27','kor',5,'u6',ARRAY['K5-1-u6-C27']::text[],'시로 쓸 대상은 본 적 없는 거창하고 화려한 것이어야 한다고 여기거나 친구의 비밀처럼 쓰면 안 되는 것을 고른다','겪은 일에서 와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X28','kor',5,'u6',ARRAY['K5-1-u6-C28']::text[],'대상을 살필 때 겉모습 하나만 적고 관련한 경험이나 생각 · 느낌은 떠올리지 않아도 된다고 여긴다','특징 · 경험 · 느낌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X29','kor',5,'u6',ARRAY['K5-1-u6-C29']::text[],'눈에 보이는 색이나 모양만 대상의 특징이라고 여겨 하는 일이나 태도는 살피지 않는다','사진으로 찍을 수 없는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X30','kor',5,'u6',ARRAY['K5-1-u6-C30']::text[],'비유를 만들 때 대상의 특징을 살피기 전에 빗댈 것부터 정하거나 차례를 뒤섞는다','대상 → 특징 → 빗댈 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X31','kor',5,'u6',ARRAY['K5-1-u6-C31']::text[],'뜻이 어렵거나 낱말이 화려하면 좋은 비유라고 여기거나 빗댄 까닭을 말하지 못해도 괜찮다고 여긴다','비슷한 점 · 까닭 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X32','kor',5,'u6',ARRAY['K5-1-u6-C32']::text[],'한 시에 비유를 많이 넣을수록 좋은 시가 된다고 여긴다','잘 드러나는 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X33','kor',5,'u6',ARRAY['K5-1-u6-C33']::text[],'감상 쪽지를 「잘 썼어」처럼 점수만 매기는 말로 채우거나 어느 표현이 왜 좋았는지 쓰지 않는다','어느 표현이 왜') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X34','kor',5,'u6',ARRAY['K5-1-u6-C34']::text[],'같은 대상이면 누구나 같은 것에 빗대야 한다고 여기거나 다르게 빗댄 것을 틀렸다고 여긴다','그 사람의 눈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X35','kor',5,'u6',ARRAY['K5-1-u6-C35']::text[],'라디오 소리가 거슬리지 않게 된 까닭을 소리가 작아졌거나 휴대 전화를 다시 켰기 때문으로 여긴다','정전이 난 밤의 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X36','kor',5,'u6',ARRAY['K5-1-u6-C36']::text[],'「건전지 한 통을 샀다」처럼 사실을 적은 문장을 비유적 표현으로 고르거나 견주는 말이 든 표현을 놓친다','다른 것에 빗대었나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X37','kor',5,'u6',ARRAY['K5-1-u6-C37']::text[],'비유적 표현이 만드는 느낌을 표현과 반대로 짐작하거나 엉뚱하게 짝짓는다','떠오르는 장면을 그려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X38','kor',5,'u6',ARRAY['K5-1-u6-C38']::text[],'이야기에서 비유를 쓰는 까닭을 길이를 줄이거나 정확한 숫자를 알려 주려는 것으로 여긴다','장면과 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X39','kor',5,'u6',ARRAY['K5-1-u6-C39']::text[],'이야기를 읽을 때 비유적 표현을 골라내는 것이 목적이라고 여겨 줄거리와 인물의 마음을 놓친다','누가 무엇을 겪었나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X40','kor',5,'u6',ARRAY['K5-1-u6-C40']::text[],'인상적인 부분을 이야기에서 가장 중요한 장면이나 정해진 정답으로 여기거나 글자 수처럼 관계없는 것으로 고른다','내 마음이 움직인 장면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X41','kor',5,'u6',ARRAY['K5-1-u6-C41']::text[],'인상적인 부분을 고른 까닭을 「그냥 좋아서」처럼 작품 내용과 이어지지 않게 말해도 된다고 여긴다','어느 대목 때문에?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X42','kor',5,'u6',ARRAY['K5-1-u6-C42']::text[],'작품은 작품일 뿐이라 내 삶과 이어 생각할 필요가 없다고 여긴다','내 삶으로 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X43','kor',5,'u6',ARRAY['K5-1-u6-C43']::text[],'신화를 요즘 일어난 일을 그대로 적은 기록이나 평범한 사람의 하루를 그린 이야기로 여긴다','오래전부터 전해 온 이야기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X44','kor',5,'u6',ARRAY['K5-1-u6-C44']::text[],'신화에서 일이 일어난 차례를 뒤섞거나 일이 일어난 까닭을 엉뚱하게 짐작한다','차례와 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X45','kor',5,'u6',ARRAY['K5-1-u6-C45']::text[],'도읍 · 태자 · 후환 · 단연의 뜻을 서로 헷갈린다','쓰인 문장을 다시 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X46','kor',5,'u6',ARRAY['K5-1-u6-C46']::text[],'신화는 옛이야기라 비유적 표현이 없다고 여기거나 사실을 적은 문장을 비유로 고른다','처럼이 든 표현') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X47','kor',5,'u6',ARRAY['K5-1-u6-C47']::text[],'신화의 특징을 모든 사건이 날짜까지 정확하다거나 평범한 사람의 하루를 그린다는 것으로 여긴다','비범한 탄생 · 시련 · 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X48','kor',5,'u6',ARRAY['K5-1-u6-C48']::text[],'여러 신화의 닮은 점을 모두 같은 나라 이야기라거나 모두 알에서 태어난다는 것으로 여긴다','특별한 인물 · 놀라운 사건 · 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X49','kor',5,'u6',ARRAY['K5-1-u6-C49']::text[],'같은 장면을 고르면 느낀 것도 같아야 한다고 여기거나 감상 나누기를 누구의 감상이 맞는지 가리는 일로 여긴다','한 장면 · 여러 해석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X50','kor',5,'u6',ARRAY['K5-1-u6-C50']::text[],'책갈피를 만들 때 작품과 표현을 고르기 전에 꾸미기부터 하거나 차례를 뒤섞는다','작품 → 표현 → 앞뒷면 → 끈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X51','kor',5,'u6',ARRAY['K5-1-u6-C51']::text[],'책갈피에 사실만 적은 문장을 담거나 장면이 떠오르지 않는 표현을 고른다','한 줄로 장면이 떠올라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X52','kor',5,'u6',ARRAY['K5-1-u6-C52']::text[],'책갈피 그림을 표현과 관계없는 그림으로 그리거나 표현을 글로 다시 설명하는 것이라고 여긴다','표현이 만든 장면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X53','kor',5,'u6',ARRAY['K5-1-u6-C53']::text[],'작은 책갈피에 시 전체를 빽빽하게 옮겨 적거나 가져온 표현의 제목과 지은이를 적지 않아도 된다고 여긴다','한두 줄 · 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X54','kor',5,'u6',ARRAY['K5-1-u6-C54']::text[],'책갈피를 소개할 때 걸린 시간이나 쓴 색연필의 개수처럼 표현과 관계없는 것을 말하거나 「그냥 예뻐서」로 끝낸다','고른 표현과 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X55','kor',5,'u6',ARRAY['K5-1-u6-C55']::text[],'비유는 시에만 쓰는 기술이라 여기거나 바로 말하지 않고 이야기로 빗대어 말하는 것은 쓸모없다고 여긴다','스스로 깨닫게 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X56','kor',5,'u6',ARRAY['K5-1-u6-C56']::text[],'「조개와 황새」를 조개 잡는 방법이나 황새가 더 세다는 이야기로 글자 그대로만 읽는다','누가 무엇을 나타내나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X57','kor',5,'u6',ARRAY['K5-1-u6-C57']::text[],'잘 듣기를 가만히 앉아 있기만 하는 일로 여기거나 네 가지 방법을 헷갈린다','귀 기울이기 · 정리 · 질문 · 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u6-X58','kor',5,'u6',ARRAY['K5-1-u6-C58']::text[],'흘려듣기 · 골라 듣기 · 따지며 듣기 · 묻지 않기처럼 대화를 끊는 듣기를 괜찮다고 여긴다','대화가 이어지게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#1','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C1',1,'mc','auto','비유적 표현의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X01','K5-1-u6-X03']::text[],false,'{"seq":1,"concept":"K5-1-u6-C1","difficulty":1,"kind":"mc","stem":"비유적 표현의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 대상을 비슷한 점이 있는 다른 대상에 빗대어 표현하는 것","correct":true},{"t":"사실을 있는 그대로 자세히 적는 것","mis":"K5-1-u6-X01"},{"t":"어려운 낱말을 많이 쓰는 것","mis":"K5-1-u6-X01"},{"t":"글의 길이를 길게 늘이는 것","mis":"K5-1-u6-X03"}],"explanation":["있는 그대로 적는 것과 달라요.","어려운 낱말과 관계없어요.","비슷한 것에 빗대어 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#2','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C2',1,'mc','auto','소율이가 한 「얼굴이 홍당무가 됐어」는 무슨 뜻인가요?',ARRAY['K5-1-u6-X02']::text[],false,'{"seq":2,"concept":"K5-1-u6-C2","difficulty":1,"kind":"mc","stem":"소율이가 한 「얼굴이 홍당무가 됐어」는 무슨 뜻인가요?","options":[{"t":"얼굴이 홍당무처럼 빨개졌다","correct":true},{"t":"얼굴이 정말 홍당무로 바뀌었다","mis":"K5-1-u6-X02"},{"t":"소율이가 홍당무를 먹었다","mis":"K5-1-u6-X02"},{"t":"소율이가 거짓말을 했다","mis":"K5-1-u6-X02"}],"explanation":["정말 바뀐 것이 아니에요.","먹은 이야기가 아니에요.","빨개진 모습을 견주어 말했어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"아까 발표할 때 얼굴이 홍당무가 됐어."},{"who":"유담","text":"나는 운동장을 한 바퀴 돌았더니 땀이 폭포처럼 흘렀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#3','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C4',1,'mc','auto','시 「지우개」에서 지우개와 눈사람의 비슷한 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":3,"concept":"K5-1-u6-C4","difficulty":1,"kind":"mc","stem":"시 「지우개」에서 지우개와 눈사람의 비슷한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"하얗고 지날수록 점점 작아진다","correct":true},{"t":"둘 다 차갑다","mis":"K5-1-u6-X04"},{"t":"둘 다 겨울에만 볼 수 있다","mis":"K5-1-u6-X04"},{"t":"둘 다 공책 위에서 산다","mis":"K5-1-u6-X04"}],"explanation":["시에 차갑다는 말은 없어요.","계절 이야기가 아니에요.","시에서 지우개가 어떻게 변하는지 보아요."],"asset":{"type":"passage","lines":["공책 위를 지나간 곳마다 하얀 길이 생긴다","지우개는 작은 눈사람","지날수록 조금씩 작아진다","내 실수를 다 데리고","제 몸을 덜어 가며 걸어간다","다 닳은 지우개를 손에 쥐면 괜히 미안해진다"],"title":"시 「지우개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#4','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C5',1,'ox','auto','비유적 표현은 시에만 쓰이는 특별한 말이에요.',ARRAY['K5-1-u6-X05']::text[],false,'{"seq":4,"concept":"K5-1-u6-C5","difficulty":1,"kind":"ox","stem":"비유적 표현은 시에만 쓰이는 특별한 말이에요.","answer":"X","reason_options":[{"t":"노랫말이나 관용어, 속담 같은 일상의 말에도 들어 있기 때문에","correct":true},{"t":"시를 쓰는 사람만 빗대어 말할 수 있기 때문에","mis":"K5-1-u6-X05"}],"mis":"K5-1-u6-X05","explanation":["시 밖에도 비유가 있어요.","「발이 넓다」를 떠올려요.","일상의 말에도 비유가 들어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#5','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C3',2,'mc','auto','빗대어 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X03','K5-1-u6-X01']::text[],false,'{"seq":5,"concept":"K5-1-u6-C3","difficulty":2,"kind":"mc","stem":"빗대어 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면을 더 생생하게 떠올리게 해 준다","correct":true},{"t":"글의 길이를 늘릴 수 있다","mis":"K5-1-u6-X03"},{"t":"어려운 낱말을 쓸 수 있다","mis":"K5-1-u6-X03"},{"t":"사실을 정확한 숫자로 알려 준다","mis":"K5-1-u6-X01"}],"explanation":["길이를 늘리려는 것이 아니에요.","어려운 말과 관계없어요.","장면이 생생하게 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#6','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C6',2,'mc','auto','인상적인 부분으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X06']::text[],false,'{"seq":6,"concept":"K5-1-u6-C6","difficulty":2,"kind":"mc","stem":"인상적인 부분으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품을 읽고 유난히 마음에 남는 부분","correct":true},{"t":"글에서 가장 긴 부분","mis":"K5-1-u6-X06"},{"t":"누구나 똑같이 골라야 하는 정답","mis":"K5-1-u6-X06"},{"t":"작품의 맨 처음 문장","mis":"K5-1-u6-X06"}],"explanation":["길이와 관계없어요.","정답이 정해져 있지 않아요.","마음이 움직인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#7','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C7',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u6-X07']::text[],false,'{"seq":7,"concept":"K5-1-u6-C7","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"비유적 표현을 알고 시 낭송하기 · 인상적인 부분을 중심으로 이야기 감상하기","correct":true},{"t":"토의 절차 익히기 · 의견 조정하기","mis":"K5-1-u6-X07"},{"t":"설명하는 글 쓰기 · 내용 요약하기","mis":"K5-1-u6-X07"},{"t":"시 낭송하기만 하고 이야기는 읽지 않기","mis":"K5-1-u6-X07"}],"explanation":["토의는 앞 단원이에요.","설명하는 글도 앞 단원이에요.","시 낭송과 이야기 감상 두 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#8','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C4',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「지우개를 눈사람에 빗댄 것은 둘 사이에 (　　)이 있기 때문이다.」',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":8,"concept":"K5-1-u6-C4","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「지우개를 눈사람에 빗댄 것은 둘 사이에 (　　)이 있기 때문이다.」","options":[{"t":"비슷한 점","correct":true},{"t":"다른 점","mis":"K5-1-u6-X04"},{"t":"같은 이름","mis":"K5-1-u6-X04"},{"t":"같은 값","mis":"K5-1-u6-X04"}],"explanation":["다른 점으로는 빗댈 수 없어요.","이름과 관계없어요.","닮은 점이 있어야 빗대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#9','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C5',2,'match','auto','일상 속 말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C5","difficulty":2,"kind":"match","stem":"일상 속 말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"발이 넓다","r":"아는 사람이 많다"},{"l":"티끌 모아 태산","r":"작은 것도 모이면 크게 된다"},{"l":"땀이 폭포처럼 흘렀다","r":"땀이 아주 많이 흘렀다"}],"mis":"K5-1-u6-X05","explanation":["발 크기 이야기가 아니에요.","티끌이 모여 산이 돼요.","폭포처럼 쏟아지는 땀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_basic#10','kor',5,1,'u6','L01','g5_1_kor_u6_L01_basic','lesson_basic','K5-1-u6-C1',3,'mc','auto','다음 가운데 비유적 표현이 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u6-X14']::text[],false,'{"seq":10,"concept":"K5-1-u6-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 비유적 표현이 쓰인 문장은 어느 것인가요?","options":[{"t":"내 동생 웃음소리는 작은 종소리 같다","correct":true},{"t":"내 동생은 웃음소리가 크다","mis":"K5-1-u6-X14"},{"t":"내 동생은 오늘 아침에 웃었다","mis":"K5-1-u6-X14"},{"t":"내 동생 이름은 새봄이다","mis":"K5-1-u6-X14"}],"explanation":["있는 그대로 말했어요.","있었던 일을 그대로 말했어요.","웃음소리를 종소리에 빗대었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#1','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C2',2,'ox','auto','유담이의 「땀이 폭포처럼 흘렀어」는 사실이 아니므로 거짓말이에요.',ARRAY['K5-1-u6-X02']::text[],false,'{"seq":1,"concept":"K5-1-u6-C2","difficulty":2,"kind":"ox","stem":"유담이의 「땀이 폭포처럼 흘렀어」는 사실이 아니므로 거짓말이에요.","answer":"X","reason_options":[{"t":"실제로 그렇다는 말이 아니라 모습이 잘 떠오르게 견주어 말한 것이기 때문에","correct":true},{"t":"사실과 다른 말은 모두 거짓말이기 때문에","mis":"K5-1-u6-X02"}],"mis":"K5-1-u6-X02","explanation":["땀이 정말 폭포가 된 건 아니에요.","속이려는 말이 아니에요.","견주어 말한 비유예요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"아까 발표할 때 얼굴이 홍당무가 됐어."},{"who":"유담","text":"나는 운동장을 한 바퀴 돌았더니 땀이 폭포처럼 흘렀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#2','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C6',2,'mc','auto','인상적인 부분에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X06','K5-1-u6-X41']::text[],false,'{"seq":2,"concept":"K5-1-u6-C6","difficulty":2,"kind":"mc","stem":"인상적인 부분에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람마다 고르는 부분과 그 까닭이 다를 수 있다","correct":true},{"t":"모든 사람이 같은 부분을 골라야 한다","mis":"K5-1-u6-X06"},{"t":"작품에서 가장 긴 문단이 인상적인 부분이다","mis":"K5-1-u6-X06"},{"t":"까닭이 없어도 정답만 맞히면 된다","mis":"K5-1-u6-X41"}],"explanation":["같을 필요가 없어요.","길이와 관계없어요.","사람마다 다르고 까닭도 저마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#3','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C3',3,'mc','auto','시 「지우개」의 「제 몸을 덜어 가며 걸어간다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":3,"concept":"K5-1-u6-C3","difficulty":3,"kind":"mc","stem":"시 「지우개」의 「제 몸을 덜어 가며 걸어간다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"제 몸을 덜어 남을 돕는 지우개에 대한 고마움과 미안함","correct":true},{"t":"지우개가 빨리 없어져서 기쁜 마음","mis":"K5-1-u6-X04"},{"t":"지우개를 새로 사고 싶은 마음","mis":"K5-1-u6-X04"},{"t":"공책이 더러워져서 화난 마음","mis":"K5-1-u6-X04"}],"explanation":["기쁜 마음이 아니에요.","새로 사자는 시가 아니에요.","마지막 행의 「미안해진다」를 보아요."],"asset":{"type":"passage","lines":["공책 위를 지나간 곳마다 하얀 길이 생긴다","지우개는 작은 눈사람","지날수록 조금씩 작아진다","내 실수를 다 데리고","제 몸을 덜어 가며 걸어간다","다 닳은 지우개를 손에 쥐면 괜히 미안해진다"],"title":"시 「지우개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#4','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C1',3,'mc','auto','「지우개는 작은 눈사람」에서 빗대는 대상과 빗댄 것을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":4,"concept":"K5-1-u6-C1","difficulty":3,"kind":"mc","stem":"「지우개는 작은 눈사람」에서 빗대는 대상과 빗댄 것을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"빗대는 대상 — 지우개 / 빗댄 것 — 눈사람","correct":true},{"t":"빗대는 대상 — 눈사람 / 빗댄 것 — 지우개","mis":"K5-1-u6-X08"},{"t":"빗대는 대상 — 공책 / 빗댄 것 — 지우개","mis":"K5-1-u6-X08"},{"t":"빗대는 대상 — 실수 / 빗댄 것 — 공책","mis":"K5-1-u6-X08"}],"explanation":["둘이 뒤바뀌었어요.","공책은 대상이 아니에요.","지우개를 눈사람에 빗대었어요."],"asset":{"type":"passage","lines":["공책 위를 지나간 곳마다 하얀 길이 생긴다","지우개는 작은 눈사람","지날수록 조금씩 작아진다","내 실수를 다 데리고","제 몸을 덜어 가며 걸어간다","다 닳은 지우개를 손에 쥐면 괜히 미안해진다"],"title":"시 「지우개」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#5','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C5',3,'error','auto','비유에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X05']::text[],false,'{"seq":5,"concept":"K5-1-u6-C5","difficulty":3,"kind":"error","stem":"비유에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「비유는 시를 쓸 때만 쓰는 말이야.」","correct":true,"mis_target":"K5-1-u6-X05"},{"t":"「속담에도 빗대어 말한 것이 있어.」","mis":"K5-1-u6-X05"},{"t":"「노랫말에도 비유가 자주 나와.」","mis":"K5-1-u6-X05"}],"explanation":["속담에도 비유가 있어요.","노랫말에도 있어요.","비유는 일상의 말에도 들어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#6','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C3',3,'mc','auto','「친구가 반가웠다」를 「친구 얼굴이 봄 햇살 같았다」로 바꾸면 무엇이 달라지나요?',ARRAY['K5-1-u6-X03','K5-1-u6-X02','K5-1-u6-X01']::text[],false,'{"seq":6,"concept":"K5-1-u6-C3","difficulty":3,"kind":"mc","stem":"「친구가 반가웠다」를 「친구 얼굴이 봄 햇살 같았다」로 바꾸면 무엇이 달라지나요?","options":[{"t":"반가운 마음이 장면처럼 생생하게 전해진다","correct":true},{"t":"글이 짧아져 읽기 쉬워진다","mis":"K5-1-u6-X03"},{"t":"친구가 정말 햇살이 되었다는 뜻이 된다","mis":"K5-1-u6-X02"},{"t":"사실을 더 정확하게 알려 준다","mis":"K5-1-u6-X01"}],"explanation":["짧아지지 않았어요.","정말 햇살이 된 게 아니에요.","마음이 생생하게 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#7','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C7',3,'mc','auto','이 단원의 비유적 표현과 인상적인 부분이 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X07','K5-1-u6-X39']::text[],false,'{"seq":7,"concept":"K5-1-u6-C7","difficulty":3,"kind":"mc","stem":"이 단원의 비유적 표현과 인상적인 부분이 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작품 속 비유가 만든 장면이 마음에 남아 인상적인 부분이 될 수 있다","correct":true},{"t":"비유와 인상적인 부분은 서로 관계없다","mis":"K5-1-u6-X07"},{"t":"인상적인 부분에는 비유가 없어야 한다","mis":"K5-1-u6-X07"},{"t":"비유를 많이 찾을수록 인상적인 부분이 정해진다","mis":"K5-1-u6-X39"}],"explanation":["둘은 이어져요.","비유가 있어도 돼요.","비유가 만든 장면이 마음에 남을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#8','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C1',4,'essay','teacher','가까이 있는 물건 하나를 골라 다른 것에 빗대어 한 문장으로 쓰고, 두 대상의 비슷한 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C1","difficulty":4,"kind":"essay","stem":"가까이 있는 물건 하나를 골라 다른 것에 빗대어 한 문장으로 쓰고, 두 대상의 비슷한 점을 쓰세요.","answer_guide":{"answer":"예: 우리 반 시계는 쉬지 않는 달리기 선수다. 시곗바늘은 멈추지 않고 계속 돌아가고, 달리기 선수도 쉬지 않고 달린다는 점이 비슷하다.","scoring_points":["물건 하나를 골라 빗대어 썼는가","두 대상의 비슷한 점을 썼는가","실제로 그렇다는 말이 아니라 견주어 말한 것인가"]},"explanation":["무엇을 골랐나요?","무엇에 빗대었나요?","어떤 점이 닮았나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#9','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C3',4,'essay','teacher','소율이와 유담이의 말을 비유 없이 바꾸어 쓰고, 처음 말과 무엇이 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C3","difficulty":4,"kind":"essay","stem":"소율이와 유담이의 말을 비유 없이 바꾸어 쓰고, 처음 말과 무엇이 다른지 쓰세요.","answer_guide":{"answer":"예: 「발표할 때 얼굴이 빨개졌어.」, 「땀이 아주 많이 흘렀어.」로 바꿀 수 있다. 처음 말은 얼굴이 얼마나 빨갰는지, 땀이 얼마나 많았는지 모습이 눈앞에 떠올라 더 생생하고 느낌이 잘 전해진다.","scoring_points":["두 말을 비유 없이 바꾸어 썼는가","처음 말과 견주었는가","생생함이나 느낌의 차이를 썼는가"]},"explanation":["비유를 빼면 어떻게 되나요?","무엇이 사라지나요?","생생함을 견주어요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"아까 발표할 때 얼굴이 홍당무가 됐어."},{"who":"유담","text":"나는 운동장을 한 바퀴 돌았더니 땀이 폭포처럼 흘렀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L01_challenge#10','kor',5,1,'u6','L01','g5_1_kor_u6_L01_challenge','lesson_challenge','K5-1-u6-C6',4,'essay','teacher','최근에 읽은 책이나 본 영상에서 마음이 움직인 장면을 하나 떠올려 쓰고, 왜 그 장면이 마음에 남았는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C6","difficulty":4,"kind":"essay","stem":"최근에 읽은 책이나 본 영상에서 마음이 움직인 장면을 하나 떠올려 쓰고, 왜 그 장면이 마음에 남았는지 까닭을 쓰세요.","answer_guide":{"answer":"예: 동화에서 주인공이 잃어버린 강아지를 다시 찾는 장면이 마음에 남았다. 나도 고양이를 잃어버렸다가 찾은 적이 있어서 주인공의 기쁜 마음을 잘 알 것 같았다.","scoring_points":["장면을 하나 썼는가","마음에 남은 까닭을 썼는가","자기 경험이나 생각과 이어 썼는가"]},"explanation":["어떤 장면이었나요?","왜 마음이 움직였나요?","내 경험과 이어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#1','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C8',1,'mc','auto','시 「내 마음은 유리병」에서 표현하는 대상은 어느 것인가요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":1,"concept":"K5-1-u6-C8","difficulty":1,"kind":"mc","stem":"시 「내 마음은 유리병」에서 표현하는 대상은 어느 것인가요?","options":[{"t":"내 마음","correct":true},{"t":"유리병","mis":"K5-1-u6-X08"},{"t":"흙탕물","mis":"K5-1-u6-X08"},{"t":"맑은 물","mis":"K5-1-u6-X08"}],"explanation":["유리병은 빗댄 것이에요.","흙탕물은 시 속 장면이에요.","첫 행을 다시 읽어요."],"asset":{"type":"passage","lines":["내 마음은 유리병","속이 다 비쳐 보인다","기분 좋은 날에는 맑은 물이 찰랑이고","서운한 날에는 흙탕물이 가라앉지 못한다","누가 툭 건드리면 소리부터 먼저 난다","그래서 나는 잠들기 전에 병을 조용히 세워 둔다"],"title":"시 「내 마음은 유리병」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#2','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C9',1,'mc','auto','은유법으로 표현한 것은 어느 것인가요?',ARRAY['K5-1-u6-X09','K5-1-u6-X14']::text[],false,'{"seq":2,"concept":"K5-1-u6-C9","difficulty":1,"kind":"mc","stem":"은유법으로 표현한 것은 어느 것인가요?","options":[{"t":"교실은 작은 숲이다","correct":true},{"t":"교실이 숲처럼 시끄럽다","mis":"K5-1-u6-X09"},{"t":"교실에 나무 화분이 있다","mis":"K5-1-u6-X14"},{"t":"교실 창문이 활짝 열렸다","mis":"K5-1-u6-X14"}],"explanation":["「처럼」이 있으면 직유예요.","그냥 사실이에요.","바로 숲이라고 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#3','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C10',1,'mc','auto','직유법으로 표현한 것은 어느 것인가요?',ARRAY['K5-1-u6-X10','K5-1-u6-X14']::text[],false,'{"seq":3,"concept":"K5-1-u6-C10","difficulty":1,"kind":"mc","stem":"직유법으로 표현한 것은 어느 것인가요?","options":[{"t":"우산처럼 옆으로 기울어 주는 친구","correct":true},{"t":"내 마음은 유리병","mis":"K5-1-u6-X10"},{"t":"비 오는 날 우산을 썼다","mis":"K5-1-u6-X14"},{"t":"계단을 한 칸씩 올라갔다","mis":"K5-1-u6-X14"}],"explanation":["견주는 말이 없으면 은유예요.","있었던 일 그대로예요.","「처럼」으로 견주었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#4','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C11',1,'ox','auto','「우산 같은 친구」의 「같은」도 직유법에 쓰이는 견주는 말이에요.',ARRAY['K5-1-u6-X11']::text[],false,'{"seq":4,"concept":"K5-1-u6-C11","difficulty":1,"kind":"ox","stem":"「우산 같은 친구」의 「같은」도 직유법에 쓰이는 견주는 말이에요.","answer":"O","reason_options":[{"t":"두 대상을 직접 견주는 말이 겉으로 드러나 있기 때문에","correct":true},{"t":"직유법에는 같이 · 처럼 · 듯이 세 가지만 쓰이기 때문에","mis":"K5-1-u6-X11"}],"mis":"K5-1-u6-X11","explanation":["같은도 견주는 말이에요.","만큼도 견주는 말이에요.","세 가지만 있는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#5','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C12',2,'mc','auto','시 「나는 좋아」에서 친구를 우산에 빗댄 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X12']::text[],false,'{"seq":5,"concept":"K5-1-u6-C12","difficulty":2,"kind":"mc","stem":"시 「나는 좋아」에서 친구를 우산에 빗댄 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"제가 젖으면서도 남에게 기울어 주는 모습이 닮아서","correct":true},{"t":"우산과 친구는 둘 다 색이 예뻐서","mis":"K5-1-u6-X12"},{"t":"비 오는 날에만 친구를 만나서","mis":"K5-1-u6-X12"},{"t":"우산은 아무것에나 빗댈 수 있어서","mis":"K5-1-u6-X12"}],"explanation":["색 이야기는 없어요.","만나는 날과 관계없어요.","닮은 점이 있어 빗대었어요."],"asset":{"type":"passage","lines":["나는 우산이 좋아, 우산 같은 친구가 좋아","비 오는 날 말없이 옆으로 기울어 주는 우산처럼","제 어깨가 젖는 줄도 모르는 친구가 좋아","나는 계단이 좋아, 계단 같은 친구가 좋아","한 번에 데려다주지는 못해도","한 칸씩 같이 올라가 주는 친구가 좋아"],"title":"시 「나는 좋아」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#6','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C8',2,'mc','auto','시 「내 마음은 유리병」에서 마음과 유리병의 비슷한 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":6,"concept":"K5-1-u6-C8","difficulty":2,"kind":"mc","stem":"시 「내 마음은 유리병」에서 마음과 유리병의 비슷한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"속이 다 비쳐 보이고 건드리면 쉽게 흔들린다","correct":true},{"t":"둘 다 무겁고 단단하다","mis":"K5-1-u6-X04"},{"t":"둘 다 네모난 모양이다","mis":"K5-1-u6-X04"},{"t":"둘 다 물만 담을 수 있다","mis":"K5-1-u6-X04"}],"explanation":["시에 무겁다는 말은 없어요.","모양 이야기가 아니에요.","속이 비치고 쉽게 흔들려요."],"asset":{"type":"passage","lines":["내 마음은 유리병","속이 다 비쳐 보인다","기분 좋은 날에는 맑은 물이 찰랑이고","서운한 날에는 흙탕물이 가라앉지 못한다","누가 툭 건드리면 소리부터 먼저 난다","그래서 나는 잠들기 전에 병을 조용히 세워 둔다"],"title":"시 「내 마음은 유리병」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#7','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C14',2,'mc','auto','비유가 아닌 문장은 어느 것인가요?',ARRAY['K5-1-u6-X01']::text[],false,'{"seq":7,"concept":"K5-1-u6-C14","difficulty":2,"kind":"mc","stem":"비유가 아닌 문장은 어느 것인가요?","options":[{"t":"교실에 나무 화분이 있다","correct":true},{"t":"첫눈은 하늘이 보낸 편지다","mis":"K5-1-u6-X01"},{"t":"땀이 폭포처럼 흘렀다","mis":"K5-1-u6-X01"},{"t":"내 마음은 유리병","mis":"K5-1-u6-X01"}],"explanation":["첫눈을 편지에 빗대었어요.","땀을 폭포에 견주었어요.","빗댄 것이 없는 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#8','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C10',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「직유법은 같이나 처럼 같은 (　　)을 써서 두 대상을 직접 견주는 방법이다.」',ARRAY['K5-1-u6-X10']::text[],false,'{"seq":8,"concept":"K5-1-u6-C10","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「직유법은 같이나 처럼 같은 (　　)을 써서 두 대상을 직접 견주는 방법이다.」","options":[{"t":"견주는 말","correct":true},{"t":"이어 주는 말","mis":"K5-1-u6-X10"},{"t":"높임말","mis":"K5-1-u6-X10"},{"t":"흉내 내는 말","mis":"K5-1-u6-X10"}],"explanation":["이어 주는 말과 달라요.","높임과 관계없어요.","견주는 말이 겉으로 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#9','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C15',2,'match','auto','같은 비유를 쓴 방법과 그 느낌을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C15","difficulty":2,"kind":"match","stem":"같은 비유를 쓴 방법과 그 느낌을 알맞게 이으세요.","pairs":[{"l":"첫눈이 하늘이 보낸 편지처럼 내려앉았다","r":"조심스럽게 견준다"},{"l":"첫눈은 하늘이 보낸 편지다","r":"단번에 겹쳐 놓는다"},{"l":"첫눈이 내렸다","r":"빗대지 않고 사실만 말한다"}],"mis":"K5-1-u6-X15","explanation":["「처럼」은 견주어요.","은유는 단번에 겹쳐요.","빗대지 않은 문장도 있어요."],"asset":{"type":"passage","lines":["직유법으로 — 첫눈이 하늘이 보낸 편지처럼 내려앉았다","은유법으로 — 첫눈은 하늘이 보낸 편지다"],"title":"같은 비유, 다른 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_basic#10','kor',5,1,'u6','L02','g5_1_kor_u6_L02_basic','lesson_basic','K5-1-u6-C13',3,'mc','auto','꼴이 같은 두 문장 ㉮와 ㉯에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u6-X13','K5-1-u6-X14']::text[],false,'{"seq":10,"concept":"K5-1-u6-C13","difficulty":3,"kind":"mc","stem":"꼴이 같은 두 문장 ㉮와 ㉯에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"㉮는 사실이고, 서로 다른 두 대상을 겹쳐 놓은 ㉯만 비유이다","correct":true},{"t":"둘 다 같은 꼴이므로 둘 다 은유법이다","mis":"K5-1-u6-X13"},{"t":"둘 다 비유가 아니다","mis":"K5-1-u6-X14"},{"t":"㉮만 비유이고 ㉯는 사실이다","mis":"K5-1-u6-X13"}],"explanation":["꼴만 보고 정할 수 없어요.","㉯는 비유예요.","두 대상이 겹쳤는지 보아요."],"asset":{"type":"passage","lines":["㉮ 내 동생은 삼 학년이다","㉯ 내 동생은 작은 태풍이다"],"title":"꼴이 같은 두 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#1','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C16',2,'ox','auto','은유법과 직유법의 이름을 정확히 외우는 것이 이 공부의 가장 큰 목적이에요.',ARRAY['K5-1-u6-X16']::text[],false,'{"seq":1,"concept":"K5-1-u6-C16","difficulty":2,"kind":"ox","stem":"은유법과 직유법의 이름을 정확히 외우는 것이 이 공부의 가장 큰 목적이에요.","answer":"X","reason_options":[{"t":"시를 읽다가 겹쳐 놓은 표현을 알아보고 그 느낌을 감상하는 것이 먼저이기 때문에","correct":true},{"t":"이름을 모르면 시를 읽을 수 없기 때문에","mis":"K5-1-u6-X16"}],"mis":"K5-1-u6-X16","explanation":["이름이 목적이 아니에요.","알아보는 눈이 먼저예요.","느낌을 감상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#2','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C11',2,'mc','auto','직유법에 쓰이는 견주는 말로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u6-X11','K5-1-u6-X09']::text[],false,'{"seq":2,"concept":"K5-1-u6-C11","difficulty":2,"kind":"mc","stem":"직유법에 쓰이는 견주는 말로만 묶은 것은 어느 것인가요?","options":[{"t":"같이 · 처럼 · 듯이 · 같은 · 만큼","correct":true},{"t":"같이 · 처럼 · 그러나","mis":"K5-1-u6-X11"},{"t":"왜냐하면 · 그래서 · 처럼","mis":"K5-1-u6-X11"},{"t":"은 · 는 · 이다","mis":"K5-1-u6-X09"}],"explanation":["그러나는 견주는 말이 아니에요.","왜냐하면도 아니에요.","같은 · 만큼도 견주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#3','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C13',3,'mc','auto','「……은 ……이다」 꼴인 문장이 은유인지 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X13','K5-1-u6-X01']::text[],false,'{"seq":3,"concept":"K5-1-u6-C13","difficulty":3,"kind":"mc","stem":"「……은 ……이다」 꼴인 문장이 은유인지 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 다른 종류의 두 대상이 겹쳐졌는지 본다","correct":true},{"t":"꼴만 맞으면 모두 은유로 본다","mis":"K5-1-u6-X13"},{"t":"문장이 길면 은유로 본다","mis":"K5-1-u6-X13"},{"t":"어려운 낱말이 있으면 은유로 본다","mis":"K5-1-u6-X01"}],"explanation":["꼴이 같아도 사실일 수 있어요.","길이와 관계없어요.","두 대상이 겹쳤는지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#4','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C15',3,'mc','auto','「첫눈은 하늘이 보낸 편지다」를 직유법으로 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u6-X14','K5-1-u6-X15']::text[],false,'{"seq":4,"concept":"K5-1-u6-C15","difficulty":3,"kind":"mc","stem":"「첫눈은 하늘이 보낸 편지다」를 직유법으로 바꾼 것은 어느 것인가요?","options":[{"t":"첫눈이 하늘이 보낸 편지처럼 내려앉았다","correct":true},{"t":"첫눈은 하얗고 차갑다","mis":"K5-1-u6-X14"},{"t":"하늘이 첫눈에게 편지를 썼다","mis":"K5-1-u6-X15"},{"t":"첫눈은 편지가 아니다","mis":"K5-1-u6-X15"}],"explanation":["빗대지 않았어요.","뜻이 바뀌었어요.","견주는 말을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#5','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C12',3,'error','auto','시 「나는 좋아」를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X12','K5-1-u6-X11']::text[],false,'{"seq":5,"concept":"K5-1-u6-C12","difficulty":3,"kind":"error","stem":"시 「나는 좋아」를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「친구를 계단에 빗댄 것은 계단이 아무것에나 빗댈 수 있는 물건이기 때문이야.」","correct":true,"mis_target":"K5-1-u6-X12"},{"t":"「한 칸씩 같이 올라가 주는 모습이 계단과 닮았어.」","mis":"K5-1-u6-X12"},{"t":"「우산 같은 친구에는 견주는 말이 드러나 있어.」","mis":"K5-1-u6-X11"}],"explanation":["닮은 점을 바르게 찾았어요.","같은도 견주는 말이에요.","아무것에나 빗대지 않아요."],"asset":{"type":"passage","lines":["나는 우산이 좋아, 우산 같은 친구가 좋아","비 오는 날 말없이 옆으로 기울어 주는 우산처럼","제 어깨가 젖는 줄도 모르는 친구가 좋아","나는 계단이 좋아, 계단 같은 친구가 좋아","한 번에 데려다주지는 못해도","한 칸씩 같이 올라가 주는 친구가 좋아"],"title":"시 「나는 좋아」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#6','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C9',3,'mc','auto','「서운한 날에는 흙탕물이 가라앉지 못한다」가 전하는 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X18']::text[],false,'{"seq":6,"concept":"K5-1-u6-C9","difficulty":3,"kind":"mc","stem":"「서운한 날에는 흙탕물이 가라앉지 못한다」가 전하는 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"서운한 마음이 쉽게 가라앉지 않고 오래 흐려져 있다","correct":true},{"t":"유리병에 흙탕물을 담아 두었다","mis":"K5-1-u6-X18"},{"t":"서운한 날에는 물을 마시지 않는다","mis":"K5-1-u6-X18"},{"t":"서운한 마음은 금방 맑아진다","mis":"K5-1-u6-X18"}],"explanation":["글자 그대로 읽었어요.","물 마시는 이야기가 아니에요.","흐린 물처럼 마음이 흐려요."],"asset":{"type":"passage","lines":["내 마음은 유리병","속이 다 비쳐 보인다","기분 좋은 날에는 맑은 물이 찰랑이고","서운한 날에는 흙탕물이 가라앉지 못한다","누가 툭 건드리면 소리부터 먼저 난다","그래서 나는 잠들기 전에 병을 조용히 세워 둔다"],"title":"시 「내 마음은 유리병」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#7','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C10',3,'mc','auto','「친구 목소리가 종소리같이 맑다」와 「친구 목소리는 종소리다」의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X10','K5-1-u6-X14','K5-1-u6-X15']::text[],false,'{"seq":7,"concept":"K5-1-u6-C10","difficulty":3,"kind":"mc","stem":"「친구 목소리가 종소리같이 맑다」와 「친구 목소리는 종소리다」의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"앞 문장은 견주는 말이 드러난 직유법이고, 뒤 문장은 바로 그것이라고 말하는 은유법이다","correct":true},{"t":"앞 문장은 은유법이고 뒤 문장은 직유법이다","mis":"K5-1-u6-X10"},{"t":"둘 다 비유가 아니다","mis":"K5-1-u6-X14"},{"t":"두 문장은 방법도 느낌도 똑같다","mis":"K5-1-u6-X15"}],"explanation":["둘이 뒤바뀌었어요.","둘 다 비유예요.","견주는 말이 있는지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#8','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C15',4,'essay','teacher','친구를 다른 대상에 빗대어 직유법과 은유법으로 한 문장씩 쓰고, 그렇게 빗댄 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C15","difficulty":4,"kind":"essay","stem":"친구를 다른 대상에 빗대어 직유법과 은유법으로 한 문장씩 쓰고, 그렇게 빗댄 까닭을 쓰세요.","answer_guide":{"answer":"예: 직유법 — 내 짝은 난로처럼 따뜻하다. 은유법 — 내 짝은 겨울 교실의 난로다. 짝은 내가 속상할 때마다 먼저 말을 걸어 주어 마음을 따뜻하게 해 주기 때문에 난로에 빗대었다.","scoring_points":["직유법 문장을 썼는가","은유법 문장을 썼는가","빗댄 까닭을 썼는가"]},"explanation":["견주는 말을 넣어요.","바로 그것이라고 말해요.","닮은 점을 까닭으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#9','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C13',4,'essay','teacher','「우리 집 고양이는 세 살이다」와 「우리 집 고양이는 작은 자명종이다」 가운데 비유인 것을 고르고, 꼴이 아닌 기준으로 그렇게 판단한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C13","difficulty":4,"kind":"essay","stem":"「우리 집 고양이는 세 살이다」와 「우리 집 고양이는 작은 자명종이다」 가운데 비유인 것을 고르고, 꼴이 아닌 기준으로 그렇게 판단한 까닭을 쓰세요.","answer_guide":{"answer":"예: 「우리 집 고양이는 작은 자명종이다」가 비유이다. 두 문장 모두 같은 꼴이지만, 앞 문장은 고양이의 나이를 그대로 말한 사실이다. 뒤 문장은 고양이와 자명종이라는 서로 다른 두 대상을 겹쳐 놓았고, 아침마다 깨워 주는 모습이 닮았다.","scoring_points":["비유인 문장을 골랐는가","꼴이 같다는 점을 짚었는가","서로 다른 두 대상이 겹쳐졌는지로 판단했는가"]},"explanation":["꼴은 같아요.","하나는 사실이에요.","두 대상이 겹쳤는지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L02_challenge#10','kor',5,1,'u6','L02','g5_1_kor_u6_L02_challenge','lesson_challenge','K5-1-u6-C16',4,'essay','teacher','시 「내 마음은 유리병」에서 가장 마음에 닿는 비유적 표현을 하나 고르고, 그 표현이 어떤 느낌을 주는지 쓰세요. 비유 방법의 이름은 쓰지 않아도 됩니다.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C16","difficulty":4,"kind":"essay","stem":"시 「내 마음은 유리병」에서 가장 마음에 닿는 비유적 표현을 하나 고르고, 그 표현이 어떤 느낌을 주는지 쓰세요. 비유 방법의 이름은 쓰지 않아도 됩니다.","answer_guide":{"answer":"예: 「누가 툭 건드리면 소리부터 먼저 난다」가 마음에 닿았다. 누가 조금만 서운하게 해도 마음이 금방 흔들리고 티가 나는 모습이 유리병 소리처럼 들려서, 나도 그런 적이 있다는 생각이 들었다.","scoring_points":["비유적 표현을 하나 골랐는가","그 표현이 주는 느낌을 썼는가","이름보다 감상에 중심을 두었는가"]},"explanation":["어느 행이 닿았나요?","어떤 느낌인가요?","내 마음과 견주어요."],"asset":{"type":"passage","lines":["내 마음은 유리병","속이 다 비쳐 보인다","기분 좋은 날에는 맑은 물이 찰랑이고","서운한 날에는 흙탕물이 가라앉지 못한다","누가 툭 건드리면 소리부터 먼저 난다","그래서 나는 잠들기 전에 병을 조용히 세워 둔다"],"title":"시 「내 마음은 유리병」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#1','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C17',1,'mc','auto','시 「나는 아직 새벽」의 말하는 이는 지금 어떤 시기를 지나고 있나요?',ARRAY['K5-1-u6-X17']::text[],false,'{"seq":1,"concept":"K5-1-u6-C17","difficulty":1,"kind":"mc","stem":"시 「나는 아직 새벽」의 말하는 이는 지금 어떤 시기를 지나고 있나요?","options":[{"t":"아직 자라는 중인 시기","correct":true},{"t":"이미 다 자란 시기","mis":"K5-1-u6-X17"},{"t":"모든 것이 끝난 시기","mis":"K5-1-u6-X17"},{"t":"잠들기 바로 전의 시기","mis":"K5-1-u6-X17"}],"explanation":["한낮은 다 자란 때예요.","끝난 시기가 아니에요.","새벽은 날이 밝아 오는 중이에요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#2','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C21',1,'mc','auto','시를 낭송하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u6-X21']::text[],false,'{"seq":2,"concept":"K5-1-u6-C21","difficulty":1,"kind":"mc","stem":"시를 낭송하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"시의 낱말 수를 세며 낭송하기","correct":true},{"t":"친구와 번갈아 가며 낭송하기","mis":"K5-1-u6-X21"},{"t":"말하는 이의 마음을 상상하며 낭송하기","mis":"K5-1-u6-X21"},{"t":"어울리는 몸짓이나 표정으로 낭송하기","mis":"K5-1-u6-X21"}],"explanation":["번갈아 읽기도 방법이에요.","마음을 상상해도 좋아요.","낱말 수 세기는 낭송과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#3','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C22',1,'mc','auto','시를 낭송할 때 살려야 할 것은 어느 것인가요?',ARRAY['K5-1-u6-X22']::text[],false,'{"seq":3,"concept":"K5-1-u6-C22","difficulty":1,"kind":"mc","stem":"시를 낭송할 때 살려야 할 것은 어느 것인가요?","options":[{"t":"말하는 이의 마음","correct":true},{"t":"최대한 빠른 속도","mis":"K5-1-u6-X22"},{"t":"가장 큰 목소리","mis":"K5-1-u6-X22"},{"t":"시의 글자 수","mis":"K5-1-u6-X22"}],"explanation":["빠르기가 목표가 아니에요.","크기가 목표가 아니에요.","마음이 전해져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#4','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C25',1,'ox','auto','시는 한 번만 읽어도 뜻을 다 알 수 있으니 되풀이해 읽을 필요가 없어요.',ARRAY['K5-1-u6-X25']::text[],false,'{"seq":4,"concept":"K5-1-u6-C25","difficulty":1,"kind":"ox","stem":"시는 한 번만 읽어도 뜻을 다 알 수 있으니 되풀이해 읽을 필요가 없어요.","answer":"X","reason_options":[{"t":"여러 번 소리 내어 읽을수록 처음에 지나친 뜻이 보이기 때문에","correct":true},{"t":"시는 짧아서 한 번이면 충분하기 때문에","mis":"K5-1-u6-X25"}],"mis":"K5-1-u6-X25","explanation":["한 번에 끝나는 글이 아니에요.","혼자도 함께도 읽어요.","여러 번 읽을수록 더 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#5','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C18',2,'match','auto','시 「나는 아직 새벽」의 비유적 표현과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u6-C18","difficulty":2,"kind":"match","stem":"시 「나는 아직 새벽」의 비유적 표현과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"나는 아직 새벽","r":"아직 자라는 중이다"},{"l":"한낮이길 바라지","r":"빨리 다 자라기를 바란다"},{"l":"종달새처럼 크게 울게","r":"때가 되면 힘껏 나를 펼치겠다"}],"mis":"K5-1-u6-X18","explanation":["새벽은 하루의 처음이에요.","한낮은 다 자란 때예요.","때가 되면 힘껏 울어요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#6','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C19',2,'mc','auto','자라는 시기를 하루의 시간에 빗댄 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X19']::text[],false,'{"seq":6,"concept":"K5-1-u6-C19","difficulty":2,"kind":"mc","stem":"자라는 시기를 하루의 시간에 빗댄 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자라는 일은 차례대로 오고 건너뛸 수 없다는 점이 닮아서","correct":true},{"t":"하루는 아주 짧기 때문에","mis":"K5-1-u6-X19"},{"t":"새벽에는 날씨가 춥기 때문에","mis":"K5-1-u6-X19"},{"t":"시는 언제나 하루를 다루기 때문에","mis":"K5-1-u6-X19"}],"explanation":["짧아서가 아니에요.","날씨 이야기가 아니에요.","새벽 · 아침 · 한낮은 차례대로 와요."],"asset":{"type":"passage","lines":["새벽 — 아직 자라는 중인 지금","아침 — 조금 더 자란 뒤","한낮 — 다 자란 때"],"title":"하루의 시간에 빗댄 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#7','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C20',2,'mc','auto','어른들이 벌써 한낮이길 바랄 때 말하는 이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X20']::text[],false,'{"seq":7,"concept":"K5-1-u6-C20","difficulty":2,"kind":"mc","stem":"어른들이 벌써 한낮이길 바랄 때 말하는 이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"재촉받는 것이 서운하고 답답하다","correct":true},{"t":"빨리 자라게 되어 신난다","mis":"K5-1-u6-X20"},{"t":"아무런 느낌이 없다","mis":"K5-1-u6-X20"},{"t":"어른들이 고마워서 기쁘다","mis":"K5-1-u6-X20"}],"explanation":["신나는 마음이 아니에요.","마음이 드러나 있어요.","「하지만」 뒤를 보아요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#8','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C24',2,'mc','auto','시 「나는 아직 새벽」에 어울리는 낭송 방법은 어느 것인가요?',ARRAY['K5-1-u6-X24','K5-1-u6-X23']::text[],false,'{"seq":8,"concept":"K5-1-u6-C24","difficulty":2,"kind":"mc","stem":"시 「나는 아직 새벽」에 어울리는 낭송 방법은 어느 것인가요?","options":[{"t":"차분하게, 되풀이되는 말을 조용히 되뇌듯이","correct":true},{"t":"힘차게 외치듯 크고 빠르게","mis":"K5-1-u6-X24"},{"t":"우스꽝스러운 목소리로","mis":"K5-1-u6-X24"},{"t":"한 번에 숨도 쉬지 않고","mis":"K5-1-u6-X23"}],"explanation":["외치는 시가 아니에요.","우스운 시가 아니에요.","스스로를 다독이는 시예요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#9','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C23',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「되풀이되는 말은 조금 더 천천히, 마음이 실린 말은 한 박자 (　　) 읽는다.」',ARRAY['K5-1-u6-X23','K5-1-u6-X22']::text[],false,'{"seq":9,"concept":"K5-1-u6-C23","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「되풀이되는 말은 조금 더 천천히, 마음이 실린 말은 한 박자 (　　) 읽는다.」","options":[{"t":"쉬고","correct":true},{"t":"빠르게","mis":"K5-1-u6-X23"},{"t":"크게 외치며","mis":"K5-1-u6-X22"},{"t":"건너뛰고","mis":"K5-1-u6-X23"}],"explanation":["빨리 읽지 않아요.","외치지 않아요.","한 박자 쉬면 힘이 실려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_basic#10','kor',5,1,'u6','L04','g5_1_kor_u6_L04_basic','lesson_basic','K5-1-u6-C23',3,'mc','auto','㉮와 ㉯처럼 읽을 때 달라지는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X23']::text[],false,'{"seq":10,"concept":"K5-1-u6-C23","difficulty":3,"kind":"mc","stem":"㉮와 ㉯처럼 읽을 때 달라지는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"㉯처럼 끊어 읽으면 「아직」이라는 말에 힘이 실린다","correct":true},{"t":"㉮와 ㉯는 느낌이 똑같다","mis":"K5-1-u6-X23"},{"t":"끊어 읽으면 시의 뜻이 틀려진다","mis":"K5-1-u6-X23"},{"t":"㉮처럼 쉬지 않고 읽어야 잘 읽는 것이다","mis":"K5-1-u6-X23"}],"explanation":["쉬는 곳에 따라 달라져요.","뜻이 틀려지지 않아요.","쉬는 곳에 힘이 실려요."],"asset":{"type":"passage","lines":["㉮ 하지만 나는 아직 새벽 날이 밝아 오는 중이야","㉯ 하지만 나는 아직 새벽 / 날이 밝아 오는 중이야"],"title":"두 가지로 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#1','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C26',2,'ox','auto','시를 감상할 때 나와 관련지어 보는 것은 시를 잘못 읽는 일이에요.',ARRAY['K5-1-u6-X26']::text[],false,'{"seq":1,"concept":"K5-1-u6-C26","difficulty":2,"kind":"ox","stem":"시를 감상할 때 나와 관련지어 보는 것은 시를 잘못 읽는 일이에요.","answer":"X","reason_options":[{"t":"지금의 나를 무엇에 빗댈지 떠올리면 시가 내 이야기가 되기 때문에","correct":true},{"t":"시는 말하는 이의 이야기일 뿐이기 때문에","mis":"K5-1-u6-X26"}],"mis":"K5-1-u6-X26","explanation":["나와 이어도 좋아요.","지금의 나를 떠올려요.","시가 내 이야기가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#2','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C21',2,'mc','auto','「친구와 번갈아 가며 낭송하기」를 할 때 알맞은 모습은 어느 것인가요?',ARRAY['K5-1-u6-X22','K5-1-u6-X21']::text[],false,'{"seq":2,"concept":"K5-1-u6-C21","difficulty":2,"kind":"mc","stem":"「친구와 번갈아 가며 낭송하기」를 할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"연이나 행을 나누어 맡아 서로 이어 가며 읽는다","correct":true},{"t":"두 사람이 누가 더 크게 읽는지 겨룬다","mis":"K5-1-u6-X22"},{"t":"한 사람만 읽고 한 사람은 쉰다","mis":"K5-1-u6-X21"},{"t":"서로 다른 시를 동시에 읽는다","mis":"K5-1-u6-X21"}],"explanation":["겨루기가 아니에요.","둘 다 읽어요.","같은 시를 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#3','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C20',3,'mc','auto','「하지만 나는 아직 새벽」을 되풀이한 데서 알 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u6-X20','K5-1-u6-X03']::text[],false,'{"seq":3,"concept":"K5-1-u6-C20","difficulty":3,"kind":"mc","stem":"「하지만 나는 아직 새벽」을 되풀이한 데서 알 수 있는 것은 어느 것인가요?","options":[{"t":"재촉에 흔들리지 않고 스스로를 다독이는 마음","correct":true},{"t":"새벽이 빨리 끝나기를 바라는 마음","mis":"K5-1-u6-X20"},{"t":"어른들 말을 그대로 따르겠다는 마음","mis":"K5-1-u6-X20"},{"t":"시를 길게 늘이려는 마음","mis":"K5-1-u6-X03"}],"explanation":["서두르는 마음이 아니에요.","따르겠다는 말이 아니에요.","되풀이하며 스스로를 다독여요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#4','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C18',3,'mc','auto','「너무 크게 울어서 모두 깨울지도 몰라」에 담긴 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X18']::text[],false,'{"seq":4,"concept":"K5-1-u6-C18","difficulty":3,"kind":"mc","stem":"「너무 크게 울어서 모두 깨울지도 몰라」에 담긴 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"때가 되면 누구보다 힘껏 자신을 펼칠 것이라는 자신감","correct":true},{"t":"아침마다 시끄럽게 떠들겠다는 다짐","mis":"K5-1-u6-X18"},{"t":"종달새를 기르고 싶은 마음","mis":"K5-1-u6-X18"},{"t":"잠을 자기 싫은 마음","mis":"K5-1-u6-X18"}],"explanation":["글자 그대로 읽었어요.","새를 기르는 이야기가 아니에요.","힘껏 펼치겠다는 마음이에요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#5','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C25',3,'error','auto','낭송에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X25','K5-1-u6-X24']::text[],false,'{"seq":5,"concept":"K5-1-u6-C25","difficulty":3,"kind":"error","stem":"낭송에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「낭송은 마지막에 한 번 잘 읽으면 되니 연습하며 읽어 본 과정은 중요하지 않아.」","correct":true,"mis_target":"K5-1-u6-X25"},{"t":"「혼자도 읽고 함께도 읽으면 새로운 뜻이 보여.」","mis":"K5-1-u6-X25"},{"t":"「분위기를 생각하며 여러 번 읽어 보자.」","mis":"K5-1-u6-X24"}],"explanation":["되풀이해 읽기는 좋아요.","분위기를 살펴 읽어요.","낭송은 과정이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#6','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C22',3,'mc','auto','「나는 아직 새벽」을 낭송할 때 가장 살려야 할 것은 어느 것인가요?',ARRAY['K5-1-u6-X22']::text[],false,'{"seq":6,"concept":"K5-1-u6-C22","difficulty":3,"kind":"mc","stem":"「나는 아직 새벽」을 낭송할 때 가장 살려야 할 것은 어느 것인가요?","options":[{"t":"되풀이되는 「아직 새벽」의 리듬과 말하는 이의 마음","correct":true},{"t":"누구보다 빠르게 읽는 속도","mis":"K5-1-u6-X22"},{"t":"반에서 가장 큰 목소리","mis":"K5-1-u6-X22"},{"t":"시에 쓰인 글자의 수","mis":"K5-1-u6-X22"}],"explanation":["빠르기가 아니에요.","크기가 아니에요.","리듬과 마음을 살려요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#7','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C19',3,'mc','auto','시 「나는 아직 새벽」의 말하는 이가 바라는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X19','K5-1-u6-X17','K5-1-u6-X20']::text[],false,'{"seq":7,"concept":"K5-1-u6-C19","difficulty":3,"kind":"mc","stem":"시 「나는 아직 새벽」의 말하는 이가 바라는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자라는 차례를 건너뛰지 않고 제때를 기다려 주는 것","correct":true},{"t":"지금 당장 한낮처럼 다 자라는 것","mis":"K5-1-u6-X19"},{"t":"새벽이 영원히 이어지는 것","mis":"K5-1-u6-X17"},{"t":"어른들이 아무 말도 하지 않는 것","mis":"K5-1-u6-X20"}],"explanation":["서두르지 않아요.","한낮도 기다리고 있어요.","차례대로 자라고 싶어 해요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#8','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C26',4,'essay','teacher','지금의 나를 하루의 시간이나 다른 대상에 빗대어 한 문장으로 쓰고, 그렇게 빗댄 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C26","difficulty":4,"kind":"essay","stem":"지금의 나를 하루의 시간이나 다른 대상에 빗대어 한 문장으로 쓰고, 그렇게 빗댄 까닭을 쓰세요.","answer_guide":{"answer":"예: 나는 지금 봄날의 꽃봉오리다. 아직 활짝 피지는 않았지만 조금씩 부풀어 오르며 필 준비를 하고 있기 때문이다.","scoring_points":["나를 무엇에 빗대어 썼는가","빗댄 까닭을 썼는가","지금의 나에 대한 생각이 드러났는가"]},"explanation":["지금의 나는 어떤가요?","무엇과 닮았나요?","까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#9','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C21',4,'essay','teacher','「나는 아직 새벽」을 낭송한다면 네 가지 방법 가운데 어떤 방법을 고를지 쓰고, 그 방법을 고른 까닭을 시의 내용과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C21","difficulty":4,"kind":"essay","stem":"「나는 아직 새벽」을 낭송한다면 네 가지 방법 가운데 어떤 방법을 고를지 쓰고, 그 방법을 고른 까닭을 시의 내용과 이어 쓰세요.","answer_guide":{"answer":"예: 말하는 이의 마음을 상상하며 낭송하겠다. 어른들의 재촉에 서운하면서도 스스로 아직 새벽이라고 다독이는 마음이 이 시의 중심이어서, 그 마음을 떠올리며 되풀이되는 말을 차분하게 읽고 싶다.","scoring_points":["방법 하나를 골랐는가","고른 까닭을 썼는가","시의 내용과 이어 썼는가"]},"explanation":["네 방법을 떠올려요.","왜 그 방법인가요?","시의 마음과 이어요."],"asset":{"type":"passage","lines":["창문이 조금씩 밝아지고 있어","나는 아직 새벽","어른들은 벌써 내가 한낮이길 바라지","하지만 나는 아직 새벽 날이 밝아 오는 중이야","아침이 오면 종달새처럼 크게 울게","너무 크게 울어서 모두 깨울지도 몰라","한낮, 나도 기다리고 있어","다만 나는 아직 새벽 날이 밝아 오는 중"],"title":"시 「나는 아직 새벽」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L04_challenge#10','kor',5,1,'u6','L04','g5_1_kor_u6_L04_challenge','lesson_challenge','K5-1-u6-C23',4,'essay','teacher','「다만 나는 아직 새벽 날이 밝아 오는 중」을 어디서 끊어 읽을지 정하고, 그렇게 읽으면 어떤 말에 힘이 실리는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C23","difficulty":4,"kind":"essay","stem":"「다만 나는 아직 새벽 날이 밝아 오는 중」을 어디서 끊어 읽을지 정하고, 그렇게 읽으면 어떤 말에 힘이 실리는지 쓰세요.","answer_guide":{"answer":"예: 「새벽」 뒤에서 끊어 「다만 나는 아직 새벽 / 날이 밝아 오는 중」으로 읽겠다. 그러면 「아직 새벽」에 힘이 실려 나는 아직 자라는 중이라는 마음이 또렷하게 전해진다.","scoring_points":["끊어 읽을 곳을 정했는가","힘이 실리는 말을 썼는가","그 효과를 시의 뜻과 이어 썼는가"]},"explanation":["어디서 쉴까요?","어떤 말이 또렷해지나요?","시의 뜻과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#1','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C27',1,'mc','auto','시로 쓰기 좋은 대상은 어느 것인가요?',ARRAY['K5-1-u6-X27']::text[],false,'{"seq":1,"concept":"K5-1-u6-C27","difficulty":1,"kind":"mc","stem":"시로 쓰기 좋은 대상은 어느 것인가요?","options":[{"t":"밤에 혼자 켜져 있는 가로등","correct":true},{"t":"한 번도 본 적 없는 물건","mis":"K5-1-u6-X27"},{"t":"친구가 털어놓은 비밀","mis":"K5-1-u6-X27"},{"t":"사전에서 찾은 어려운 낱말","mis":"K5-1-u6-X27"}],"explanation":["본 적 없으면 특징을 몰라요.","비밀은 지켜 주어요.","직접 보고 겪은 것이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#2','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C29',1,'mc','auto','가로등의 특징 가운데 눈에 보이지 않는 특징은 어느 것인가요?',ARRAY['K5-1-u6-X29']::text[],false,'{"seq":2,"concept":"K5-1-u6-C29","difficulty":1,"kind":"mc","stem":"가로등의 특징 가운데 눈에 보이지 않는 특징은 어느 것인가요?","options":[{"t":"아무도 봐 주지 않아도 밤새 켜져 있다","correct":true},{"t":"기둥이 길고 위에 등이 달려 있다","mis":"K5-1-u6-X29"},{"t":"몸통이 회색이다","mis":"K5-1-u6-X29"},{"t":"키가 어른보다 크다","mis":"K5-1-u6-X29"}],"explanation":["사진으로 찍을 수 있어요.","색은 보여요.","하는 일과 태도는 보이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#3','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C30',1,'mc','auto','비유를 만들 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['K5-1-u6-X30']::text[],false,'{"seq":3,"concept":"K5-1-u6-C30","difficulty":1,"kind":"mc","stem":"비유를 만들 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"시로 쓸 대상을 정한다","correct":true},{"t":"비유적 표현을 먼저 완성한다","mis":"K5-1-u6-X30"},{"t":"빗댈 대상부터 고른다","mis":"K5-1-u6-X30"},{"t":"친구에게 감상 쪽지를 받는다","mis":"K5-1-u6-X30"}],"explanation":["표현은 마지막이에요.","빗댈 것은 특징을 본 뒤에 정해요.","대상부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#4','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C32',1,'ox','auto','시에 비유를 많이 넣을수록 좋은 시가 돼요.',ARRAY['K5-1-u6-X32']::text[],false,'{"seq":4,"concept":"K5-1-u6-C32","difficulty":1,"kind":"ox","stem":"시에 비유를 많이 넣을수록 좋은 시가 돼요.","answer":"X","reason_options":[{"t":"대상의 특징이 잘 드러나는 비유 하나가 흩어진 비유 여럿보다 오래 남기 때문에","correct":true},{"t":"비유가 많을수록 시가 화려해지기 때문에","mis":"K5-1-u6-X32"}],"mis":"K5-1-u6-X32","explanation":["많다고 좋은 게 아니에요.","흩어지면 흐려져요.","잘 드러나는 하나가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#5','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C31',2,'match','auto','대상과 어울리는 비유를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u6-C31","difficulty":2,"kind":"match","stem":"대상과 어울리는 비유를 알맞게 이으세요.","pairs":[{"l":"매미 소리","r":"여름을 켜는 스위치"},{"l":"지하철","r":"땅속을 헤엄치는 물고기"},{"l":"기다리는 마음","r":"늘어나는 고무줄"}],"mis":"K5-1-u6-X31","explanation":["매미가 울면 여름이 시작돼요.","땅속을 달려요.","기다릴수록 늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#6','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C31',2,'mc','auto','비슷한 점이 잘 드러난 비유는 어느 것인가요?',ARRAY['K5-1-u6-X31']::text[],false,'{"seq":6,"concept":"K5-1-u6-C31","difficulty":2,"kind":"mc","stem":"비슷한 점이 잘 드러난 비유는 어느 것인가요?","options":[{"t":"기다리는 마음은 자꾸 늘어나는 고무줄이다","correct":true},{"t":"기다리는 마음은 의자다","mis":"K5-1-u6-X31"},{"t":"기다리는 마음은 숫자 칠이다","mis":"K5-1-u6-X31"},{"t":"기다리는 마음은 아주 길고 화려한 무지갯빛 궁전이다","mis":"K5-1-u6-X31"}],"explanation":["닮은 점을 말하기 어려워요.","까닭을 댈 수 없어요.","늘어나는 모습이 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#7','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C28',2,'mc','auto','「가로등 살펴보기」의 「늦게 학원에서 돌아오던 길」은 무엇을 떠올린 것인가요?',ARRAY['K5-1-u6-X28','K5-1-u6-X30']::text[],false,'{"seq":7,"concept":"K5-1-u6-C28","difficulty":2,"kind":"mc","stem":"「가로등 살펴보기」의 「늦게 학원에서 돌아오던 길」은 무엇을 떠올린 것인가요?","options":[{"t":"대상과 관련한 경험","correct":true},{"t":"대상의 겉모습","mis":"K5-1-u6-X28"},{"t":"비유할 대상","mis":"K5-1-u6-X30"},{"t":"감상 쪽지","mis":"K5-1-u6-X28"}],"explanation":["겉모습이 아니에요.","빗댈 것이 아니에요.","겪은 일을 떠올렸어요."],"asset":{"type":"passage","lines":["대상 — 가로등","대상의 특징 — 밤새 혼자 켜져 있다 · 아무도 봐 주지 않아도 켜진다","관련한 경험 — 늦게 학원에서 돌아오던 길, 가로등만 나를 따라왔다","생각이나 느낌 — 혼자 있는 것이 덜 무서웠다"],"title":"가로등 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#8','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C33',2,'mc','auto','감상 쪽지에 담으면 좋은 것은 어느 것인가요?',ARRAY['K5-1-u6-X33']::text[],false,'{"seq":8,"concept":"K5-1-u6-C33","difficulty":2,"kind":"mc","stem":"감상 쪽지에 담으면 좋은 것은 어느 것인가요?","options":[{"t":"어느 표현이 왜 좋았는지와 더 좋은 생각","correct":true},{"t":"친구 시에 매긴 점수","mis":"K5-1-u6-X33"},{"t":"시의 글자 수","mis":"K5-1-u6-X33"},{"t":"친구의 글씨가 예쁜지","mis":"K5-1-u6-X33"}],"explanation":["점수를 매기는 쪽지가 아니에요.","글자 수와 관계없어요.","다음 시를 돕는 쪽지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#9','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C27',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「시는 거창하거나 화려한 말이 아니라 (　　)에서 온다.」',ARRAY['K5-1-u6-X27']::text[],false,'{"seq":9,"concept":"K5-1-u6-C27","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「시는 거창하거나 화려한 말이 아니라 (　　)에서 온다.」","options":[{"t":"겪은 일","correct":true},{"t":"어려운 낱말","mis":"K5-1-u6-X27"},{"t":"남의 시","mis":"K5-1-u6-X27"},{"t":"사전","mis":"K5-1-u6-X27"}],"explanation":["어려운 말이 아니에요.","남의 시를 옮기지 않아요.","내가 겪은 일에서 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_basic#10','kor',5,1,'u6','L06','g5_1_kor_u6_L06_basic','lesson_basic','K5-1-u6-C30',3,'mc','auto','「비유를 만드는 차례」에서 ㉣ 비슷한 점이 하는 구실로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X29','K5-1-u6-X30','K5-1-u6-X12']::text[],false,'{"seq":10,"concept":"K5-1-u6-C30","difficulty":3,"kind":"mc","stem":"「비유를 만드는 차례」에서 ㉣ 비슷한 점이 하는 구실로 알맞은 것은 어느 것인가요?","options":[{"t":"가로등을 등대에 빗댄 까닭이 된다","correct":true},{"t":"가로등의 색을 알려 준다","mis":"K5-1-u6-X29"},{"t":"시의 제목이 된다","mis":"K5-1-u6-X30"},{"t":"비유를 하지 않아도 되게 한다","mis":"K5-1-u6-X12"}],"explanation":["색은 겉모습이에요.","제목이 아니에요.","닮은 점이 빗댄 까닭이에요."],"asset":{"type":"passage","lines":["㉠ 시로 쓸 대상 — 가로등","㉡ 대상의 특징 — 밤새 혼자 불을 켜고 서 있다","㉢ 비유할 대상 — 등대","㉣ 비슷한 점 — 어둠 속에서 길을 잃지 않게 해 준다","㉤ 비유적 표현 — 가로등은 골목을 지키는 등대다"],"title":"비유를 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#1','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C34',2,'ox','auto','친구와 같은 대상을 골랐다면 같은 것에 빗대어야 해요.',ARRAY['K5-1-u6-X34']::text[],false,'{"seq":1,"concept":"K5-1-u6-C34","difficulty":2,"kind":"ox","stem":"친구와 같은 대상을 골랐다면 같은 것에 빗대어야 해요.","answer":"X","reason_options":[{"t":"같은 대상도 무엇에 빗대는지는 사람마다 다르고, 그 차이가 그 사람의 눈이기 때문에","correct":true},{"t":"빗댈 것은 대상마다 하나로 정해져 있기 때문에","mis":"K5-1-u6-X34"}],"mis":"K5-1-u6-X34","explanation":["정해진 비유는 없어요.","사람마다 보는 눈이 달라요.","다르게 빗대도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#2','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C29',2,'mc','auto','가로등의 보이지 않는 특징을 살피는 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X29']::text[],false,'{"seq":2,"concept":"K5-1-u6-C29","difficulty":2,"kind":"mc","stem":"가로등의 보이지 않는 특징을 살피는 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"가로등은 밤에 무엇을 해 주나요?","correct":true},{"t":"가로등은 무슨 색인가요?","mis":"K5-1-u6-X29"},{"t":"가로등 기둥은 얼마나 긴가요?","mis":"K5-1-u6-X29"},{"t":"가로등 등은 어떤 모양인가요?","mis":"K5-1-u6-X29"}],"explanation":["색은 보여요.","길이도 보여요.","하는 일을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#3','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C32',3,'mc','auto','두 시 ㉮와 ㉯를 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u6-X32','K5-1-u6-X14']::text[],false,'{"seq":3,"concept":"K5-1-u6-C32","difficulty":3,"kind":"mc","stem":"두 시 ㉮와 ㉯를 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"㉯는 비유 하나로 가로등의 특징을 밀고 가서 더 오래 남는다","correct":true},{"t":"㉮가 비유를 더 많이 넣었으니 더 좋은 시다","mis":"K5-1-u6-X32"},{"t":"㉮와 ㉯에는 비유가 없다","mis":"K5-1-u6-X14"},{"t":"㉯는 비유가 하나뿐이라 아쉬운 시다","mis":"K5-1-u6-X32"}],"explanation":["많다고 좋은 게 아니에요.","둘 다 비유가 있어요.","하나로 밀고 가면 오래 남아요."],"asset":{"type":"passage","lines":["㉮ 가로등은 등대이고 별이고 보초이고 손전등이고 달이다","㉯ 가로등은 골목을 지키는 등대 / 밤새 혼자 서서 길을 밝힌다"],"title":"두 시의 첫 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#4','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C31',3,'mc','auto','좋은 비유의 조건으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u6-X31']::text[],false,'{"seq":4,"concept":"K5-1-u6-C31","difficulty":3,"kind":"mc","stem":"좋은 비유의 조건으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"아무도 생각하지 못할 만큼 뜻이 어렵다","correct":true},{"t":"두 대상 사이에 비슷한 점이 있다","mis":"K5-1-u6-X31"},{"t":"그렇게 빗댄 까닭을 말할 수 있다","mis":"K5-1-u6-X31"},{"t":"담고 싶은 뜻이나 마음이 함께 전해진다","mis":"K5-1-u6-X31"}],"explanation":["비슷한 점은 조건이에요.","까닭도 조건이에요.","어렵기만 하면 닿지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#5','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C33',3,'error','auto','감상 쪽지 ㉮와 ㉯에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X33']::text[],false,'{"seq":5,"concept":"K5-1-u6-C33","difficulty":3,"kind":"error","stem":"감상 쪽지 ㉮와 ㉯에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「쪽지 ㉮처럼 짧게 칭찬만 하면 친구가 다음 시를 쓰는 데 가장 도움이 돼.」","correct":true,"mis_target":"K5-1-u6-X33"},{"t":"「쪽지 ㉯는 어느 표현이 왜 좋았는지 적었어.」","mis":"K5-1-u6-X33"},{"t":"「쪽지 ㉯는 더 좋은 생각도 함께 적어 주었어.」","mis":"K5-1-u6-X33"}],"explanation":["㉯는 표현과 까닭을 적었어요.","더 좋은 생각도 있어요.","칭찬만으로는 다음 시를 돕기 어려워요."],"asset":{"type":"passage","lines":["쪽지 ㉮ — 잘 썼어. 좋다.","쪽지 ㉯ — 기다리는 마음을 늘어나는 고무줄에 빗대니 조마조마한 느낌이 생생했어.","고무줄이 끊어질 뻔한 장면도 있으면 좋겠어."],"title":"친구의 시에 붙인 감상 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#6','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C28',3,'mc','auto','시 「가로등」의 「내 그림자를 앞으로 밀어 주었다가 다시 뒤로 데려간다」는 무엇을 살려 쓴 것인가요?',ARRAY['K5-1-u6-X29','K5-1-u6-X28','K5-1-u6-X27']::text[],false,'{"seq":6,"concept":"K5-1-u6-C28","difficulty":3,"kind":"mc","stem":"시 「가로등」의 「내 그림자를 앞으로 밀어 주었다가 다시 뒤로 데려간다」는 무엇을 살려 쓴 것인가요?","options":[{"t":"학원에서 돌아오던 길에 겪은 일과 그때의 느낌","correct":true},{"t":"가로등의 회색 몸통","mis":"K5-1-u6-X29"},{"t":"등대의 생김새","mis":"K5-1-u6-X28"},{"t":"친구의 비밀","mis":"K5-1-u6-X27"}],"explanation":["겉모습이 아니에요.","등대 모양 이야기가 아니에요.","겪은 일을 살렸어요."],"asset":{"type":"passage","lines":["가로등은 골목을 지키는 등대","배 한 척 지나가지 않는 밤에도 혼자 불을 켜 둔다","학원 끝나고 돌아오는 길","내 그림자를 앞으로 밀어 주었다가 다시 뒤로 데려간다","아무도 고맙다고 하지 않는데","오늘도 골목 끝에 서 있다"],"title":"시 「가로등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#7','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C27',3,'mc','auto','시로 쓸 대상을 고르는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X27','K5-1-u6-X28']::text[],false,'{"seq":7,"concept":"K5-1-u6-C27","difficulty":3,"kind":"mc","stem":"시로 쓸 대상을 고르는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 직접 겪어서 특징을 오래 들여다볼 수 있는 것을 고른다","correct":true},{"t":"남들이 놀랄 만큼 거창한 것만 고른다","mis":"K5-1-u6-X27"},{"t":"한 번도 본 적 없는 것을 상상해 고른다","mis":"K5-1-u6-X27"},{"t":"특징을 떠올리지 않아도 되는 것을 고른다","mis":"K5-1-u6-X28"}],"explanation":["거창할 필요가 없어요.","본 적 없으면 특징을 몰라요.","오래 들여다볼 수 있는 것이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#8','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C30',4,'essay','teacher','시로 쓸 대상을 하나 골라 대상, 특징, 비유할 대상, 비슷한 점, 비유적 표현의 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C30","difficulty":4,"kind":"essay","stem":"시로 쓸 대상을 하나 골라 대상, 특징, 비유할 대상, 비슷한 점, 비유적 표현의 차례대로 쓰세요.","answer_guide":{"answer":"예: 대상 — 운동화. 특징 — 내가 가는 곳은 어디든 같이 가 주고, 밑창이 닳아도 불평하지 않는다. 비유할 대상 — 그림자. 비슷한 점 — 늘 나를 따라다닌다. 비유적 표현 — 내 운동화는 발밑의 그림자다.","scoring_points":["다섯 단계를 차례대로 썼는가","특징에 보이지 않는 특징이 들어 있는가","비슷한 점이 비유를 뒷받침하는가"]},"explanation":["대상부터 정해요.","보이지 않는 특징도 살펴요.","닮은 점으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#9','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C32',4,'essay','teacher','「비유는 많을수록 좋은 것이 아니다」라는 말이 무슨 뜻인지 두 시 ㉮와 ㉯를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C32","difficulty":4,"kind":"essay","stem":"「비유는 많을수록 좋은 것이 아니다」라는 말이 무슨 뜻인지 두 시 ㉮와 ㉯를 예로 들어 쓰세요.","answer_guide":{"answer":"예: ㉮는 가로등을 등대 · 별 · 보초 · 손전등 · 달에 빗대어 비유가 많지만 무엇이 닮았는지 흩어져 버린다. ㉯는 등대 하나에 빗대고 밤새 길을 밝힌다는 특징을 밀고 가서 가로등의 모습이 오래 남는다. 비유를 많이 넣기보다 특징이 잘 드러나는 비유 하나를 고르는 것이 중요하다.","scoring_points":["㉮의 아쉬운 점을 썼는가","㉯의 좋은 점을 썼는가","비유 하나가 오래 남는다는 뜻을 썼는가"]},"explanation":["㉮는 비유가 몇 개인가요?","㉯는 무엇을 밀고 가나요?","무엇이 오래 남나요?"],"asset":{"type":"passage","lines":["㉮ 가로등은 등대이고 별이고 보초이고 손전등이고 달이다","㉯ 가로등은 골목을 지키는 등대 / 밤새 혼자 서서 길을 밝힌다"],"title":"두 시의 첫 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L06_challenge#10','kor',5,1,'u6','L06','g5_1_kor_u6_L06_challenge','lesson_challenge','K5-1-u6-C33',4,'essay','teacher','시 「가로등」에 감상 쪽지를 쓰세요. 어느 표현이 왜 좋았는지와 더 좋은 생각을 함께 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C33","difficulty":4,"kind":"essay","stem":"시 「가로등」에 감상 쪽지를 쓰세요. 어느 표현이 왜 좋았는지와 더 좋은 생각을 함께 넣으세요.","answer_guide":{"answer":"예: 「내 그림자를 앞으로 밀어 주었다가 다시 뒤로 데려간다」가 좋았어. 가로등 밑을 지날 때 그림자가 길어졌다 짧아지는 모습이 가로등이 나를 데리고 걷는 것처럼 느껴졌거든. 마지막에 내가 가로등에게 하고 싶은 말이 한 줄 있으면 더 좋겠어.","scoring_points":["좋았던 표현을 골랐는가","왜 좋았는지 썼는가","더 좋은 생각을 적었는가"]},"explanation":["어느 표현인가요?","왜 좋았나요?","더하면 좋을 생각을 적어요."],"asset":{"type":"passage","lines":["가로등은 골목을 지키는 등대","배 한 척 지나가지 않는 밤에도 혼자 불을 켜 둔다","학원 끝나고 돌아오는 길","내 그림자를 앞으로 밀어 주었다가 다시 뒤로 데려간다","아무도 고맙다고 하지 않는데","오늘도 골목 끝에 서 있다"],"title":"시 「가로등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#1','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C35',1,'mc','auto','이야기 「할머니의 라디오」에서 라디오 소리가 거슬리지 않게 된 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X35']::text[],false,'{"seq":1,"concept":"K5-1-u6-C35","difficulty":1,"kind":"mc","stem":"이야기 「할머니의 라디오」에서 라디오 소리가 거슬리지 않게 된 까닭은 어느 것인가요?","options":[{"t":"어둠 속에서 할머니의 이야기를 오래 듣고 난 뒤여서","correct":true},{"t":"라디오 소리가 작아져서","mis":"K5-1-u6-X35"},{"t":"휴대 전화를 다시 켜서","mis":"K5-1-u6-X35"},{"t":"라디오를 새것으로 바꿔서","mis":"K5-1-u6-X35"}],"explanation":["소리가 작아진 게 아니에요.","휴대 전화 이야기가 아니에요.","정전이 난 밤을 떠올려요."],"asset":{"type":"passage","lines":["사흘째 되던 밤, 마을 전체에 불이 나갔다.","라디오도 뚝 그쳤고 재하의 휴대 전화도 꺼졌다.","어둠은 두꺼운 담요 같았다.","「재하야, 여기 있다.」 할머니의 목소리가 들려왔다.","그 소리는 낮은 강물처럼 방바닥을 타고 흘러왔다.","할머니는 재하 아버지가 어릴 때 이야기를 꺼냈다.","재하는 처음으로 할머니의 목소리를 오래 들었다."],"title":"이야기 「할머니의 라디오」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#2','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C36',1,'mc','auto','이야기 「할머니의 라디오」 ②에서 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X36']::text[],false,'{"seq":2,"concept":"K5-1-u6-C36","difficulty":1,"kind":"mc","stem":"이야기 「할머니의 라디오」 ②에서 비유적 표현은 어느 것인가요?","options":[{"t":"어둠은 두꺼운 담요 같았다","correct":true},{"t":"사흘째 되던 밤, 마을 전체에 불이 나갔다","mis":"K5-1-u6-X36"},{"t":"라디오도 뚝 그쳤다","mis":"K5-1-u6-X36"},{"t":"할머니는 이야기를 꺼냈다","mis":"K5-1-u6-X36"}],"explanation":["있었던 일을 그대로 적었어요.","빗댄 것이 없어요.","어둠을 담요에 견주었어요."],"asset":{"type":"passage","lines":["사흘째 되던 밤, 마을 전체에 불이 나갔다.","라디오도 뚝 그쳤고 재하의 휴대 전화도 꺼졌다.","어둠은 두꺼운 담요 같았다.","「재하야, 여기 있다.」 할머니의 목소리가 들려왔다.","그 소리는 낮은 강물처럼 방바닥을 타고 흘러왔다.","할머니는 재하 아버지가 어릴 때 이야기를 꺼냈다.","재하는 처음으로 할머니의 목소리를 오래 들었다."],"title":"이야기 「할머니의 라디오」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#3','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C38',1,'mc','auto','이야기에서 비유적 표현을 쓰면 좋은 점은 어느 것인가요?',ARRAY['K5-1-u6-X38','K5-1-u6-X39']::text[],false,'{"seq":3,"concept":"K5-1-u6-C38","difficulty":1,"kind":"mc","stem":"이야기에서 비유적 표현을 쓰면 좋은 점은 어느 것인가요?","options":[{"t":"장면이 생생해지고 인물의 마음이 함께 전해진다","correct":true},{"t":"이야기의 길이를 줄일 수 있다","mis":"K5-1-u6-X38"},{"t":"사실을 정확한 숫자로 알려 준다","mis":"K5-1-u6-X38"},{"t":"읽는 사람이 줄거리를 몰라도 된다","mis":"K5-1-u6-X39"}],"explanation":["길이와 관계없어요.","숫자를 알려 주지 않아요.","장면과 마음이 함께 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#4','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C40',1,'ox','auto','인상적인 부분은 이야기에서 가장 중요한 장면이에요.',ARRAY['K5-1-u6-X40']::text[],false,'{"seq":4,"concept":"K5-1-u6-C40","difficulty":1,"kind":"ox","stem":"인상적인 부분은 이야기에서 가장 중요한 장면이에요.","answer":"X","reason_options":[{"t":"가장 중요한 장면이 아니라 내 마음이 움직인 장면이기 때문에","correct":true},{"t":"중요한 장면을 고르는 것이 정답이기 때문에","mis":"K5-1-u6-X40"}],"mis":"K5-1-u6-X40","explanation":["중요한 장면과 달라요.","정답이 정해져 있지 않아요.","내 마음이 움직인 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#5','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C37',2,'match','auto','비유적 표현과 그 느낌을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u6-C37","difficulty":2,"kind":"match","stem":"비유적 표현과 그 느낌을 알맞게 이으세요.","pairs":[{"l":"오래된 이불처럼 방 안을 덮고","r":"낡았지만 늘 곁에 있다"},{"l":"두꺼운 담요 같은 어둠","r":"답답하고 조금 무섭다"},{"l":"낮은 강물처럼 흘러온 목소리","r":"잔잔하고 마음을 놓게 한다"}],"mis":"K5-1-u6-X37","explanation":["오래된 이불은 늘 깔려 있어요.","두꺼운 담요는 답답해요.","낮은 강물은 잔잔해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#6','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C35',2,'mc','auto','이야기 「할머니의 라디오」의 흐름으로 알맞은 차례는 어느 것인가요?',ARRAY['K5-1-u6-X35']::text[],false,'{"seq":6,"concept":"K5-1-u6-C35","difficulty":2,"kind":"mc","stem":"이야기 「할머니의 라디오」의 흐름으로 알맞은 차례는 어느 것인가요?","options":[{"t":"라디오 소리가 거슬림 → 정전이 난 밤 → 할머니의 이야기를 오래 들음 → 건전지를 갈아 끼움","correct":true},{"t":"정전이 난 밤 → 라디오 소리가 거슬림 → 건전지를 갈아 끼움 → 할머니의 이야기를 들음","mis":"K5-1-u6-X35"},{"t":"건전지를 갈아 끼움 → 정전이 난 밤 → 라디오 소리가 거슬림 → 할머니의 이야기를 들음","mis":"K5-1-u6-X35"},{"t":"할머니의 이야기를 들음 → 건전지를 갈아 끼움 → 정전이 난 밤 → 라디오 소리가 거슬림","mis":"K5-1-u6-X35"}],"explanation":["처음에 소리가 거슬렸어요.","건전지는 돌아가는 날이에요.","차례대로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#7','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C40',2,'mc','auto','인상적인 부분을 고를 때 살펴볼 것이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u6-X40']::text[],false,'{"seq":7,"concept":"K5-1-u6-C40","difficulty":2,"kind":"mc","stem":"인상적인 부분을 고를 때 살펴볼 것이 아닌 것은 어느 것인가요?","options":[{"t":"이야기의 글자 수","correct":true},{"t":"인물의 말이나 행동","mis":"K5-1-u6-X40"},{"t":"일어난 사건","mis":"K5-1-u6-X40"},{"t":"인상 깊은 표현","mis":"K5-1-u6-X40"}],"explanation":["말과 행동도 살펴요.","사건도 살펴요.","글자 수는 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#8','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C41',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「인상적인 부분을 고른 뒤에는 작품의 어느 대목 때문에 그렇게 느꼈는지 (　　)를 함께 말한다.」',ARRAY['K5-1-u6-X41','K5-1-u6-X40']::text[],false,'{"seq":8,"concept":"K5-1-u6-C41","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「인상적인 부분을 고른 뒤에는 작품의 어느 대목 때문에 그렇게 느꼈는지 (　　)를 함께 말한다.」","options":[{"t":"근거","correct":true},{"t":"점수","mis":"K5-1-u6-X41"},{"t":"글자 수","mis":"K5-1-u6-X40"},{"t":"지은이의 나이","mis":"K5-1-u6-X41"}],"explanation":["점수를 매기지 않아요.","글자 수와 관계없어요.","어느 대목 때문인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#9','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C39',2,'mc','auto','이야기를 읽을 때 먼저 살펴야 할 것은 어느 것인가요?',ARRAY['K5-1-u6-X39']::text[],false,'{"seq":9,"concept":"K5-1-u6-C39","difficulty":2,"kind":"mc","stem":"이야기를 읽을 때 먼저 살펴야 할 것은 어느 것인가요?","options":[{"t":"누가 무엇을 겪었고 마음이 어떻게 달라졌는지","correct":true},{"t":"비유적 표현이 몇 개 나오는지","mis":"K5-1-u6-X39"},{"t":"가장 긴 문장이 무엇인지","mis":"K5-1-u6-X39"},{"t":"견주는 말이 어디에 있는지만","mis":"K5-1-u6-X39"}],"explanation":["비유 세기가 먼저가 아니에요.","길이와 관계없어요.","인물이 겪은 일과 마음이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_basic#10','kor',5,1,'u6','L08','g5_1_kor_u6_L08_basic','lesson_basic','K5-1-u6-C38',3,'mc','auto','「방이 캄캄해서 조금 무서웠다」 대신 「어둠은 두꺼운 담요 같았다」로 쓸 때 더해지는 것은 어느 것인가요?',ARRAY['K5-1-u6-X02','K5-1-u6-X35','K5-1-u6-X37']::text[],false,'{"seq":10,"concept":"K5-1-u6-C38","difficulty":3,"kind":"mc","stem":"「방이 캄캄해서 조금 무서웠다」 대신 「어둠은 두꺼운 담요 같았다」로 쓸 때 더해지는 것은 어느 것인가요?","options":[{"t":"어둠의 무게와 답답함까지 함께 전해진다","correct":true},{"t":"방이 정말 담요로 덮였다는 사실","mis":"K5-1-u6-X02"},{"t":"정전이 난 까닭","mis":"K5-1-u6-X35"},{"t":"재하가 담요를 좋아한다는 것","mis":"K5-1-u6-X37"}],"explanation":["정말 덮인 게 아니에요.","까닭은 나오지 않아요.","무게와 답답함이 전해져요."],"asset":{"type":"passage","lines":["그냥 쓰면 — 방이 캄캄해서 조금 무서웠다.","빗대어 쓰면 — 어둠은 두꺼운 담요 같았다."],"title":"두 가지로 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#1','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C39',2,'ox','auto','이야기를 읽을 때는 비유적 표현을 모두 찾아내는 것이 가장 중요해요.',ARRAY['K5-1-u6-X39']::text[],false,'{"seq":1,"concept":"K5-1-u6-C39","difficulty":2,"kind":"ox","stem":"이야기를 읽을 때는 비유적 표현을 모두 찾아내는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"비유는 이야기를 더 잘 읽으려고 살피는 것이고, 인물이 겪은 일과 마음이 먼저이기 때문에","correct":true},{"t":"비유를 많이 찾을수록 이야기를 잘 읽은 것이기 때문에","mis":"K5-1-u6-X39"}],"mis":"K5-1-u6-X39","explanation":["비유 찾기가 목적이 아니에요.","줄거리를 놓치기 쉬워요.","인물과 마음이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#2','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C36',2,'mc','auto','「손안에서 화면 불빛이 반딧불처럼 깜빡였다」에서 무엇을 무엇에 빗대었나요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":2,"concept":"K5-1-u6-C36","difficulty":2,"kind":"mc","stem":"「손안에서 화면 불빛이 반딧불처럼 깜빡였다」에서 무엇을 무엇에 빗대었나요?","options":[{"t":"화면 불빛을 반딧불에","correct":true},{"t":"반딧불을 화면 불빛에","mis":"K5-1-u6-X08"},{"t":"손을 반딧불에","mis":"K5-1-u6-X08"},{"t":"휴대 전화를 손에","mis":"K5-1-u6-X08"}],"explanation":["둘이 뒤바뀌었어요.","손은 빗댄 대상이 아니에요.","깜빡이는 불빛을 반딧불에 견주었어요."],"asset":{"type":"passage","lines":["여름 방학에 재하는 시골 할머니 댁에서 나흘을 지내게 되었다.","방 한쪽 선반의 낡은 라디오가 온종일 켜져 있었다.","지지직거리는 잡음이 오래된 이불처럼 방 안을 덮고 있었다.","재하는 그 소리가 신경 쓰여 휴대 전화를 더 붙들었다.","손안에서 화면 불빛이 반딧불처럼 깜빡였다.","「할머니, 이거 꺼도 돼요?」 「놔두렴. 말동무야.」"],"title":"이야기 「할머니의 라디오」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#3','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C37',3,'mc','auto','「오래된 이불처럼 방 안을 덮고」로 보아 처음에 재하가 라디오 소리를 어떻게 느꼈나요?',ARRAY['K5-1-u6-X37','K5-1-u6-X36']::text[],false,'{"seq":3,"concept":"K5-1-u6-C37","difficulty":3,"kind":"mc","stem":"「오래된 이불처럼 방 안을 덮고」로 보아 처음에 재하가 라디오 소리를 어떻게 느꼈나요?","options":[{"t":"늘 깔려 있어 답답하고 신경 쓰이는 소리","correct":true},{"t":"포근해서 잠이 솔솔 오는 소리","mis":"K5-1-u6-X37"},{"t":"맑고 또렷한 소리","mis":"K5-1-u6-X37"},{"t":"아무 소리도 나지 않는 것","mis":"K5-1-u6-X36"}],"explanation":["재하는 신경 쓰였어요.","소리는 맑지 않았어요.","방 안을 덮은 잡음이에요."],"asset":{"type":"passage","lines":["여름 방학에 재하는 시골 할머니 댁에서 나흘을 지내게 되었다.","방 한쪽 선반의 낡은 라디오가 온종일 켜져 있었다.","지지직거리는 잡음이 오래된 이불처럼 방 안을 덮고 있었다.","재하는 그 소리가 신경 쓰여 휴대 전화를 더 붙들었다.","손안에서 화면 불빛이 반딧불처럼 깜빡였다.","「할머니, 이거 꺼도 돼요?」 「놔두렴. 말동무야.」"],"title":"이야기 「할머니의 라디오」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#4','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C35',3,'mc','auto','재하가 돌아가는 날 건전지를 갈아 끼운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X35']::text[],false,'{"seq":4,"concept":"K5-1-u6-C35","difficulty":3,"kind":"mc","stem":"재하가 돌아가는 날 건전지를 갈아 끼운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니의 말동무인 라디오를 소중히 여기게 되어서","correct":true},{"t":"라디오 소리를 끄고 싶어서","mis":"K5-1-u6-X35"},{"t":"자기 휴대 전화를 충전하려고","mis":"K5-1-u6-X35"},{"t":"할머니가 시켜서 어쩔 수 없이","mis":"K5-1-u6-X35"}],"explanation":["끄려는 게 아니에요.","휴대 전화와 관계없어요.","재하의 마음이 달라졌어요."],"asset":{"type":"passage","lines":["다음 날 불이 들어오고 라디오도 다시 켜졌다.","그런데 그 소리가 전날처럼 거슬리지 않았다.","돌아가는 날 아침, 재하는 건전지 한 통을 샀다.","라디오의 낡은 건전지를 새것으로 갈아 끼웠다.","「말동무 목소리가 커졌네.」 할머니가 웃었다.","버스에 오르며 돌아보니 라디오 소리가 마당까지 나와 있었다."],"title":"이야기 「할머니의 라디오」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#5','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C41',3,'error','auto','인상적인 부분을 말한 친구들이에요. 근거를 대지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X41','K5-1-u6-X40']::text[],false,'{"seq":5,"concept":"K5-1-u6-C41","difficulty":3,"kind":"error","stem":"인상적인 부분을 말한 친구들이에요. 근거를 대지 않은 말은 어느 것인가요?","options":[{"t":"「나는 그냥 마지막 부분이 좋았어.」","correct":true,"mis_target":"K5-1-u6-X41"},{"t":"「정전된 밤이 인상적이었어. 할머니 목소리를 낮은 강물에 빗대서 마음이 놓였거든.」","mis":"K5-1-u6-X41"},{"t":"「건전지를 갈아 끼우는 장면이 좋았어. 재하가 할머니를 이해하게 된 게 보였어.」","mis":"K5-1-u6-X40"}],"explanation":["표현을 근거로 들었어요.","장면 속 재하의 변화를 들었어요.","어느 대목 때문인지 밝혀야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#6','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C42',3,'mc','auto','이 이야기를 내 삶과 이어 감상한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X42','K5-1-u6-X39']::text[],false,'{"seq":6,"concept":"K5-1-u6-C42","difficulty":3,"kind":"mc","stem":"이 이야기를 내 삶과 이어 감상한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"바쁘다는 까닭으로 할아버지 이야기를 제대로 들어 드리지 못한 일이 떠올랐다","correct":true},{"t":"라디오는 건전지가 있어야 움직인다","mis":"K5-1-u6-X42"},{"t":"이야기에 비유가 네 개 나온다","mis":"K5-1-u6-X39"},{"t":"여름 방학은 나흘보다 길다","mis":"K5-1-u6-X42"}],"explanation":["내 삶과 이은 게 아니에요.","비유 세기는 감상이 아니에요.","내 경험과 이어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#7','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C38',3,'mc','auto','「라디오 소리가 마당까지 나와 있었다」에 담긴 느낌으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X37','K5-1-u6-X35','K5-1-u6-X36']::text[],false,'{"seq":7,"concept":"K5-1-u6-C38","difficulty":3,"kind":"mc","stem":"「라디오 소리가 마당까지 나와 있었다」에 담긴 느낌으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니와 라디오가 재하를 배웅하는 듯한 따뜻한 마음","correct":true},{"t":"라디오 소리가 너무 커서 시끄럽다는 불만","mis":"K5-1-u6-X37"},{"t":"라디오가 고장 났다는 걱정","mis":"K5-1-u6-X35"},{"t":"마당에 라디오를 내놓았다는 사실","mis":"K5-1-u6-X36"}],"explanation":["불만이 아니에요.","고장 난 게 아니에요.","배웅하는 마음이 느껴져요."],"asset":{"type":"passage","lines":["다음 날 불이 들어오고 라디오도 다시 켜졌다.","그런데 그 소리가 전날처럼 거슬리지 않았다.","돌아가는 날 아침, 재하는 건전지 한 통을 샀다.","라디오의 낡은 건전지를 새것으로 갈아 끼웠다.","「말동무 목소리가 커졌네.」 할머니가 웃었다.","버스에 오르며 돌아보니 라디오 소리가 마당까지 나와 있었다."],"title":"이야기 「할머니의 라디오」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#8','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C40',4,'essay','teacher','「할머니의 라디오」에서 가장 마음이 움직인 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 이야기 속 대목을 근거로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C40","difficulty":4,"kind":"essay","stem":"「할머니의 라디오」에서 가장 마음이 움직인 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 이야기 속 대목을 근거로 쓰세요.","answer_guide":{"answer":"예: 정전이 난 밤 할머니가 재하를 부른 장면이 마음에 남았다. 어둠이 두꺼운 담요처럼 무서웠는데 할머니 목소리가 낮은 강물처럼 흘러와 재하가 다가가 앉는 모습에서 마음이 놓였다.","scoring_points":["장면을 하나 골랐는가","이야기 속 대목을 근거로 들었는가","마음이 움직인 까닭을 썼는가"]},"explanation":["어느 장면인가요?","어느 대목 때문인가요?","내 마음을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#9','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C38',4,'essay','teacher','이야기 속 비유적 표현 하나를 골라 비유 없이 바꾸어 쓰고, 두 문장이 주는 느낌을 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C38","difficulty":4,"kind":"essay","stem":"이야기 속 비유적 표현 하나를 골라 비유 없이 바꾸어 쓰고, 두 문장이 주는 느낌을 견주어 쓰세요.","answer_guide":{"answer":"예: 「그 소리는 낮은 강물처럼 방바닥을 타고 흘러왔다」를 「할머니가 낮은 목소리로 말했다」로 바꿀 수 있다. 바꾼 문장은 무엇이 일어났는지만 알려 주지만, 처음 문장은 목소리가 잔잔하게 퍼져 재하의 무서운 마음을 달래 주는 느낌까지 전해 준다.","scoring_points":["비유적 표현을 골랐는가","비유 없이 바꾸어 썼는가","두 문장의 느낌을 견주었는가"]},"explanation":["어떤 표현을 고를까요?","비유를 빼면?","무엇이 사라지나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L08_challenge#10','kor',5,1,'u6','L08','g5_1_kor_u6_L08_challenge','lesson_challenge','K5-1-u6-C39',4,'essay','teacher','재하의 마음이 처음과 끝에 어떻게 달라졌는지 쓰고, 그렇게 달라진 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C39","difficulty":4,"kind":"essay","stem":"재하의 마음이 처음과 끝에 어떻게 달라졌는지 쓰고, 그렇게 달라진 까닭을 쓰세요.","answer_guide":{"answer":"예: 처음에 재하는 라디오 소리가 거슬려 휴대 전화만 붙들었다. 끝에는 건전지를 갈아 끼울 만큼 라디오와 할머니를 소중히 여기게 되었다. 정전이 난 밤 할머니의 이야기를 오래 들으며 할머니에게 라디오가 왜 말동무인지 알게 되었기 때문이다.","scoring_points":["처음의 마음을 썼는가","끝의 마음을 썼는가","달라진 까닭을 썼는가"]},"explanation":["처음엔 어땠나요?","끝엔 어땠나요?","무슨 일이 있었나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#1','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C43',1,'mc','auto','신화에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X43']::text[],false,'{"seq":1,"concept":"K5-1-u6-C43","difficulty":1,"kind":"mc","stem":"신화에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"아주 오래전부터 입에서 입으로 전해 온 이야기","correct":true},{"t":"요즘 일어난 일을 그대로 적은 기록","mis":"K5-1-u6-X43"},{"t":"평범한 사람의 하루를 그린 일기","mis":"K5-1-u6-X43"},{"t":"과학 실험의 결과를 적은 글","mis":"K5-1-u6-X43"}],"explanation":["요즘 일이 아니에요.","평범한 하루가 아니에요.","오래전부터 전해 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#2','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C44',1,'mc','auto','사람들이 아이를 주몽이라 부른 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":2,"concept":"K5-1-u6-C44","difficulty":1,"kind":"mc","stem":"사람들이 아이를 주몽이라 부른 까닭은 어느 것인가요?","options":[{"t":"활을 아주 잘 쏘아서","correct":true},{"t":"알에서 태어나서","mis":"K5-1-u6-X44"},{"t":"말을 잘 먹여서","mis":"K5-1-u6-X44"},{"t":"강을 건너서","mis":"K5-1-u6-X44"}],"explanation":["이름의 까닭이 아니에요.","말 이야기는 뒤에 나와요.","활 잘 쏘는 사람이라는 뜻이에요."],"asset":{"type":"passage","lines":["왕이 알을 버리게 했지만 짐승들은 알을 밟지 않고 피해 다녔다.","새들은 날아와 깃털로 알을 덮어 주었다.","무엇으로도 깨지지 않던 알에서 마침내 아기가 태어났다.","아이는 일곱 살에 스스로 활을 만들어 쏘았다.","백 번을 쏘면 백 번을 맞혀 사람들은 아이를 주몽이라 불렀다."],"title":"신화 「알에서 태어난 아이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#3','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C45',1,'match','auto','신화 속 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u6-C45","difficulty":1,"kind":"match","stem":"신화 속 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"도읍","r":"한 나라의 중앙 정부가 있는 곳"},{"l":"태자","r":"임금의 뒤를 이을 아들"},{"l":"후환","r":"뒷날 생기는 걱정과 근심"}],"mis":"K5-1-u6-X45","explanation":["주몽은 졸본주를 도읍으로 삼았어요.","대소는 태자예요.","후환은 뒷날의 걱정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#4','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C46',1,'ox','auto','신화는 옛이야기라서 비유적 표현이 쓰이지 않아요.',ARRAY['K5-1-u6-X46']::text[],false,'{"seq":4,"concept":"K5-1-u6-C46","difficulty":1,"kind":"ox","stem":"신화는 옛이야기라서 비유적 표현이 쓰이지 않아요.","answer":"X","reason_options":[{"t":"「갈대처럼 여윈 말」처럼 신화에도 비유적 표현이 쓰이기 때문에","correct":true},{"t":"비유는 요즘 쓴 시에만 나오기 때문에","mis":"K5-1-u6-X46"}],"mis":"K5-1-u6-X46","explanation":["신화에도 비유가 있어요.","「처럼」을 찾아보아요.","장면이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#5','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C46',2,'mc','auto','신화 「알에서 태어난 아이」 ①에 쓰인 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X46']::text[],false,'{"seq":5,"concept":"K5-1-u6-C46","difficulty":2,"kind":"mc","stem":"신화 「알에서 태어난 아이」 ①에 쓰인 비유적 표현은 어느 것인가요?","options":[{"t":"그 빛은 그림자처럼 유화를 따라다녔다","correct":true},{"t":"얼마 뒤 유화는 커다란 알 하나를 낳았다","mis":"K5-1-u6-X46"},{"t":"왕은 유화를 햇빛이 들지 않는 방에 두었다","mis":"K5-1-u6-X46"},{"t":"금와왕이 못가에서 유화를 만났다","mis":"K5-1-u6-X46"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","빛을 그림자에 견주었어요."],"asset":{"type":"passage","lines":["동부여의 금와왕이 못가에서 유화라는 여인을 만났다.","유화는 물의 신 하백의 딸로, 아버지의 노여움을 사 쫓겨난 처지였다.","왕은 유화를 햇빛이 들지 않는 방에 두었다.","그런데 햇빛 한 줄기가 들어와 유화를 비추었다.","그 빛은 그림자처럼 유화를 따라다녔다.","얼마 뒤 유화는 커다란 알 하나를 낳았다."],"title":"신화 「알에서 태어난 아이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#6','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C47',2,'mc','auto','신화에서 자주 나타나는 특징은 어느 것인가요?',ARRAY['K5-1-u6-X47']::text[],false,'{"seq":6,"concept":"K5-1-u6-C47","difficulty":2,"kind":"mc","stem":"신화에서 자주 나타나는 특징은 어느 것인가요?","options":[{"t":"비범한 탄생과 시련, 그리고 뜻밖의 도움","correct":true},{"t":"모든 사건이 날짜까지 정확하다","mis":"K5-1-u6-X47"},{"t":"평범한 사람의 하루를 그린다","mis":"K5-1-u6-X47"},{"t":"누구나 겪는 일만 나온다","mis":"K5-1-u6-X47"}],"explanation":["날짜가 정확하지 않아요.","평범한 하루가 아니에요.","놀라운 일이 일어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#7','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C44',2,'mc','auto','왕이 주몽에게 말 먹이는 일을 시킨 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":7,"concept":"K5-1-u6-C44","difficulty":2,"kind":"mc","stem":"왕이 주몽에게 말 먹이는 일을 시킨 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 뜻을 품지 못하게 하려고","correct":true},{"t":"말타기 실력을 길러 주려고","mis":"K5-1-u6-X44"},{"t":"좋은 말을 선물하려고","mis":"K5-1-u6-X44"},{"t":"주몽이 말을 좋아해서","mis":"K5-1-u6-X44"}],"explanation":["실력을 키워 주려는 게 아니에요.","선물이 아니에요.","태자의 말을 들은 뒤였어요."],"asset":{"type":"passage","lines":["주몽의 재주는 왕자들보다 단연 뛰어났다.","태자 대소는 주몽을 없애야 후환이 없다고 왕에게 말했다.","왕은 주몽에게 말 먹이는 일을 시켰다.","주몽은 가장 좋은 말에게 일부러 먹이를 조금씩만 주었다.","그 말은 갈대처럼 여위어 갔고, 왕은 볼품없어진 그 말을 주몽에게 주었다.","쫓기던 주몽 앞에 강이 나타나자 자라와 물고기가 다리를 놓았다.","강을 건넌 주몽은 졸본주를 도읍으로 삼고 고구려를 세웠다."],"title":"신화 「알에서 태어난 아이」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#8','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C45',2,'blank','auto','빈칸에 알맞은 낱말은 어느 것인가요? 「주몽의 재주는 왕자들보다 (　　) 뛰어났다.」',ARRAY['K5-1-u6-X45']::text[],false,'{"seq":8,"concept":"K5-1-u6-C45","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 낱말은 어느 것인가요? 「주몽의 재주는 왕자들보다 (　　) 뛰어났다.」","options":[{"t":"단연","correct":true},{"t":"후환","mis":"K5-1-u6-X45"},{"t":"도읍","mis":"K5-1-u6-X45"},{"t":"태자","mis":"K5-1-u6-X45"}],"explanation":["후환은 뒷날의 걱정이에요.","도읍은 곳을 가리켜요.","여럿 가운데 뚜렷하게라는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#9','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C48',2,'mc','auto','주몽 · 박혁거세 · 프로메테우스 이야기의 닮은 점은 어느 것인가요?',ARRAY['K5-1-u6-X48','K5-1-u6-X43']::text[],false,'{"seq":9,"concept":"K5-1-u6-C48","difficulty":2,"kind":"mc","stem":"주몽 · 박혁거세 · 프로메테우스 이야기의 닮은 점은 어느 것인가요?","options":[{"t":"보통 사람과 다른 특별한 인물이 나온다","correct":true},{"t":"모두 같은 나라의 이야기이다","mis":"K5-1-u6-X48"},{"t":"모두 알에서 태어난다","mis":"K5-1-u6-X48"},{"t":"모두 요즘 일어난 일이다","mis":"K5-1-u6-X43"}],"explanation":["나라가 서로 달라요.","프로메테우스는 알에서 태어나지 않았어요.","특별한 인물이 나와요."],"asset":{"type":"passage","lines":["박혁거세 — 우물가에 내려온 빛 곁에 흰말과 큰 알이 있었다.","알에서 빛나는 사내아이가 태어나 자라서 왕이 되었고, 신라가 시작되었다.","프로메테우스 — 옛날 사람들에게는 불이 없어 추운 밤에 떨었다.","프로메테우스는 몰래 불을 가져와 사람들에게 건넸다.","사람들은 따뜻해졌지만 프로메테우스는 그 일로 벌을 받았다."],"title":"신화 두 편 더"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_basic#10','kor',5,1,'u6','L10','g5_1_kor_u6_L10_basic','lesson_basic','K5-1-u6-C49',3,'mc','auto','세 신화를 읽고 감상을 나눌 때 알맞은 생각은 어느 것인가요?',ARRAY['K5-1-u6-X49','K5-1-u6-X40']::text[],false,'{"seq":10,"concept":"K5-1-u6-C49","difficulty":3,"kind":"mc","stem":"세 신화를 읽고 감상을 나눌 때 알맞은 생각은 어느 것인가요?","options":[{"t":"같은 장면을 골라도 느낀 것이 다를 수 있으니 그 다름을 나눈다","correct":true},{"t":"같은 장면을 골랐다면 느낀 것도 같아야 한다","mis":"K5-1-u6-X49"},{"t":"누구의 감상이 맞는지 가려야 한다","mis":"K5-1-u6-X49"},{"t":"가장 많은 친구가 고른 장면이 정답이다","mis":"K5-1-u6-X40"}],"explanation":["느낌은 다를 수 있어요.","맞고 틀림을 가리지 않아요.","정답 장면은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#1','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C48',2,'ox','auto','주몽과 박혁거세가 알에서 태어났으니, 모든 신화의 주인공은 알에서 태어나요.',ARRAY['K5-1-u6-X48']::text[],false,'{"seq":1,"concept":"K5-1-u6-C48","difficulty":2,"kind":"ox","stem":"주몽과 박혁거세가 알에서 태어났으니, 모든 신화의 주인공은 알에서 태어나요.","answer":"X","reason_options":[{"t":"프로메테우스 이야기처럼 알에서 태어나지 않는 신화도 있기 때문에","correct":true},{"t":"신화라면 주인공이 반드시 알에서 태어나기 때문에","mis":"K5-1-u6-X48"}],"mis":"K5-1-u6-X48","explanation":["두 이야기만 보고 정할 수 없어요.","프로메테우스를 떠올려요.","닮은 점은 특별한 인물과 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#2','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C45',2,'mc','auto','「단연」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X45']::text[],false,'{"seq":2,"concept":"K5-1-u6-C45","difficulty":2,"kind":"mc","stem":"「단연」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"여럿 가운데 뚜렷하게","correct":true},{"t":"뒷날 생기는 걱정과 근심","mis":"K5-1-u6-X45"},{"t":"한 나라의 중앙 정부가 있는 곳","mis":"K5-1-u6-X45"},{"t":"임금의 뒤를 이을 아들","mis":"K5-1-u6-X45"}],"explanation":["후환의 뜻이에요.","도읍의 뜻이에요.","「단연 뛰어났다」를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#3','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C47',3,'mc','auto','주몽 이야기에서 「시련과 도움」에 해당하는 장면은 어느 것인가요?',ARRAY['K5-1-u6-X47']::text[],false,'{"seq":3,"concept":"K5-1-u6-C47","difficulty":3,"kind":"mc","stem":"주몽 이야기에서 「시련과 도움」에 해당하는 장면은 어느 것인가요?","options":[{"t":"쫓기던 주몽 앞에 강이 나타나자 자라와 물고기가 다리를 놓았다","correct":true},{"t":"유화가 커다란 알을 낳았다","mis":"K5-1-u6-X47"},{"t":"일곱 살에 활을 만들어 쏘았다","mis":"K5-1-u6-X47"},{"t":"졸본주를 도읍으로 삼았다","mis":"K5-1-u6-X47"}],"explanation":["비범한 탄생이에요.","남다른 재주예요.","위기에서 뜻밖의 도움을 받았어요."],"asset":{"type":"passage","lines":["비범한 탄생 — 알에서 태어나거나 하늘의 빛을 받아 태어난다","남다른 재주 — 어릴 때부터 뛰어난 능력을 보인다","시련과 도움 — 위기를 만나지만 뜻밖의 도움을 받는다","나라의 시작 — 끝에 나라를 세우거나 새 질서를 연다"],"title":"신화에서 자주 보이는 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#4','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C46',3,'mc','auto','「그 말은 갈대처럼 여위어 갔고」에서 말을 갈대에 빗댄 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04','K5-1-u6-X02']::text[],false,'{"seq":4,"concept":"K5-1-u6-C46","difficulty":3,"kind":"mc","stem":"「그 말은 갈대처럼 여위어 갔고」에서 말을 갈대에 빗댄 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"말이 가늘고 마른 갈대처럼 볼품없이 말랐다는 모습을 또렷하게 보여 주려고","correct":true},{"t":"말이 갈대밭에서 살았기 때문에","mis":"K5-1-u6-X04"},{"t":"갈대가 말의 먹이였기 때문에","mis":"K5-1-u6-X04"},{"t":"말이 갈대처럼 초록색이 되었기 때문에","mis":"K5-1-u6-X02"}],"explanation":["사는 곳 이야기가 아니에요.","먹이 이야기가 아니에요.","마른 모습이 닮았어요."],"asset":{"type":"passage","lines":["주몽의 재주는 왕자들보다 단연 뛰어났다.","태자 대소는 주몽을 없애야 후환이 없다고 왕에게 말했다.","왕은 주몽에게 말 먹이는 일을 시켰다.","주몽은 가장 좋은 말에게 일부러 먹이를 조금씩만 주었다.","그 말은 갈대처럼 여위어 갔고, 왕은 볼품없어진 그 말을 주몽에게 주었다.","쫓기던 주몽 앞에 강이 나타나자 자라와 물고기가 다리를 놓았다.","강을 건넌 주몽은 졸본주를 도읍으로 삼고 고구려를 세웠다."],"title":"신화 「알에서 태어난 아이」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#5','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C44',3,'error','auto','주몽 이야기의 흐름을 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":5,"concept":"K5-1-u6-C44","difficulty":3,"kind":"error","stem":"주몽 이야기의 흐름을 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「주몽은 고구려를 세운 뒤에 알에서 태어났어.」","correct":true,"mis_target":"K5-1-u6-X44"},{"t":"「주몽은 활 솜씨 때문에 태자 대소의 시기를 받았어.」","mis":"K5-1-u6-X44"},{"t":"「주몽은 좋은 말을 몰래 마련해 두었다가 떠났어.」","mis":"K5-1-u6-X44"}],"explanation":["시기를 받은 것은 맞아요.","말을 마련한 것도 맞아요.","알에서 태어난 일이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#6','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C43',3,'mc','auto','박혁거세 이야기가 신화인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X43','K5-1-u6-X47']::text[],false,'{"seq":6,"concept":"K5-1-u6-C43","difficulty":3,"kind":"mc","stem":"박혁거세 이야기가 신화인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빛나는 아이가 알에서 태어나 신라를 시작했다는 놀라운 이야기가 오래 전해졌기 때문이다","correct":true},{"t":"흰말이 나오는 이야기는 모두 신화이기 때문이다","mis":"K5-1-u6-X43"},{"t":"지은이와 쓴 날짜가 분명하기 때문이다","mis":"K5-1-u6-X43"},{"t":"평범한 마을 사람의 하루를 그렸기 때문이다","mis":"K5-1-u6-X47"}],"explanation":["흰말 때문이 아니에요.","지은이를 알 수 없어요.","나라의 시작을 놀라운 일로 풀었어요."],"asset":{"type":"passage","lines":["박혁거세 — 우물가에 내려온 빛 곁에 흰말과 큰 알이 있었다.","알에서 빛나는 사내아이가 태어나 자라서 왕이 되었고, 신라가 시작되었다.","프로메테우스 — 옛날 사람들에게는 불이 없어 추운 밤에 떨었다.","프로메테우스는 몰래 불을 가져와 사람들에게 건넸다.","사람들은 따뜻해졌지만 프로메테우스는 그 일로 벌을 받았다."],"title":"신화 두 편 더"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#7','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C49',3,'mc','auto','프로메테우스가 불을 건넨 장면을 두고 한 친구는 「용기」를, 다른 친구는 「약속을 어긴 일」을 떠올렸어요. 바르게 생각한 것은 어느 것인가요?',ARRAY['K5-1-u6-X49']::text[],false,'{"seq":7,"concept":"K5-1-u6-C49","difficulty":3,"kind":"mc","stem":"프로메테우스가 불을 건넨 장면을 두고 한 친구는 「용기」를, 다른 친구는 「약속을 어긴 일」을 떠올렸어요. 바르게 생각한 것은 어느 것인가요?","options":[{"t":"같은 장면도 다르게 새길 수 있으니 서로의 까닭을 들어 본다","correct":true},{"t":"둘 가운데 한 사람은 틀렸다","mis":"K5-1-u6-X49"},{"t":"같은 장면이니 느낌도 같아야 한다","mis":"K5-1-u6-X49"},{"t":"선생님이 정한 감상만 맞다","mis":"K5-1-u6-X49"}],"explanation":["틀린 감상이 아니에요.","느낌은 다를 수 있어요.","까닭을 들어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#8','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C47',4,'essay','teacher','박혁거세 이야기에서 신화의 특징이 드러난 곳을 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C47","difficulty":4,"kind":"essay","stem":"박혁거세 이야기에서 신화의 특징이 드러난 곳을 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 우물가에 빛이 내려오고 알에서 빛나는 아이가 태어난 것은 비범한 탄생이다. 그 아이가 자라 왕이 되어 신라가 시작된 것은 나라의 시작이다.","scoring_points":["특징 하나를 찾았는가","다른 특징 하나를 더 찾았는가","이야기 속 장면을 들어 썼는가"]},"explanation":["어떻게 태어났나요?","무엇이 시작되었나요?","장면을 들어 써요."],"asset":{"type":"passage","lines":["박혁거세 — 우물가에 내려온 빛 곁에 흰말과 큰 알이 있었다.","알에서 빛나는 사내아이가 태어나 자라서 왕이 되었고, 신라가 시작되었다.","프로메테우스 — 옛날 사람들에게는 불이 없어 추운 밤에 떨었다.","프로메테우스는 몰래 불을 가져와 사람들에게 건넸다.","사람들은 따뜻해졌지만 프로메테우스는 그 일로 벌을 받았다."],"title":"신화 두 편 더"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#9','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C49',4,'essay','teacher','세 신화 가운데 가장 인상적인 장면을 하나 고르고, 그 장면을 두고 친구가 나와 다르게 느낄 수 있는 점도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C49","difficulty":4,"kind":"essay","stem":"세 신화 가운데 가장 인상적인 장면을 하나 고르고, 그 장면을 두고 친구가 나와 다르게 느낄 수 있는 점도 함께 쓰세요.","answer_guide":{"answer":"예: 자라와 물고기가 다리를 놓아 주몽이 강을 건너는 장면이 가장 인상적이었다. 나는 위기에 뜻밖의 도움을 받는 모습이 짜릿했다. 하지만 어떤 친구는 떠나는 아들을 보낸 유화의 마음을 떠올리며 쓸쓸하게 느낄 수도 있다.","scoring_points":["장면을 하나 골랐는가","내가 느낀 것을 썼는가","친구가 다르게 느낄 수 있는 점을 썼는가"]},"explanation":["어느 장면인가요?","나는 어떻게 느꼈나요?","다르게 볼 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L10_challenge#10','kor',5,1,'u6','L10','g5_1_kor_u6_L10_challenge','lesson_challenge','K5-1-u6-C44',4,'essay','teacher','주몽 이야기를 일이 일어난 차례대로 세 문장으로 간추리세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C44","difficulty":4,"kind":"essay","stem":"주몽 이야기를 일이 일어난 차례대로 세 문장으로 간추리세요.","answer_guide":{"answer":"예: 유화가 햇빛을 받아 낳은 알에서 주몽이 태어났다. 주몽은 활 솜씨가 뛰어나 태자 대소의 시기를 받자 좋은 말을 마련해 떠났다. 자라와 물고기가 놓은 다리로 강을 건넌 주몽은 고구려를 세웠다.","scoring_points":["태어난 일을 썼는가","시련과 떠남을 썼는가","강을 건너 나라를 세운 일을 차례대로 썼는가"]},"explanation":["처음은 탄생이에요.","가운데는 시련이에요.","끝은 나라의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#1','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C50',1,'mc','auto','책갈피를 만드는 차례에서 가장 먼저 할 일은 어느 것인가요?',ARRAY['K5-1-u6-X50']::text[],false,'{"seq":1,"concept":"K5-1-u6-C50","difficulty":1,"kind":"mc","stem":"책갈피를 만드는 차례에서 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"읽은 작품 가운데 마음에 드는 작품을 고른다","correct":true},{"t":"끈부터 묶는다","mis":"K5-1-u6-X50"},{"t":"뒷면에 그림부터 그린다","mis":"K5-1-u6-X50"},{"t":"색연필 색부터 고른다","mis":"K5-1-u6-X50"}],"explanation":["끈은 마지막이에요.","그림은 표현을 고른 뒤예요.","작품부터 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#2','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C51',1,'mc','auto','책갈피에 담을 만한 표현은 어느 것인가요?',ARRAY['K5-1-u6-X51']::text[],false,'{"seq":2,"concept":"K5-1-u6-C51","difficulty":1,"kind":"mc","stem":"책갈피에 담을 만한 표현은 어느 것인가요?","options":[{"t":"지우개는 작은 눈사람","correct":true},{"t":"오늘은 화요일이다","mis":"K5-1-u6-X51"},{"t":"건전지를 갈아 끼웠다","mis":"K5-1-u6-X51"},{"t":"학교는 아홉 시에 시작한다","mis":"K5-1-u6-X51"}],"explanation":["사실만 적었어요.","있었던 일 그대로예요.","한 줄로 장면이 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#3','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C54',1,'mc','auto','책갈피를 소개할 때 담을 것은 어느 것인가요?',ARRAY['K5-1-u6-X54']::text[],false,'{"seq":3,"concept":"K5-1-u6-C54","difficulty":1,"kind":"mc","stem":"책갈피를 소개할 때 담을 것은 어느 것인가요?","options":[{"t":"고른 표현과 그것을 고른 까닭","correct":true},{"t":"만드는 데 걸린 시간","mis":"K5-1-u6-X54"},{"t":"사용한 색연필의 개수","mis":"K5-1-u6-X54"},{"t":"끈의 길이","mis":"K5-1-u6-X54"}],"explanation":["시간과 관계없어요.","개수와 관계없어요.","표현과 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#4','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C53',1,'ox','auto','남의 작품에서 가져온 표현이라도 책갈피에 작품 제목과 지은이를 적지 않아도 돼요.',ARRAY['K5-1-u6-X53']::text[],false,'{"seq":4,"concept":"K5-1-u6-C53","difficulty":1,"kind":"ox","stem":"남의 작품에서 가져온 표현이라도 책갈피에 작품 제목과 지은이를 적지 않아도 돼요.","answer":"X","reason_options":[{"t":"가져온 표현이라면 어디서 가져왔는지 제목과 지은이를 적어야 하기 때문에","correct":true},{"t":"책갈피는 작아서 출처를 적을 곳이 없기 때문에","mis":"K5-1-u6-X53"}],"mis":"K5-1-u6-X53","explanation":["작게라도 적어요.","누구의 표현인지 밝혀요.","가져왔다면 출처를 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#5','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C52',2,'mc','auto','책갈피 뒷면의 그림에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X52']::text[],false,'{"seq":5,"concept":"K5-1-u6-C52","difficulty":2,"kind":"mc","stem":"책갈피 뒷면의 그림에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"표현이 만든 장면을 담는다","correct":true},{"t":"표현을 글로 다시 설명한다","mis":"K5-1-u6-X52"},{"t":"표현과 관계없이 좋아하는 것을 그린다","mis":"K5-1-u6-X52"},{"t":"그림은 빈칸으로 남긴다","mis":"K5-1-u6-X52"}],"explanation":["다시 설명하는 게 아니에요.","표현과 이어져야 해요.","장면을 담아요."],"asset":{"type":"passage","lines":["앞면 — 가로등은 골목을 지키는 등대","뒷면 — 어두운 골목에 홀로 켜진 불빛, 그 아래 길게 늘어진 그림자"],"title":"책갈피의 앞면과 뒷면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#6','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C52',2,'match','auto','표현과 어울리는 그림을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-1-u6-C52","difficulty":2,"kind":"match","stem":"표현과 어울리는 그림을 알맞게 이으세요.","pairs":[{"l":"지우개는 작은 눈사람","r":"닳아서 작아진 하얀 조각"},{"l":"어둠은 두꺼운 담요 같았다","r":"방 전체를 덮은 짙은 색 면"},{"l":"매미 소리는 여름을 켜는 스위치","r":"나무에 붙은 매미와 쏟아지는 햇빛"}],"mis":"K5-1-u6-X52","explanation":["작아지는 하얀 모습이에요.","방을 덮은 어둠이에요.","여름이 켜지는 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#7','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C53',2,'mc','auto','책갈피를 만들 때 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X53']::text[],false,'{"seq":7,"concept":"K5-1-u6-C53","difficulty":2,"kind":"mc","stem":"책갈피를 만들 때 알맞은 것은 어느 것인가요?","options":[{"t":"표현은 한두 줄만 골라 또렷하게 옮긴다","correct":true},{"t":"시 전체를 빽빽하게 옮겨 적는다","mis":"K5-1-u6-X53"},{"t":"글씨를 아주 작게 흘려 쓴다","mis":"K5-1-u6-X53"},{"t":"색은 표현의 분위기와 관계없이 고른다","mis":"K5-1-u6-X53"}],"explanation":["책갈피는 작아요.","또렷하게 써요.","색은 분위기에 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#8','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C54',2,'mc','auto','나윤이와 소율이의 소개 가운데 소율이의 소개가 더 나은 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X54']::text[],false,'{"seq":8,"concept":"K5-1-u6-C54","difficulty":2,"kind":"mc","stem":"나윤이와 소율이의 소개 가운데 소율이의 소개가 더 나은 까닭은 어느 것인가요?","options":[{"t":"고른 표현과 그 까닭을 함께 말했다","correct":true},{"t":"말이 길어서 멋있다","mis":"K5-1-u6-X54"},{"t":"예쁘다는 말을 넣었다","mis":"K5-1-u6-X54"},{"t":"두 소개는 담은 것이 똑같다","mis":"K5-1-u6-X54"}],"explanation":["길이가 까닭이 아니에요.","예쁘다는 말은 나윤이가 했어요.","표현과 까닭을 함께 말했어요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"그냥 예뻐서 골랐어요."},{"who":"소율","text":"가로등을 등대에 빗댄 표현을 골랐어요. 늦게 오는 길에 저를 지켜 준 느낌이 이 한 줄에 다 들어 있어서요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#9','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C53',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「책갈피의 색은 표현의 (　　)에 맞춘다.」',ARRAY['K5-1-u6-X53']::text[],false,'{"seq":9,"concept":"K5-1-u6-C53","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「책갈피의 색은 표현의 (　　)에 맞춘다.」","options":[{"t":"분위기","correct":true},{"t":"글자 수","mis":"K5-1-u6-X53"},{"t":"지은이 나이","mis":"K5-1-u6-X53"},{"t":"값","mis":"K5-1-u6-X53"}],"explanation":["글자 수와 관계없어요.","나이와 관계없어요.","분위기에 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_basic#10','kor',5,1,'u6','L12','g5_1_kor_u6_L12_basic','lesson_basic','K5-1-u6-C51',3,'mc','auto','「할머니의 라디오」로 책갈피를 만들 때 담을 표현으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X51']::text[],false,'{"seq":10,"concept":"K5-1-u6-C51","difficulty":3,"kind":"mc","stem":"「할머니의 라디오」로 책갈피를 만들 때 담을 표현으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 소리는 낮은 강물처럼 방바닥을 타고 흘러왔다","correct":true},{"t":"재하는 건전지 한 통을 샀다","mis":"K5-1-u6-X51"},{"t":"다음 날 불이 들어왔다","mis":"K5-1-u6-X51"},{"t":"여름 방학에 할머니 댁에 갔다","mis":"K5-1-u6-X51"}],"explanation":["사실만 적었어요.","있었던 일 그대로예요.","한 줄로 장면과 마음이 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#1','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C50',2,'ox','auto','책갈피를 만들 때는 작품을 고르기 전에 끈부터 묶어 두어야 해요.',ARRAY['K5-1-u6-X50']::text[],false,'{"seq":1,"concept":"K5-1-u6-C50","difficulty":2,"kind":"ox","stem":"책갈피를 만들 때는 작품을 고르기 전에 끈부터 묶어 두어야 해요.","answer":"X","reason_options":[{"t":"작품과 표현을 먼저 골라야 무엇을 담을지 정할 수 있기 때문에","correct":true},{"t":"끈을 묶는 것이 책갈피의 첫 단계이기 때문에","mis":"K5-1-u6-X50"}],"mis":"K5-1-u6-X50","explanation":["끈은 마지막이에요.","담을 것부터 정해요.","작품 → 표현 → 앞뒷면 → 끈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#2','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C52',2,'mc','auto','「가로등은 골목을 지키는 등대」 책갈피의 뒷면 그림으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X52']::text[],false,'{"seq":2,"concept":"K5-1-u6-C52","difficulty":2,"kind":"mc","stem":"「가로등은 골목을 지키는 등대」 책갈피의 뒷면 그림으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어두운 골목에 홀로 켜진 불빛과 길게 늘어진 그림자","correct":true},{"t":"가로등 기둥의 길이를 잰 그림","mis":"K5-1-u6-X52"},{"t":"바닷가 놀이공원 그림","mis":"K5-1-u6-X52"},{"t":"가로등과 등대라는 낱말을 크게 쓴 것","mis":"K5-1-u6-X52"}],"explanation":["길이를 재는 게 아니에요.","표현과 관계없어요.","표현이 만든 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#3','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C54',3,'mc','auto','「지우개는 작은 눈사람」으로 만든 책갈피를 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X54']::text[],false,'{"seq":3,"concept":"K5-1-u6-C54","difficulty":3,"kind":"mc","stem":"「지우개는 작은 눈사람」으로 만든 책갈피를 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실수를 지워 주며 작아지는 지우개가 고마워서 이 표현을 골랐어요","correct":true},{"t":"이 책갈피는 십 분 만에 만들었어요","mis":"K5-1-u6-X54"},{"t":"색연필 세 자루를 썼어요","mis":"K5-1-u6-X54"},{"t":"그냥 예뻐서 골랐어요","mis":"K5-1-u6-X54"}],"explanation":["시간 이야기예요.","개수 이야기예요.","고른 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#4','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C53',3,'mc','auto','친구의 시에서 표현을 가져와 책갈피를 만들 때 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X53']::text[],false,'{"seq":4,"concept":"K5-1-u6-C53","difficulty":3,"kind":"mc","stem":"친구의 시에서 표현을 가져와 책갈피를 만들 때 알맞은 것은 어느 것인가요?","options":[{"t":"표현 아래에 시의 제목과 친구 이름을 작게 적는다","correct":true},{"t":"내가 쓴 표현인 것처럼 이름을 적지 않는다","mis":"K5-1-u6-X53"},{"t":"시 전체를 다 옮겨 적는다","mis":"K5-1-u6-X53"},{"t":"표현을 조금 바꾸고 출처는 적지 않는다","mis":"K5-1-u6-X53"}],"explanation":["출처를 밝혀요.","한두 줄만 옮겨요.","바꾸어도 출처를 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#5','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C51',3,'error','auto','책갈피에 담을 표현을 고른 친구들이에요. 알맞지 않게 고른 말은 어느 것인가요?',ARRAY['K5-1-u6-X51']::text[],false,'{"seq":5,"concept":"K5-1-u6-C51","difficulty":3,"kind":"error","stem":"책갈피에 담을 표현을 고른 친구들이에요. 알맞지 않게 고른 말은 어느 것인가요?","options":[{"t":"「나는 오늘이 무슨 요일인지 적은 문장을 골랐어.」","correct":true,"mis_target":"K5-1-u6-X51"},{"t":"「나는 어둠을 두꺼운 담요에 빗댄 표현을 골랐어.」","mis":"K5-1-u6-X51"},{"t":"「나는 지우개를 눈사람에 빗댄 표현을 골랐어.」","mis":"K5-1-u6-X51"}],"explanation":["장면이 떠오르는 비유예요.","이것도 비유예요.","사실만 적은 문장은 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#6','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C50',3,'mc','auto','책갈피를 만드는 일과 이 단원에서 배운 것이 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X32','K5-1-u6-X52','K5-1-u6-X50']::text[],false,'{"seq":6,"concept":"K5-1-u6-C50","difficulty":3,"kind":"mc","stem":"책갈피를 만드는 일과 이 단원에서 배운 것이 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마음에 남은 비유적 표현을 골라 그 장면을 다시 떠올리며 즐긴다","correct":true},{"t":"비유를 많이 모을수록 좋은 책갈피가 된다","mis":"K5-1-u6-X32"},{"t":"그림 솜씨를 겨루는 활동이다","mis":"K5-1-u6-X52"},{"t":"작품을 읽지 않아도 만들 수 있다","mis":"K5-1-u6-X50"}],"explanation":["많이 모으는 게 아니에요.","겨루기가 아니에요.","읽은 작품에서 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#7','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C52',3,'mc','auto','「매미 소리는 여름을 켜는 스위치」 책갈피의 그림을 두고 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u6-X52']::text[],false,'{"seq":7,"concept":"K5-1-u6-C52","difficulty":3,"kind":"mc","stem":"「매미 소리는 여름을 켜는 스위치」 책갈피의 그림을 두고 바르게 말한 것은 어느 것인가요?","options":[{"t":"매미가 울기 시작하자 여름이 켜지는 듯한 장면을 담으면 표현이 살아난다","correct":true},{"t":"스위치 모양만 크게 그려야 한다","mis":"K5-1-u6-X52"},{"t":"매미 소리가 곧 여름이라고 글로 다시 쓰면 된다","mis":"K5-1-u6-X52"},{"t":"표현과 관계없는 겨울 풍경을 그려도 된다","mis":"K5-1-u6-X52"}],"explanation":["겉모양만 그리지 않아요.","글로 다시 쓰지 않아요.","표현이 만든 장면을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#8','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C54',4,'essay','teacher','이 단원에서 읽은 작품 가운데 책갈피에 담고 싶은 비유적 표현을 하나 고르고, 그 표현을 고른 까닭을 소개하는 말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u6-C54","difficulty":4,"kind":"essay","stem":"이 단원에서 읽은 작품 가운데 책갈피에 담고 싶은 비유적 표현을 하나 고르고, 그 표현을 고른 까닭을 소개하는 말로 쓰세요.","answer_guide":{"answer":"예: 시 「나는 아직 새벽」의 「나는 아직 새벽」을 골랐어요. 빨리 잘하라는 말을 들을 때마다 조급했는데, 아직 자라는 중이라고 말해 주는 것 같아 마음이 편해졌기 때문이에요.","scoring_points":["비유적 표현을 하나 골랐는가","고른 까닭을 썼는가","소개하는 말로 썼는가"]},"explanation":["어떤 표현을 고를까요?","왜 마음에 남았나요?","소개하듯 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#9','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C52',4,'essay','teacher','고른 표현에 어울리는 뒷면 그림을 어떻게 그릴지 쓰고, 그 그림이 표현과 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u6-C52","difficulty":4,"kind":"essay","stem":"고른 표현에 어울리는 뒷면 그림을 어떻게 그릴지 쓰고, 그 그림이 표현과 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 「어둠은 두꺼운 담요 같았다」의 뒷면에 짙은 남색으로 방 전체를 덮고, 한쪽 구석에 작게 웅크린 아이를 그리겠다. 어둠이 담요처럼 무겁게 덮어 답답하고 무서운 장면을 그림으로 보여 줄 수 있다.","scoring_points":["그릴 그림을 썼는가","표현과 이어지는 점을 썼는가","표현이 만든 장면을 담았는가"]},"explanation":["무엇을 그릴까요?","표현과 어떻게 이어지나요?","장면을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_L12_challenge#10','kor',5,1,'u6','L12','g5_1_kor_u6_L12_challenge','lesson_challenge','K5-1-u6-C53',4,'essay','teacher','책갈피를 만들 때 지킬 점 두 가지를 쓰고, 각각 왜 지켜야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C53","difficulty":4,"kind":"essay","stem":"책갈피를 만들 때 지킬 점 두 가지를 쓰고, 각각 왜 지켜야 하는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 표현은 한두 줄만 골라 또렷하게 쓴다. 책갈피는 작아서 많이 쓰면 읽기 어렵기 때문이다. 둘째, 가져온 표현이라면 작품 제목과 지은이를 적는다. 그 표현을 만든 사람의 것임을 밝혀야 하기 때문이다.","scoring_points":["지킬 점 하나를 썼는가","다른 지킬 점을 썼는가","각각의 까닭을 썼는가"]},"explanation":["책갈피는 작아요.","출처를 떠올려요.","까닭도 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#1','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C57',1,'mc','auto','다른 사람의 말을 잘 듣는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X58']::text[],false,'{"seq":1,"concept":"K5-1-u6-C57","difficulty":1,"kind":"mc","stem":"다른 사람의 말을 잘 듣는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 사람을 보며 끝까지 듣는다","correct":true},{"t":"듣고 싶은 부분만 골라 듣는다","mis":"K5-1-u6-X58"},{"t":"실수만 따지며 듣는다","mis":"K5-1-u6-X58"},{"t":"내용이 많으면 흘려듣는다","mis":"K5-1-u6-X58"}],"explanation":["골라 들으면 놓쳐요.","따지기만 하면 뜻을 놓쳐요.","끝까지 귀 기울여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#2','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C9',1,'mc','auto','예솜이의 시에서 「내 장화는 작은 배 두 척이다」에 쓰인 비유 방법은 어느 것인가요?',ARRAY['K5-1-u6-X09','K5-1-u6-X14','K5-1-u6-X13']::text[],false,'{"seq":2,"concept":"K5-1-u6-C9","difficulty":1,"kind":"mc","stem":"예솜이의 시에서 「내 장화는 작은 배 두 척이다」에 쓰인 비유 방법은 어느 것인가요?","options":[{"t":"은유법","correct":true},{"t":"직유법","mis":"K5-1-u6-X09"},{"t":"비유가 아니다","mis":"K5-1-u6-X14"},{"t":"사실을 적은 문장","mis":"K5-1-u6-X13"}],"explanation":["견주는 말이 없어요.","장화를 배에 빗대었어요.","바로 그것이라고 말했어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#3','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C39',1,'mc','auto','「마지막 주자」에서 서림이네 반이 맨 뒤로 처진 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X39']::text[],false,'{"seq":3,"concept":"K5-1-u6-C39","difficulty":1,"kind":"mc","stem":"「마지막 주자」에서 서림이네 반이 맨 뒤로 처진 까닭은 어느 것인가요?","options":[{"t":"앞에서 달리던 우람이가 넘어져서","correct":true},{"t":"서림이가 늦게 출발해서","mis":"K5-1-u6-X39"},{"t":"바통을 잃어버려서","mis":"K5-1-u6-X39"},{"t":"비가 와서 경기가 멈춰서","mis":"K5-1-u6-X39"}],"explanation":["서림이 탓이 아니에요.","바통 이야기가 아니에요.","앞 주자가 넘어졌어요."],"asset":{"type":"passage","lines":["운동회 날, 서림이는 이어달리기 마지막 주자였다.","출발선에 서자 가슴이 북처럼 둥둥 울렸다.","앞에서 달리던 우람이가 넘어지는 바람에 서림이네 반은 맨 뒤로 처졌다.","서림이는 바통을 받고 이를 악물고 달렸지만 끝내 따라잡지 못했다."],"title":"서림의 이야기 「마지막 주자」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#4','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C13',1,'ox','auto','「우리 반 반장은 지담이다」는 「……은 ……이다」 꼴이니 은유법이에요.',ARRAY['K5-1-u6-X13']::text[],false,'{"seq":4,"concept":"K5-1-u6-C13","difficulty":1,"kind":"ox","stem":"「우리 반 반장은 지담이다」는 「……은 ……이다」 꼴이니 은유법이에요.","answer":"X","reason_options":[{"t":"서로 다른 두 대상을 겹친 것이 아니라 사실을 말한 문장이기 때문에","correct":true},{"t":"꼴이 같으면 모두 은유법이기 때문에","mis":"K5-1-u6-X13"}],"mis":"K5-1-u6-X13","explanation":["꼴만 보고 정하지 않아요.","반장이 누구인지 알려 준 문장이에요.","두 대상이 겹쳤는지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#5','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C33',1,'mc','auto','「노란 장화」에 붙인 두 쪽지 가운데 감상 쪽지로 더 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X33']::text[],false,'{"seq":5,"concept":"K5-1-u6-C33","difficulty":1,"kind":"mc","stem":"「노란 장화」에 붙인 두 쪽지 가운데 감상 쪽지로 더 알맞은 것은 어느 것인가요?","options":[{"t":"나봄의 쪽지","correct":true},{"t":"하담의 쪽지","mis":"K5-1-u6-X33"},{"t":"둘 다 알맞지 않다","mis":"K5-1-u6-X33"},{"t":"둘 다 똑같이 알맞다","mis":"K5-1-u6-X33"}],"explanation":["점수만 매겼어요.","나봄은 표현과 까닭을 적었어요.","어느 표현이 왜 좋았는지 보아요."],"asset":{"type":"passage","lines":["하담의 쪽지 — 재미있어. 백 점!","나봄의 쪽지 — 장화를 작은 배 두 척에 빗대니 웅덩이를 건너는 모습이 눈에 그려졌어.","장화가 다음 비를 기다리는 마지막 부분이 특히 마음에 남았어."],"title":"「노란 장화」에 붙인 감상 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#6','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C45',1,'mc','auto','「태자」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X45']::text[],false,'{"seq":6,"concept":"K5-1-u6-C45","difficulty":1,"kind":"mc","stem":"「태자」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"임금의 뒤를 이을 아들","correct":true},{"t":"뒷날 생기는 걱정과 근심","mis":"K5-1-u6-X45"},{"t":"여럿 가운데 뚜렷하게","mis":"K5-1-u6-X45"},{"t":"한 나라의 중앙 정부가 있는 곳","mis":"K5-1-u6-X45"}],"explanation":["후환의 뜻이에요.","단연의 뜻이에요.","대소가 태자였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#7','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C51',1,'mc','auto','「마지막 주자」로 책갈피를 만들 때 담을 만한 표현은 어느 것인가요?',ARRAY['K5-1-u6-X51']::text[],false,'{"seq":7,"concept":"K5-1-u6-C51","difficulty":1,"kind":"mc","stem":"「마지막 주자」로 책갈피를 만들 때 담을 만한 표현은 어느 것인가요?","options":[{"t":"운동장이 끝없는 사막 같았다","correct":true},{"t":"서림이는 마지막 주자였다","mis":"K5-1-u6-X51"},{"t":"운동회 날이었다","mis":"K5-1-u6-X51"},{"t":"서림이는 바통을 받았다","mis":"K5-1-u6-X51"}],"explanation":["사실만 적었어요.","배경을 말했을 뿐이에요.","한 줄로 장면이 떠올라요."],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#8','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C5',1,'mc','auto','비유가 들어 있는 속담은 어느 것인가요?',ARRAY['K5-1-u6-X14']::text[],false,'{"seq":8,"concept":"K5-1-u6-C5","difficulty":1,"kind":"mc","stem":"비유가 들어 있는 속담은 어느 것인가요?","options":[{"t":"티끌 모아 태산","correct":true},{"t":"우리 집은 삼 층이다","mis":"K5-1-u6-X14"},{"t":"밥을 먹고 이를 닦는다","mis":"K5-1-u6-X14"},{"t":"운동장에 친구가 많다","mis":"K5-1-u6-X14"}],"explanation":["사실을 말한 문장이에요.","있는 그대로 말했어요.","작은 것을 티끌에, 큰 것을 태산에 빗대었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#9','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C37',2,'mc','auto','「운동장이 끝없는 사막 같았다」가 전하는 서림이의 마음은 어느 것인가요?',ARRAY['K5-1-u6-X37','K5-1-u6-X02']::text[],false,'{"seq":9,"concept":"K5-1-u6-C37","difficulty":2,"kind":"mc","stem":"「운동장이 끝없는 사막 같았다」가 전하는 서림이의 마음은 어느 것인가요?","options":[{"t":"막막하고 쓸쓸한 마음","correct":true},{"t":"신나고 들뜬 마음","mis":"K5-1-u6-X37"},{"t":"덥고 목마른 느낌만","mis":"K5-1-u6-X02"},{"t":"아무 느낌 없음","mis":"K5-1-u6-X37"}],"explanation":["졌을 때의 마음이에요.","정말 사막이 된 게 아니에요.","끝없이 넓고 텅 빈 느낌이에요."],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#10','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C9',2,'match','auto','「노란 장화」의 표현과 비유 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C9","difficulty":2,"kind":"match","stem":"「노란 장화」의 표현과 비유 방법을 알맞게 이으세요.","pairs":[{"l":"내 장화는 작은 배 두 척이다","r":"은유법"},{"l":"오리처럼 뒤뚱뒤뚱 건너간다","r":"직유법"},{"l":"흙탕물이 튀어도 내 발은 보송보송","r":"비유가 아님"}],"mis":"K5-1-u6-X10","explanation":["바로 배라고 말했어요.","「처럼」으로 견주었어요.","빗댄 것이 없어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#11','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C41',2,'mc','auto','지담이가 그 장면을 인상적인 부분으로 고른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X40','K5-1-u6-X41']::text[],false,'{"seq":11,"concept":"K5-1-u6-C41","difficulty":2,"kind":"mc","stem":"지담이가 그 장면을 인상적인 부분으로 고른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"진 것보다 함께 달린 게 중요하다는 걸 알게 되어서","correct":true},{"t":"그 장면이 가장 길어서","mis":"K5-1-u6-X40"},{"t":"선생님이 고르라고 해서","mis":"K5-1-u6-X41"},{"t":"그냥 좋아서","mis":"K5-1-u6-X41"}],"explanation":["길이와 관계없어요.","스스로 골랐어요.","지담이가 댄 근거를 보아요."],"asset":{"type":"speech","turns":[{"who":"지담","text":"나는 우람이가 손을 잡아 준 장면이 제일 마음에 남았어. 진 것보다 함께 달린 게 중요하다는 걸 알았거든."},{"who":"나봄","text":"나도 그 장면을 골랐는데 느낌은 좀 달라. 넘어진 우람이가 미안한 마음을 용기 내어 전한 것 같아서 찡했어."},{"who":"지담","text":"같은 장면인데 너는 우람이의 마음을 보았구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#12','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C24',2,'mc','auto','「노란 장화」에 어울리는 낭송 방법은 어느 것인가요?',ARRAY['K5-1-u6-X24','K5-1-u6-X22','K5-1-u6-X23']::text[],false,'{"seq":12,"concept":"K5-1-u6-C24","difficulty":2,"kind":"mc","stem":"「노란 장화」에 어울리는 낭송 방법은 어느 것인가요?","options":[{"t":"신나는 분위기를 살려 「뒤뚱뒤뚱」을 리듬 있게 읽는다","correct":true},{"t":"슬프고 무겁게 천천히 읽는다","mis":"K5-1-u6-X24"},{"t":"아무 느낌 없이 빠르게 읽는다","mis":"K5-1-u6-X22"},{"t":"한 번에 숨도 쉬지 않고 읽는다","mis":"K5-1-u6-X23"}],"explanation":["슬픈 시가 아니에요.","빠르기가 아니에요.","즐거운 분위기를 살려요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#13','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C29',2,'mc','auto','예솜이가 장화의 보이지 않는 특징을 살린 행은 어느 것인가요?',ARRAY['K5-1-u6-X29']::text[],false,'{"seq":13,"concept":"K5-1-u6-C29","difficulty":2,"kind":"mc","stem":"예솜이가 장화의 보이지 않는 특징을 살린 행은 어느 것인가요?","options":[{"t":"흙탕물이 튀어도 내 발은 보송보송","correct":true},{"t":"비 오는 날 현관에 선 노란 장화","mis":"K5-1-u6-X29"},{"t":"웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","mis":"K5-1-u6-X29"},{"t":"집에 오면 장화는 현관에 엎드려","mis":"K5-1-u6-X29"}],"explanation":["색은 눈에 보여요.","걷는 모습은 보여요.","발을 지켜 주는 일은 보이지 않아요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#14','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C56',2,'mc','auto','신하가 「조개와 황새」로 말하려 한 것은 어느 것인가요?',ARRAY['K5-1-u6-X56']::text[],false,'{"seq":14,"concept":"K5-1-u6-C56","difficulty":2,"kind":"mc","stem":"신하가 「조개와 황새」로 말하려 한 것은 어느 것인가요?","options":[{"t":"두 나라가 다투면 지켜보던 다른 나라만 이롭다","correct":true},{"t":"조개를 잡을 때는 그물을 써야 한다","mis":"K5-1-u6-X56"},{"t":"황새는 조개보다 힘이 세다","mis":"K5-1-u6-X56"},{"t":"강가에는 조개가 많다","mis":"K5-1-u6-X56"}],"explanation":["글자 그대로 읽었어요.","힘 겨루기 이야기가 아니에요.","조개 · 황새 · 어부가 무엇을 나타내나요?"],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#15','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C58',2,'mc','auto','나윤이의 듣기 태도는 어느 것에 해당하나요?',ARRAY['K5-1-u6-X58']::text[],false,'{"seq":15,"concept":"K5-1-u6-C58","difficulty":2,"kind":"mc","stem":"나윤이의 듣기 태도는 어느 것에 해당하나요?","options":[{"t":"흘려듣기","correct":true},{"t":"확인하며 듣기","mis":"K5-1-u6-X58"},{"t":"질문하며 듣기","mis":"K5-1-u6-X58"},{"t":"정리하며 듣기","mis":"K5-1-u6-X58"}],"explanation":["되묻지 않았어요.","묻지도 않았어요.","내용이 많다고 흘려들으려 해요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"어제 왜 속상했다고 했지?"},{"who":"재하","text":"방금 전에 이야기했는데……."},{"who":"나윤","text":"(속으로) 내용이 너무 많아서 다 기억하기 힘드니까 그냥 흘려듣자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#16','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C33',2,'mc','auto','하담이의 쪽지를 고쳐 쓴다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X33']::text[],false,'{"seq":16,"concept":"K5-1-u6-C33","difficulty":2,"kind":"mc","stem":"하담이의 쪽지를 고쳐 쓴다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 표현이 왜 재미있었는지를 넣는다","correct":true},{"t":"점수를 더 높게 매긴다","mis":"K5-1-u6-X33"},{"t":"글자를 더 크게 쓴다","mis":"K5-1-u6-X33"},{"t":"재미있다는 말을 세 번 쓴다","mis":"K5-1-u6-X33"}],"explanation":["점수가 아니에요.","글씨 크기가 아니에요.","어느 표현이 왜인지 넣어요."],"asset":{"type":"passage","lines":["하담의 쪽지 — 재미있어. 백 점!","나봄의 쪽지 — 장화를 작은 배 두 척에 빗대니 웅덩이를 건너는 모습이 눈에 그려졌어.","장화가 다음 비를 기다리는 마지막 부분이 특히 마음에 남았어."],"title":"「노란 장화」에 붙인 감상 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#17','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C13',3,'error','auto','비유인지 가른 친구들이에요. 알맞지 않게 가른 말은 어느 것인가요?',ARRAY['K5-1-u6-X13','K5-1-u6-X10']::text[],false,'{"seq":17,"concept":"K5-1-u6-C13","difficulty":3,"kind":"error","stem":"비유인지 가른 친구들이에요. 알맞지 않게 가른 말은 어느 것인가요?","options":[{"t":"「반장이 누구인지 알려 주는 문장도 꼴이 같으니 은유야.」","correct":true,"mis_target":"K5-1-u6-X13"},{"t":"「장화를 배에 겹쳐 놓았으니 은유야.」","mis":"K5-1-u6-X13"},{"t":"「오리처럼이 들어 있으니 직유야.」","mis":"K5-1-u6-X10"}],"explanation":["두 대상이 겹쳤어요.","견주는 말이 있어요.","사실 문장은 꼴이 같아도 비유가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#18','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C42',3,'mc','auto','「마지막 주자」를 내 삶과 이어 감상한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X42','K5-1-u6-X39']::text[],false,'{"seq":18,"concept":"K5-1-u6-C42","difficulty":3,"kind":"mc","stem":"「마지막 주자」를 내 삶과 이어 감상한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠 활동에서 실수한 친구를 탓했던 일이 떠올라 다음에는 먼저 손을 내밀고 싶어졌다","correct":true},{"t":"이어달리기는 여러 명이 바통을 넘긴다","mis":"K5-1-u6-X42"},{"t":"이야기에 비유가 세 개 나온다","mis":"K5-1-u6-X39"},{"t":"운동회는 가을에 많이 한다","mis":"K5-1-u6-X42"}],"explanation":["사실만 말했어요.","비유 세기는 감상이 아니에요.","내 삶과 이어 생각했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#19','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C12',3,'mc','auto','「내 장화는 작은 배 두 척이다」에서 장화와 배의 비슷한 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X04']::text[],false,'{"seq":19,"concept":"K5-1-u6-C12","difficulty":3,"kind":"mc","stem":"「내 장화는 작은 배 두 척이다」에서 장화와 배의 비슷한 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물 위를 건너면서도 안을 젖지 않게 지켜 준다","correct":true},{"t":"둘 다 노랗다","mis":"K5-1-u6-X04"},{"t":"둘 다 바다에서만 쓴다","mis":"K5-1-u6-X04"},{"t":"둘 다 사람이 운전한다","mis":"K5-1-u6-X04"}],"explanation":["색이 닮은 게 아니에요.","장화는 바다에서 쓰지 않아요.","물을 건너며 지켜 줘요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#20','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C56',3,'mc','auto','「조개와 황새」 이야기에서 어부가 나타내는 것은 어느 것인가요?',ARRAY['K5-1-u6-X56']::text[],false,'{"seq":20,"concept":"K5-1-u6-C56","difficulty":3,"kind":"mc","stem":"「조개와 황새」 이야기에서 어부가 나타내는 것은 어느 것인가요?","options":[{"t":"두 나라가 다투는 사이 이득을 보는 다른 나라","correct":true},{"t":"바다를 지키는 사람","mis":"K5-1-u6-X56"},{"t":"조개를 먹는 사람","mis":"K5-1-u6-X56"},{"t":"신하를 보낸 왕","mis":"K5-1-u6-X56"}],"explanation":["글자 그대로 읽었어요.","먹는 이야기가 아니에요.","둘을 다 거둔 쪽이에요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#21','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C54',3,'mc','auto','하담이의 책갈피 소개할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X54']::text[],false,'{"seq":21,"concept":"K5-1-u6-C54","difficulty":3,"kind":"mc","stem":"하담이의 책갈피 소개할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빵처럼 따뜻했다는 표현을 골랐어요. 실수한 친구를 탓하지 않고 감싸 주는 마음이 이 한 줄에 담겨 있어서요.","correct":true},{"t":"이 책갈피는 이십 분 걸렸어요.","mis":"K5-1-u6-X54"},{"t":"노란 색연필을 썼어요.","mis":"K5-1-u6-X54"},{"t":"그냥 예뻐서요.","mis":"K5-1-u6-X54"}],"explanation":["시간 이야기예요.","도구 이야기예요.","표현과 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#22','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C15',3,'mc','auto','「내 장화는 작은 배 두 척이다」와 「내 장화는 작은 배 두 척 같다」의 느낌 차이로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X15','K5-1-u6-X09','K5-1-u6-X14']::text[],false,'{"seq":22,"concept":"K5-1-u6-C15","difficulty":3,"kind":"mc","stem":"「내 장화는 작은 배 두 척이다」와 「내 장화는 작은 배 두 척 같다」의 느낌 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"앞은 단번에 겹쳐 놓고, 뒤는 조심스럽게 견준다","correct":true},{"t":"두 문장의 느낌은 똑같다","mis":"K5-1-u6-X15"},{"t":"앞은 직유, 뒤는 은유다","mis":"K5-1-u6-X09"},{"t":"뒤 문장은 비유가 아니다","mis":"K5-1-u6-X14"}],"explanation":["방법이 다르면 느낌도 달라요.","둘이 뒤바뀌었어요.","둘 다 비유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#23','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C9',4,'essay','teacher','「노란 장화」에서 은유법과 직유법을 하나씩 찾아 쓰고, 각각 무엇을 무엇에 빗대었는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u6-C9","difficulty":4,"kind":"essay","stem":"「노란 장화」에서 은유법과 직유법을 하나씩 찾아 쓰고, 각각 무엇을 무엇에 빗대었는지 쓰세요.","answer_guide":{"answer":"예: 은유법 — 「내 장화는 작은 배 두 척이다」. 장화를 배에 빗대었다. 직유법 — 「오리처럼 뒤뚱뒤뚱 건너간다」. 웅덩이를 건너는 장화의 움직임을 오리에 빗대었다.","scoring_points":["은유법을 찾았는가","직유법을 찾았는가","무엇을 무엇에 빗대었는지 썼는가"]},"explanation":["견주는 말이 없는 표현은?","「처럼」이 든 표현은?","대상과 빗댄 것을 써요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#24','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C41',4,'essay','teacher','「마지막 주자」에서 가장 인상적인 부분을 하나 고르고, 그 부분에 쓰인 비유적 표현을 함께 짚어 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u6-C41","difficulty":4,"kind":"essay","stem":"「마지막 주자」에서 가장 인상적인 부분을 하나 고르고, 그 부분에 쓰인 비유적 표현을 함께 짚어 까닭을 쓰세요.","answer_guide":{"answer":"예: 우람이가 서림이의 손을 잡은 장면이 인상적이었다. 갓 구운 빵처럼 따뜻했다는 표현 때문에 손의 온기뿐 아니라 서로를 감싸 주는 마음까지 느껴져 찡했다.","scoring_points":["인상적인 부분을 골랐는가","그 부분의 비유적 표현을 짚었는가","근거를 들어 까닭을 썼는가"]},"explanation":["어느 장면인가요?","어떤 표현이 쓰였나요?","왜 마음이 움직였나요?"],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_a#25','kor',5,1,'u6','','g5_1_kor_u6_review_a','unit_review','K5-1-u6-C55',4,'essay','teacher','「조개와 황새」에서 신하가 이야기로 빗대어 말한 까닭을 쓰고, 비유가 시 밖에서도 쓰인다는 점과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u6-C55","difficulty":4,"kind":"essay","stem":"「조개와 황새」에서 신하가 이야기로 빗대어 말한 까닭을 쓰고, 비유가 시 밖에서도 쓰인다는 점과 이어 쓰세요.","answer_guide":{"answer":"예: 신하는 싸우지 말라고 바로 말하면 왕이 받아들이지 않을 수 있어서 조개와 황새 이야기로 빗대어 왕이 스스로 깨닫게 했다. 비유는 시에만 쓰는 기술이 아니라 사람을 설득하고 마음을 움직이는 말의 방법이다.","scoring_points":["빗대어 말한 까닭을 썼는가","스스로 깨닫게 한다는 점을 썼는가","비유가 말의 방법이라는 점과 이었는가"]},"explanation":["왜 바로 말하지 않았나요?","왕은 어떻게 되었나요?","비유는 어디에 쓰이나요?"],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#1','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C57',1,'mc','auto','「질문하며 듣기」에 알맞은 모습은 어느 것인가요?',ARRAY['K5-1-u6-X57','K5-1-u6-X58']::text[],false,'{"seq":1,"concept":"K5-1-u6-C57","difficulty":1,"kind":"mc","stem":"「질문하며 듣기」에 알맞은 모습은 어느 것인가요?","options":[{"t":"모르는 말이 나오면 물어본다","correct":true},{"t":"말하는 사람을 보지 않는다","mis":"K5-1-u6-X57"},{"t":"모르는 말은 아는 척 넘어간다","mis":"K5-1-u6-X58"},{"t":"듣고 싶은 말만 받아들인다","mis":"K5-1-u6-X58"}],"explanation":["보며 들어요.","모르면 물어요.","궁금한 점을 물으며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#2','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C10',1,'mc','auto','예솜이의 시에서 「오리처럼 뒤뚱뒤뚱 건너간다」에 쓰인 비유 방법은 어느 것인가요?',ARRAY['K5-1-u6-X10','K5-1-u6-X14']::text[],false,'{"seq":2,"concept":"K5-1-u6-C10","difficulty":1,"kind":"mc","stem":"예솜이의 시에서 「오리처럼 뒤뚱뒤뚱 건너간다」에 쓰인 비유 방법은 어느 것인가요?","options":[{"t":"직유법","correct":true},{"t":"은유법","mis":"K5-1-u6-X10"},{"t":"비유가 아니다","mis":"K5-1-u6-X14"},{"t":"사실을 적은 문장","mis":"K5-1-u6-X14"}],"explanation":["견주는 말이 보여요.","장화를 오리에 견주었어요.","「처럼」으로 견주었어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#3','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C39',1,'mc','auto','「마지막 주자」에서 결승선을 지난 서림이에게 다가와 손을 잡은 사람은 누구인가요?',ARRAY['K5-1-u6-X39']::text[],false,'{"seq":3,"concept":"K5-1-u6-C39","difficulty":1,"kind":"mc","stem":"「마지막 주자」에서 결승선을 지난 서림이에게 다가와 손을 잡은 사람은 누구인가요?","options":[{"t":"우람","correct":true},{"t":"예솜","mis":"K5-1-u6-X39"},{"t":"하담","mis":"K5-1-u6-X39"},{"t":"나봄","mis":"K5-1-u6-X39"}],"explanation":["시를 쓴 친구예요.","이야기에 나오지 않아요.","넘어졌던 친구예요."],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#4','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C32',1,'ox','auto','예솜이의 시에 비유를 열 개쯤 더 넣으면 훨씬 좋은 시가 돼요.',ARRAY['K5-1-u6-X32']::text[],false,'{"seq":4,"concept":"K5-1-u6-C32","difficulty":1,"kind":"ox","stem":"예솜이의 시에 비유를 열 개쯤 더 넣으면 훨씬 좋은 시가 돼요.","answer":"X","reason_options":[{"t":"비유는 많을수록 좋은 것이 아니라 특징이 잘 드러나는 것이 중요하기 때문에","correct":true},{"t":"비유가 많을수록 시가 화려해지기 때문에","mis":"K5-1-u6-X32"}],"mis":"K5-1-u6-X32","explanation":["많다고 좋은 게 아니에요.","흩어지면 흐려져요.","잘 드러나는 비유가 남아요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#5','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C22',1,'mc','auto','「노란 장화」를 낭송할 때 살릴 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X22']::text[],false,'{"seq":5,"concept":"K5-1-u6-C22","difficulty":1,"kind":"mc","stem":"「노란 장화」를 낭송할 때 살릴 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"비 오는 날의 즐거운 분위기","correct":true},{"t":"가장 빠른 속도","mis":"K5-1-u6-X22"},{"t":"가장 큰 목소리","mis":"K5-1-u6-X22"},{"t":"시의 글자 수","mis":"K5-1-u6-X22"}],"explanation":["빠르기가 목표가 아니에요.","크기가 목표가 아니에요.","분위기를 살려요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#6','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C45',1,'mc','auto','「후환」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X45']::text[],false,'{"seq":6,"concept":"K5-1-u6-C45","difficulty":1,"kind":"mc","stem":"「후환」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"뒷날 생기는 걱정과 근심","correct":true},{"t":"임금의 뒤를 이을 아들","mis":"K5-1-u6-X45"},{"t":"여럿 가운데 뚜렷하게","mis":"K5-1-u6-X45"},{"t":"한 나라의 중앙 정부가 있는 곳","mis":"K5-1-u6-X45"}],"explanation":["태자의 뜻이에요.","단연의 뜻이에요.","뒷날의 걱정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#7','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C53',1,'mc','auto','하담이가 책갈피에 함께 적어야 할 것은 어느 것인가요?',ARRAY['K5-1-u6-X53','K5-1-u6-X54']::text[],false,'{"seq":7,"concept":"K5-1-u6-C53","difficulty":1,"kind":"mc","stem":"하담이가 책갈피에 함께 적어야 할 것은 어느 것인가요?","options":[{"t":"작품 제목과 지은이","correct":true},{"t":"만든 날의 날씨","mis":"K5-1-u6-X53"},{"t":"쓴 색연필 개수","mis":"K5-1-u6-X54"},{"t":"만드는 데 걸린 시간","mis":"K5-1-u6-X54"}],"explanation":["날씨는 관계없어요.","개수는 관계없어요.","가져온 표현이니 출처를 적어요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#8','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C3',1,'mc','auto','예솜이가 장화를 작은 배에 빗대어 쓴 덕분에 생긴 좋은 점은 어느 것인가요?',ARRAY['K5-1-u6-X03']::text[],false,'{"seq":8,"concept":"K5-1-u6-C3","difficulty":1,"kind":"mc","stem":"예솜이가 장화를 작은 배에 빗대어 쓴 덕분에 생긴 좋은 점은 어느 것인가요?","options":[{"t":"익숙한 장화를 새롭게 느끼게 해 준다","correct":true},{"t":"시가 길어진다","mis":"K5-1-u6-X03"},{"t":"어려운 낱말을 익힌다","mis":"K5-1-u6-X03"},{"t":"장화의 값을 알 수 있다","mis":"K5-1-u6-X03"}],"explanation":["길이와 관계없어요.","어려운 말이 아니에요.","익숙한 것이 새롭게 보여요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#9','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C37',2,'mc','auto','「우람이의 손은 갓 구운 빵처럼 따뜻했다」가 주는 느낌은 어느 것인가요?',ARRAY['K5-1-u6-X02','K5-1-u6-X37']::text[],false,'{"seq":9,"concept":"K5-1-u6-C37","difficulty":2,"kind":"mc","stem":"「우람이의 손은 갓 구운 빵처럼 따뜻했다」가 주는 느낌은 어느 것인가요?","options":[{"t":"포근하고 위로가 되는 느낌","correct":true},{"t":"뜨거워서 데일 것 같은 느낌","mis":"K5-1-u6-X02"},{"t":"배가 고픈 느낌","mis":"K5-1-u6-X37"},{"t":"답답하고 무서운 느낌","mis":"K5-1-u6-X37"}],"explanation":["정말 뜨거운 게 아니에요.","빵을 먹는 장면이 아니에요.","따뜻한 위로예요."],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#10','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C37',2,'match','auto','「마지막 주자」의 표현과 그 느낌을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C37","difficulty":2,"kind":"match","stem":"「마지막 주자」의 표현과 그 느낌을 알맞게 이으세요.","pairs":[{"l":"가슴이 북처럼 둥둥 울렸다","r":"몹시 긴장된다"},{"l":"운동장이 끝없는 사막 같았다","r":"막막하고 쓸쓸하다"},{"l":"손은 갓 구운 빵처럼 따뜻했다","r":"포근하고 위로가 된다"}],"mis":"K5-1-u6-X37","explanation":["출발선의 긴장이에요.","진 뒤의 막막함이에요.","친구의 위로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#11','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C49',2,'mc','auto','지담이와 나봄이의 감상에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u6-X49']::text[],false,'{"seq":11,"concept":"K5-1-u6-C49","difficulty":2,"kind":"mc","stem":"지담이와 나봄이의 감상에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"같은 장면을 골랐지만 느낀 것이 서로 다르다","correct":true},{"t":"나봄이의 감상은 틀렸다","mis":"K5-1-u6-X49"},{"t":"두 사람은 다른 장면을 골랐다","mis":"K5-1-u6-X49"},{"t":"두 사람의 느낌은 똑같다","mis":"K5-1-u6-X49"}],"explanation":["틀린 감상이 아니에요.","같은 장면이에요.","느낌은 달랐어요."],"asset":{"type":"speech","turns":[{"who":"지담","text":"나는 우람이가 손을 잡아 준 장면이 제일 마음에 남았어. 진 것보다 함께 달린 게 중요하다는 걸 알았거든."},{"who":"나봄","text":"나도 그 장면을 골랐는데 느낌은 좀 달라. 넘어진 우람이가 미안한 마음을 용기 내어 전한 것 같아서 찡했어."},{"who":"지담","text":"같은 장면인데 너는 우람이의 마음을 보았구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#12','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C23',2,'mc','auto','「웅덩이를 만나면 / 오리처럼 뒤뚱뒤뚱 건너간다」처럼 끊어 읽으면 어떻게 되나요?',ARRAY['K5-1-u6-X23']::text[],false,'{"seq":12,"concept":"K5-1-u6-C23","difficulty":2,"kind":"mc","stem":"「웅덩이를 만나면 / 오리처럼 뒤뚱뒤뚱 건너간다」처럼 끊어 읽으면 어떻게 되나요?","options":[{"t":"뒤의 「오리처럼 뒤뚱뒤뚱」에 힘이 실려 건너는 모습이 살아난다","correct":true},{"t":"시의 뜻이 틀려진다","mis":"K5-1-u6-X23"},{"t":"어디서 끊어도 느낌이 같다","mis":"K5-1-u6-X23"},{"t":"끊어 읽으면 낭송이 아니다","mis":"K5-1-u6-X23"}],"explanation":["뜻이 틀려지지 않아요.","쉬는 곳에 따라 달라요.","쉰 뒤의 말에 힘이 실려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#13','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C30',2,'mc','auto','예솜이가 「내 장화는 작은 배 두 척이다」를 만든 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X30','K5-1-u6-X29']::text[],false,'{"seq":13,"concept":"K5-1-u6-C30","difficulty":2,"kind":"mc","stem":"예솜이가 「내 장화는 작은 배 두 척이다」를 만든 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"장화 → 물 위를 건너게 해 준다 → 배 → 둘 다 물을 건넌다 → 작은 배 두 척이다","correct":true},{"t":"배 → 장화 → 작은 배 두 척이다 → 둘 다 물을 건넌다","mis":"K5-1-u6-X30"},{"t":"작은 배 두 척이다 → 장화 → 배 → 물 위를 건너게 해 준다","mis":"K5-1-u6-X30"},{"t":"장화 → 노란색 → 배 → 작은 배 두 척이다","mis":"K5-1-u6-X29"}],"explanation":["대상부터 정해요.","표현은 마지막이에요.","특징을 살핀 뒤 빗댈 것을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#14','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C36',2,'mc','auto','「조개와 황새」에 쓰인 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X36']::text[],false,'{"seq":14,"concept":"K5-1-u6-C36","difficulty":2,"kind":"mc","stem":"「조개와 황새」에 쓰인 비유적 표현은 어느 것인가요?","options":[{"t":"조개는 덫처럼 입을 다물었습니다","correct":true},{"t":"큰 조개가 햇볕을 쬐고 있었습니다","mis":"K5-1-u6-X36"},{"t":"어부가 둘을 다 거두어 갔습니다","mis":"K5-1-u6-X36"},{"t":"왕은 계획을 접었다","mis":"K5-1-u6-X36"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","입을 다문 모습을 덫에 견주었어요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#15','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C57',2,'mc','auto','지담이가 등대지기가 무엇인지 물은 것은 어떤 듣기 방법인가요?',ARRAY['K5-1-u6-X57','K5-1-u6-X58']::text[],false,'{"seq":15,"concept":"K5-1-u6-C57","difficulty":2,"kind":"mc","stem":"지담이가 등대지기가 무엇인지 물은 것은 어떤 듣기 방법인가요?","options":[{"t":"질문하며 듣기","correct":true},{"t":"흘려듣기","mis":"K5-1-u6-X57"},{"t":"골라 듣기","mis":"K5-1-u6-X58"},{"t":"따지며 듣기","mis":"K5-1-u6-X58"}],"explanation":["흘려듣지 않았어요.","골라 듣지 않았어요.","모르는 말을 물었어요."],"asset":{"type":"speech","turns":[{"who":"휘린","text":"어제 도서관에서 빌린 책 이야기인데, 주인공이 마지막에 집으로 돌아가지 않고 등대지기가 돼."},{"who":"지담","text":"등대지기가 뭐야? 처음 듣는 말이야."},{"who":"휘린","text":"등대를 지키며 불을 밝히는 사람이야."},{"who":"지담","text":"그러니까 주인공이 집 대신 남의 길을 밝혀 주는 일을 고른 거구나. 내가 이해한 게 맞아?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#16','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C34',2,'mc','auto','하담이와 나봄이가 똑같이 장화를 시로 쓴다면 어떻게 될까요?',ARRAY['K5-1-u6-X34']::text[],false,'{"seq":16,"concept":"K5-1-u6-C34","difficulty":2,"kind":"mc","stem":"하담이와 나봄이가 똑같이 장화를 시로 쓴다면 어떻게 될까요?","options":[{"t":"장화를 무엇에 빗댈지는 저마다 다를 수 있다","correct":true},{"t":"둘 다 반드시 배에 빗대야 한다","mis":"K5-1-u6-X34"},{"t":"늦게 쓴 사람이 다르게 빗대면 틀린다","mis":"K5-1-u6-X34"},{"t":"빗댈 것은 장화마다 하나로 정해져 있다","mis":"K5-1-u6-X34"}],"explanation":["정해진 비유는 없어요.","틀린 것이 아니에요.","사람마다 보는 눈이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#17','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C41',3,'error','auto','「마지막 주자」의 인상적인 부분을 말한 친구들이에요. 근거가 없는 말은 어느 것인가요?',ARRAY['K5-1-u6-X41','K5-1-u6-X40']::text[],false,'{"seq":17,"concept":"K5-1-u6-C41","difficulty":3,"kind":"error","stem":"「마지막 주자」의 인상적인 부분을 말한 친구들이에요. 근거가 없는 말은 어느 것인가요?","options":[{"t":"「그 이야기는 그냥 다 좋았어.」","correct":true,"mis_target":"K5-1-u6-X41"},{"t":"「손을 잡은 장면이 좋았어. 우람이가 고맙다고 말해서 마음이 따뜻해졌거든.」","mis":"K5-1-u6-X41"},{"t":"「사막 같았다는 표현이 기억에 남아. 서림이의 막막함이 느껴졌어.」","mis":"K5-1-u6-X40"}],"explanation":["장면과 까닭이 있어요.","표현과 까닭이 있어요.","어느 대목 때문인지 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#18','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C39',3,'mc','auto','「마지막 주자」에서 서림이의 마음이 달라진 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X39']::text[],false,'{"seq":18,"concept":"K5-1-u6-C39","difficulty":3,"kind":"mc","stem":"「마지막 주자」에서 서림이의 마음이 달라진 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"긴장 → 막막함 → 위로받아 웃음","correct":true},{"t":"기쁨 → 화남 → 슬픔","mis":"K5-1-u6-X39"},{"t":"막막함 → 긴장 → 화남","mis":"K5-1-u6-X39"},{"t":"웃음 → 긴장 → 막막함","mis":"K5-1-u6-X39"}],"explanation":["처음엔 긴장했어요.","차례가 뒤섞였어요.","비유가 마음을 따라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#19','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C13',3,'mc','auto','다음 가운데 비유가 아닌 문장은 어느 것인가요?',ARRAY['K5-1-u6-X01']::text[],false,'{"seq":19,"concept":"K5-1-u6-C13","difficulty":3,"kind":"mc","stem":"다음 가운데 비유가 아닌 문장은 어느 것인가요?","options":[{"t":"우리 반 반장은 지담이다","correct":true},{"t":"지담이는 우리 반의 해님이다","mis":"K5-1-u6-X01"},{"t":"지담이 웃음은 종소리 같다","mis":"K5-1-u6-X01"},{"t":"지담이 목소리는 봄바람이다","mis":"K5-1-u6-X01"}],"explanation":["지담이를 해님에 빗대었어요.","웃음을 종소리에 견주었어요.","꼴이 같아도 사실이면 비유가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#20','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C55',3,'mc','auto','「조개와 황새」처럼 빗대어 말하는 방법을 생활에서 바르게 쓴 것은 어느 것인가요?',ARRAY['K5-1-u6-X55','K5-1-u6-X56','K5-1-u6-X05']::text[],false,'{"seq":20,"concept":"K5-1-u6-C55","difficulty":3,"kind":"mc","stem":"「조개와 황새」처럼 빗대어 말하는 방법을 생활에서 바르게 쓴 것은 어느 것인가요?","options":[{"t":"다투는 동생들에게 조개와 황새 이야기를 들려주어 스스로 생각하게 한다","correct":true},{"t":"싸우지 말라고만 크게 외친다","mis":"K5-1-u6-X55"},{"t":"동생들에게 조개 잡는 법을 가르친다","mis":"K5-1-u6-X56"},{"t":"비유는 시에만 쓰니 이야기는 하지 않는다","mis":"K5-1-u6-X05"}],"explanation":["바로 외치기만 했어요.","글자 그대로 받아들였어요.","빗대어 말하면 스스로 깨달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#21','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C52',3,'mc','auto','하담이의 책갈피 뒷면 그림으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X52']::text[],false,'{"seq":21,"concept":"K5-1-u6-C52","difficulty":3,"kind":"mc","stem":"하담이의 책갈피 뒷면 그림으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"흙 묻은 손과 손이 맞잡은 모습을 따뜻한 색으로 그린 그림","correct":true},{"t":"빵집 진열장 그림","mis":"K5-1-u6-X52"},{"t":"운동장 트랙의 길이를 잰 그림","mis":"K5-1-u6-X52"},{"t":"표현을 그대로 다시 쓴 글","mis":"K5-1-u6-X52"}],"explanation":["빵은 빗댄 것일 뿐이에요.","길이와 관계없어요.","표현이 만든 장면을 담아요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#22','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C11',3,'mc','auto','다음 가운데 견주는 말이 쓰인 직유 표현은 어느 것인가요?',ARRAY['K5-1-u6-X14','K5-1-u6-X10']::text[],false,'{"seq":22,"concept":"K5-1-u6-C11","difficulty":3,"kind":"mc","stem":"다음 가운데 견주는 말이 쓰인 직유 표현은 어느 것인가요?","options":[{"t":"키가 전봇대만큼 크다","correct":true},{"t":"키가 크다","mis":"K5-1-u6-X14"},{"t":"내 키는 전봇대다","mis":"K5-1-u6-X10"},{"t":"키를 재었다","mis":"K5-1-u6-X14"}],"explanation":["빗대지 않았어요.","견주는 말이 없는 은유예요.","「만큼」도 견주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#23','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C31',4,'essay','teacher','예솜이처럼 비 오는 날 쓰는 물건 하나를 골라 비유적 표현을 만들고, 좋은 비유의 조건에 맞는지 스스로 점검해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u6-C31","difficulty":4,"kind":"essay","stem":"예솜이처럼 비 오는 날 쓰는 물건 하나를 골라 비유적 표현을 만들고, 좋은 비유의 조건에 맞는지 스스로 점검해 쓰세요.","answer_guide":{"answer":"예: 「우비는 비 오는 날 내 몸을 감싸는 작은 지붕이다.」 우비와 지붕은 둘 다 비를 막아 준다는 비슷한 점이 있고, 비를 막아 주는 고마운 마음도 전해진다. 그래서 빗댄 까닭을 말할 수 있는 좋은 비유이다.","scoring_points":["비유적 표현을 만들었는가","비슷한 점과 까닭을 점검했는가","담고 싶은 마음이 전해지는지 점검했는가"]},"explanation":["무엇을 고를까요?","어떤 점이 닮았나요?","조건 세 가지로 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#24','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C49',4,'essay','teacher','지담이와 나봄이의 대화를 보고, 같은 장면을 두고 감상이 다를 때 감상 나누기를 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u6-C49","difficulty":4,"kind":"essay","stem":"지담이와 나봄이의 대화를 보고, 같은 장면을 두고 감상이 다를 때 감상 나누기를 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 누구의 감상이 맞는지 가리지 않고 서로 왜 그렇게 느꼈는지 까닭을 들어 본다. 지담이는 함께 달린 뜻을, 나봄이는 우람이의 용기를 보았다. 다른 감상을 들으면 나 혼자 놓친 뜻을 알게 된다.","scoring_points":["맞고 틀림을 가리지 않는다고 썼는가","두 사람의 감상을 견주었는가","다른 감상을 나누면 좋은 점을 썼는가"]},"explanation":["누가 맞을까요?","둘은 무엇을 보았나요?","나누면 무엇을 얻나요?"],"asset":{"type":"speech","turns":[{"who":"지담","text":"나는 우람이가 손을 잡아 준 장면이 제일 마음에 남았어. 진 것보다 함께 달린 게 중요하다는 걸 알았거든."},{"who":"나봄","text":"나도 그 장면을 골랐는데 느낌은 좀 달라. 넘어진 우람이가 미안한 마음을 용기 내어 전한 것 같아서 찡했어."},{"who":"지담","text":"같은 장면인데 너는 우람이의 마음을 보았구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_b#25','kor',5,1,'u6','','g5_1_kor_u6_review_b','unit_review','K5-1-u6-C57',4,'essay','teacher','휘린이와 지담이의 대화에서 지담이가 쓴 잘 듣는 방법 두 가지를 찾아 쓰고, 그 방법이 대화에 어떤 도움을 주었는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u6-C57","difficulty":4,"kind":"essay","stem":"휘린이와 지담이의 대화에서 지담이가 쓴 잘 듣는 방법 두 가지를 찾아 쓰고, 그 방법이 대화에 어떤 도움을 주었는지 쓰세요.","answer_guide":{"answer":"예: 지담이는 모르는 낱말인 등대지기를 물어보는 질문하며 듣기와, 이해한 내용이 맞는지 되묻는 확인하며 듣기를 했다. 덕분에 휘린이의 이야기를 바르게 이해하고 대화가 계속 이어졌다.","scoring_points":["질문하며 듣기를 찾았는가","확인하며 듣기를 찾았는가","대화에 준 도움을 썼는가"]},"explanation":["무엇을 물었나요?","무엇을 되물었나요?","대화는 어떻게 되었나요?"],"asset":{"type":"speech","turns":[{"who":"휘린","text":"어제 도서관에서 빌린 책 이야기인데, 주인공이 마지막에 집으로 돌아가지 않고 등대지기가 돼."},{"who":"지담","text":"등대지기가 뭐야? 처음 듣는 말이야."},{"who":"휘린","text":"등대를 지키며 불을 밝히는 사람이야."},{"who":"지담","text":"그러니까 주인공이 집 대신 남의 길을 밝혀 주는 일을 고른 거구나. 내가 이해한 게 맞아?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#1','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C58',1,'mc','auto','피해야 할 듣기 태도는 어느 것인가요?',ARRAY['K5-1-u6-X57']::text[],false,'{"seq":1,"concept":"K5-1-u6-C58","difficulty":1,"kind":"mc","stem":"피해야 할 듣기 태도는 어느 것인가요?","options":[{"t":"듣고 싶은 부분만 골라 듣기","correct":true},{"t":"귀 기울여 듣기","mis":"K5-1-u6-X57"},{"t":"정리하며 듣기","mis":"K5-1-u6-X57"},{"t":"확인하며 듣기","mis":"K5-1-u6-X57"}],"explanation":["귀 기울이기는 좋은 방법이에요.","정리하며 듣기도 좋아요.","골라 들으면 대화가 끊겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#2','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C1',1,'mc','auto','예솜이처럼 장화를 배에 빗대어 말하는 것을 무엇이라고 하나요?',ARRAY['K5-1-u6-X01']::text[],false,'{"seq":2,"concept":"K5-1-u6-C1","difficulty":1,"kind":"mc","stem":"예솜이처럼 장화를 배에 빗대어 말하는 것을 무엇이라고 하나요?","options":[{"t":"비유적 표현","correct":true},{"t":"흉내 내는 말","mis":"K5-1-u6-X01"},{"t":"높임 표현","mis":"K5-1-u6-X01"},{"t":"시간 표현","mis":"K5-1-u6-X01"}],"explanation":["소리나 모양을 흉내 낸 게 아니에요.","높임과 관계없어요.","비슷한 것에 빗대었어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#3','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C36',1,'mc','auto','「마지막 주자」 ①에서 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X36']::text[],false,'{"seq":3,"concept":"K5-1-u6-C36","difficulty":1,"kind":"mc","stem":"「마지막 주자」 ①에서 비유적 표현은 어느 것인가요?","options":[{"t":"가슴이 북처럼 둥둥 울렸다","correct":true},{"t":"서림이는 이어달리기 마지막 주자였다","mis":"K5-1-u6-X36"},{"t":"서림이네 반은 맨 뒤로 처졌다","mis":"K5-1-u6-X36"},{"t":"서림이는 바통을 받았다","mis":"K5-1-u6-X36"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","가슴을 북에 견주었어요."],"asset":{"type":"passage","lines":["운동회 날, 서림이는 이어달리기 마지막 주자였다.","출발선에 서자 가슴이 북처럼 둥둥 울렸다.","앞에서 달리던 우람이가 넘어지는 바람에 서림이네 반은 맨 뒤로 처졌다.","서림이는 바통을 받고 이를 악물고 달렸지만 끝내 따라잡지 못했다."],"title":"서림의 이야기 「마지막 주자」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#4','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C40',1,'ox','auto','인상적인 부분은 친구들과 똑같이 골라야 해요.',ARRAY['K5-1-u6-X40']::text[],false,'{"seq":4,"concept":"K5-1-u6-C40","difficulty":1,"kind":"ox","stem":"인상적인 부분은 친구들과 똑같이 골라야 해요.","answer":"X","reason_options":[{"t":"내 마음이 움직인 장면이라 사람마다 다를 수 있기 때문에","correct":true},{"t":"인상적인 부분에는 정답이 있기 때문에","mis":"K5-1-u6-X40"}],"mis":"K5-1-u6-X40","explanation":["정답이 없어요.","사람마다 달라요.","내 마음이 움직인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#5','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C21',1,'mc','auto','시를 낭송하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X21','K5-1-u6-X22']::text[],false,'{"seq":5,"concept":"K5-1-u6-C21","difficulty":1,"kind":"mc","stem":"시를 낭송하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"어울리는 몸짓이나 표정으로 낭송하기","correct":true},{"t":"글자 수를 세며 낭송하기","mis":"K5-1-u6-X21"},{"t":"눈을 감고 속으로만 읽기","mis":"K5-1-u6-X21"},{"t":"가장 빠르게 읽고 끝내기","mis":"K5-1-u6-X22"}],"explanation":["세기는 낭송이 아니에요.","소리 내어 읽어요.","몸짓과 표정도 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#6','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C45',1,'mc','auto','「도읍」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X45']::text[],false,'{"seq":6,"concept":"K5-1-u6-C45","difficulty":1,"kind":"mc","stem":"「도읍」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 나라의 중앙 정부가 있는 곳","correct":true},{"t":"임금의 뒤를 이을 아들","mis":"K5-1-u6-X45"},{"t":"뒷날 생기는 걱정과 근심","mis":"K5-1-u6-X45"},{"t":"여럿 가운데 뚜렷하게","mis":"K5-1-u6-X45"}],"explanation":["태자의 뜻이에요.","후환의 뜻이에요.","주몽은 졸본주를 도읍으로 삼았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#7','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C50',1,'mc','auto','책갈피 앞면과 뒷면에 넣을 것을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u6-X50','K5-1-u6-X53']::text[],false,'{"seq":7,"concept":"K5-1-u6-C50","difficulty":1,"kind":"mc","stem":"책갈피 앞면과 뒷면에 넣을 것을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"앞면 — 비유적 표현 / 뒷면 — 어울리는 그림","correct":true},{"t":"앞면 — 끈 / 뒷면 — 지은이 나이","mis":"K5-1-u6-X50"},{"t":"앞면 — 작품 전체 / 뒷면 — 빈칸","mis":"K5-1-u6-X53"},{"t":"앞면 — 날짜 / 뒷면 — 점수","mis":"K5-1-u6-X50"}],"explanation":["끈은 구멍에 묶어요.","작품 전체는 다 못 옮겨요.","앞면 표현, 뒷면 그림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#8','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C2',1,'mc','auto','「가슴이 북처럼 둥둥 울렸다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X02','K5-1-u6-X18']::text[],false,'{"seq":8,"concept":"K5-1-u6-C2","difficulty":1,"kind":"mc","stem":"「가슴이 북처럼 둥둥 울렸다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"가슴이 몹시 두근거렸다","correct":true},{"t":"가슴에 북을 달았다","mis":"K5-1-u6-X02"},{"t":"북 치는 소리를 들었다","mis":"K5-1-u6-X02"},{"t":"가슴이 아팠다","mis":"K5-1-u6-X18"}],"explanation":["정말 북을 단 게 아니에요.","북소리를 들은 게 아니에요.","두근거림을 북에 견주었어요."],"asset":{"type":"passage","lines":["운동회 날, 서림이는 이어달리기 마지막 주자였다.","출발선에 서자 가슴이 북처럼 둥둥 울렸다.","앞에서 달리던 우람이가 넘어지는 바람에 서림이네 반은 맨 뒤로 처졌다.","서림이는 바통을 받고 이를 악물고 달렸지만 끝내 따라잡지 못했다."],"title":"서림의 이야기 「마지막 주자」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#9','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C38',2,'mc','auto','「가슴이 북처럼 둥둥 울렸다」를 쓴 효과로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X38','K5-1-u6-X02']::text[],false,'{"seq":9,"concept":"K5-1-u6-C38","difficulty":2,"kind":"mc","stem":"「가슴이 북처럼 둥둥 울렸다」를 쓴 효과로 알맞은 것은 어느 것인가요?","options":[{"t":"긴장한 서림이의 마음이 소리처럼 생생하게 전해진다","correct":true},{"t":"달리기 순서를 정확히 알려 준다","mis":"K5-1-u6-X38"},{"t":"이야기를 짧게 줄여 준다","mis":"K5-1-u6-X38"},{"t":"서림이가 북을 쳤다는 사실을 알려 준다","mis":"K5-1-u6-X02"}],"explanation":["순서를 알려 주지 않아요.","줄이려는 게 아니에요.","긴장이 생생하게 전해져요."],"asset":{"type":"passage","lines":["운동회 날, 서림이는 이어달리기 마지막 주자였다.","출발선에 서자 가슴이 북처럼 둥둥 울렸다.","앞에서 달리던 우람이가 넘어지는 바람에 서림이네 반은 맨 뒤로 처졌다.","서림이는 바통을 받고 이를 악물고 달렸지만 끝내 따라잡지 못했다."],"title":"서림의 이야기 「마지막 주자」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#10','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C57',2,'match','auto','듣는 방법과 지담이의 말이나 행동을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C57","difficulty":2,"kind":"match","stem":"듣는 방법과 지담이의 말이나 행동을 알맞게 이으세요.","pairs":[{"l":"질문하며 듣기","r":"등대지기가 무엇인지 물었다"},{"l":"확인하며 듣기","r":"이해한 것이 맞는지 되물었다"},{"l":"귀 기울여 듣기","r":"휘린이를 보며 끝까지 들었다"}],"mis":"K5-1-u6-X57","explanation":["모르는 말을 물었어요.","되물어 확인했어요.","끝까지 들었어요."],"asset":{"type":"speech","turns":[{"who":"휘린","text":"어제 도서관에서 빌린 책 이야기인데, 주인공이 마지막에 집으로 돌아가지 않고 등대지기가 돼."},{"who":"지담","text":"등대지기가 뭐야? 처음 듣는 말이야."},{"who":"휘린","text":"등대를 지키며 불을 밝히는 사람이야."},{"who":"지담","text":"그러니까 주인공이 집 대신 남의 길을 밝혀 주는 일을 고른 거구나. 내가 이해한 게 맞아?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#11','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C40',2,'mc','auto','「마지막 주자」에서 인상적인 부분을 고를 때 살펴볼 것이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u6-X40']::text[],false,'{"seq":11,"concept":"K5-1-u6-C40","difficulty":2,"kind":"mc","stem":"「마지막 주자」에서 인상적인 부분을 고를 때 살펴볼 것이 아닌 것은 어느 것인가요?","options":[{"t":"이야기에 나온 쉼표의 개수","correct":true},{"t":"우람이가 손을 잡은 행동","mis":"K5-1-u6-X40"},{"t":"운동회라는 배경","mis":"K5-1-u6-X40"},{"t":"빵처럼 따뜻했다는 표현","mis":"K5-1-u6-X40"}],"explanation":["행동도 살펴요.","배경도 살펴요.","쉼표 개수는 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#12','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C26',2,'mc','auto','「노란 장화」를 나와 관련지어 감상한 것은 어느 것인가요?',ARRAY['K5-1-u6-X26','K5-1-u6-X39']::text[],false,'{"seq":12,"concept":"K5-1-u6-C26","difficulty":2,"kind":"mc","stem":"「노란 장화」를 나와 관련지어 감상한 것은 어느 것인가요?","options":[{"t":"나도 비 오는 날 웅덩이를 일부러 밟으며 즐거웠던 일이 떠올랐다","correct":true},{"t":"장화는 고무로 만든다","mis":"K5-1-u6-X26"},{"t":"시에 비유가 두 개 있다","mis":"K5-1-u6-X39"},{"t":"예솜이의 장화는 노랗다","mis":"K5-1-u6-X26"}],"explanation":["사실만 말했어요.","비유 세기는 감상이 아니에요.","내 경험과 이어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#13','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C31',2,'mc','auto','예솜이의 「작은 배 두 척」이 좋은 비유인 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X31','K5-1-u6-X32']::text[],false,'{"seq":13,"concept":"K5-1-u6-C31","difficulty":2,"kind":"mc","stem":"예솜이의 「작은 배 두 척」이 좋은 비유인 까닭은 어느 것인가요?","options":[{"t":"장화와 배는 둘 다 물을 건너게 해 준다는 비슷한 점이 있다","correct":true},{"t":"배라는 낱말이 화려하기 때문이다","mis":"K5-1-u6-X31"},{"t":"아무도 모를 만큼 뜻이 어렵기 때문이다","mis":"K5-1-u6-X31"},{"t":"비유를 많이 넣었기 때문이다","mis":"K5-1-u6-X32"}],"explanation":["화려함이 조건이 아니에요.","어렵기만 하면 닿지 않아요.","닮은 점과 까닭이 있어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#14','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C47',2,'mc','auto','주몽 이야기에서 「남다른 재주」에 해당하는 것은 어느 것인가요?',ARRAY['K5-1-u6-X47']::text[],false,'{"seq":14,"concept":"K5-1-u6-C47","difficulty":2,"kind":"mc","stem":"주몽 이야기에서 「남다른 재주」에 해당하는 것은 어느 것인가요?","options":[{"t":"일곱 살에 활을 만들어 백 번 쏘면 백 번 맞혔다","correct":true},{"t":"유화가 커다란 알을 낳았다","mis":"K5-1-u6-X47"},{"t":"자라와 물고기가 다리를 놓았다","mis":"K5-1-u6-X47"},{"t":"졸본주를 도읍으로 삼았다","mis":"K5-1-u6-X47"}],"explanation":["비범한 탄생이에요.","시련과 도움이에요.","어릴 때부터 뛰어난 능력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#15','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C57',2,'mc','auto','지담이가 대화의 마지막에 한 말은 어떤 듣기 방법인가요?',ARRAY['K5-1-u6-X57','K5-1-u6-X58']::text[],false,'{"seq":15,"concept":"K5-1-u6-C57","difficulty":2,"kind":"mc","stem":"지담이가 대화의 마지막에 한 말은 어떤 듣기 방법인가요?","options":[{"t":"확인하며 듣기","correct":true},{"t":"흘려듣기","mis":"K5-1-u6-X57"},{"t":"골라 듣기","mis":"K5-1-u6-X58"},{"t":"묻지 않기","mis":"K5-1-u6-X58"}],"explanation":["흘려듣지 않았어요.","골라 듣지 않았어요.","이해한 것을 되물었어요."],"asset":{"type":"speech","turns":[{"who":"휘린","text":"어제 도서관에서 빌린 책 이야기인데, 주인공이 마지막에 집으로 돌아가지 않고 등대지기가 돼."},{"who":"지담","text":"등대지기가 뭐야? 처음 듣는 말이야."},{"who":"휘린","text":"등대를 지키며 불을 밝히는 사람이야."},{"who":"지담","text":"그러니까 주인공이 집 대신 남의 길을 밝혀 주는 일을 고른 거구나. 내가 이해한 게 맞아?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#16','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C16',2,'mc','auto','「노란 장화」를 감상하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X16','K5-1-u6-X39']::text[],false,'{"seq":16,"concept":"K5-1-u6-C16","difficulty":2,"kind":"mc","stem":"「노란 장화」를 감상하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"배에 빗댄 표현이 주는 느낌을 먼저 즐긴다","correct":true},{"t":"은유법 · 직유법 이름만 외운다","mis":"K5-1-u6-X16"},{"t":"비유가 몇 개인지만 센다","mis":"K5-1-u6-X39"},{"t":"글자 수를 센다","mis":"K5-1-u6-X16"}],"explanation":["이름이 목적이 아니에요.","세기가 목적이 아니에요.","느낌을 즐겨요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#17','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C53',3,'error','auto','하담이의 책갈피 계획을 보고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X53','K5-1-u6-X52']::text[],false,'{"seq":17,"concept":"K5-1-u6-C53","difficulty":3,"kind":"error","stem":"하담이의 책갈피 계획을 보고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「다른 사람 작품에서 가져왔으니 제목은 안 적어도 돼.」","correct":true,"mis_target":"K5-1-u6-X53"},{"t":"「뒷면에는 두 손을 맞잡은 따뜻한 장면을 그리면 좋겠어.」","mis":"K5-1-u6-X52"},{"t":"「표현이 한 줄이라 책갈피에 알맞아.」","mis":"K5-1-u6-X53"}],"explanation":["표현이 만든 장면이에요.","한두 줄이 알맞아요.","가져왔다면 제목과 지은이를 적어요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#18','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C38',3,'mc','auto','「마지막 주자」에서 비유적 표현이 하는 구실로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X38','K5-1-u6-X35']::text[],false,'{"seq":18,"concept":"K5-1-u6-C38","difficulty":3,"kind":"mc","stem":"「마지막 주자」에서 비유적 표현이 하는 구실로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서림이의 마음이 긴장에서 막막함, 위로로 바뀌는 흐름을 장면처럼 보여 준다","correct":true},{"t":"경기 결과를 정확한 숫자로 알려 준다","mis":"K5-1-u6-X38"},{"t":"이야기를 짧게 줄여 준다","mis":"K5-1-u6-X38"},{"t":"우람이가 왜 넘어졌는지 설명한다","mis":"K5-1-u6-X35"}],"explanation":["숫자는 없어요.","줄이려는 게 아니에요.","마음의 흐름을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#19','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C32',3,'mc','auto','「노란 장화」에 비유를 다섯 개 더 넣으면 생길 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X32','K5-1-u6-X16']::text[],false,'{"seq":19,"concept":"K5-1-u6-C32","difficulty":3,"kind":"mc","stem":"「노란 장화」에 비유를 다섯 개 더 넣으면 생길 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"장화의 특징이 흩어져 무엇이 닮았는지 흐려진다","correct":true},{"t":"시가 화려해져 반드시 더 좋아진다","mis":"K5-1-u6-X32"},{"t":"장화의 모습이 더 또렷해진다","mis":"K5-1-u6-X32"},{"t":"읽는 사람이 비유를 쉽게 외운다","mis":"K5-1-u6-X16"}],"explanation":["반드시 좋아지지 않아요.","오히려 흐려져요.","많으면 흩어져요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#20','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C48',3,'mc','auto','주몽 · 박혁거세 · 프로메테우스 이야기가 모두 설명하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X48']::text[],false,'{"seq":20,"concept":"K5-1-u6-C48","difficulty":3,"kind":"mc","stem":"주몽 · 박혁거세 · 프로메테우스 이야기가 모두 설명하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"나라나 사람들의 삶에 무언가가 처음 시작된 일","correct":true},{"t":"주인공이 모두 알에서 태어난 일","mis":"K5-1-u6-X48"},{"t":"모두 같은 나라에서 일어난 일","mis":"K5-1-u6-X48"},{"t":"주인공이 모두 벌을 받은 일","mis":"K5-1-u6-X48"}],"explanation":["프로메테우스는 알에서 태어나지 않았어요.","나라가 서로 달라요.","무언가의 시작을 풀어요."],"asset":{"type":"passage","lines":["박혁거세 — 우물가에 내려온 빛 곁에 흰말과 큰 알이 있었다.","알에서 빛나는 사내아이가 태어나 자라서 왕이 되었고, 신라가 시작되었다.","프로메테우스 — 옛날 사람들에게는 불이 없어 추운 밤에 떨었다.","프로메테우스는 몰래 불을 가져와 사람들에게 건넸다.","사람들은 따뜻해졌지만 프로메테우스는 그 일로 벌을 받았다."],"title":"신화 두 편 더"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#21','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C51',3,'mc','auto','「노란 장화」로 책갈피를 만들 때 담을 표현으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X51']::text[],false,'{"seq":21,"concept":"K5-1-u6-C51","difficulty":3,"kind":"mc","stem":"「노란 장화」로 책갈피를 만들 때 담을 표현으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내 장화는 작은 배 두 척이다","correct":true},{"t":"비 오는 날 현관에 선 노란 장화","mis":"K5-1-u6-X51"},{"t":"집에 오면","mis":"K5-1-u6-X51"},{"t":"흙탕물이 튀어도","mis":"K5-1-u6-X51"}],"explanation":["장면만 말했어요.","한 줄로 장면이 떠오르지 않아요.","빗대어 장면이 떠올라요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#22','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C20',3,'mc','auto','「장화는 젖은 몸을 말리며 다음 비를 기다린다」를 쓴 예솜이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X20']::text[],false,'{"seq":22,"concept":"K5-1-u6-C20","difficulty":3,"kind":"mc","stem":"「장화는 젖은 몸을 말리며 다음 비를 기다린다」를 쓴 예솜이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"비 오는 날이 다시 오기를 기다리는 즐거운 마음","correct":true},{"t":"비가 싫어 장화를 버리고 싶은 마음","mis":"K5-1-u6-X20"},{"t":"장화가 젖어 속상한 마음","mis":"K5-1-u6-X20"},{"t":"장화를 새로 사고 싶은 마음","mis":"K5-1-u6-X20"}],"explanation":["싫어하는 마음이 아니에요.","속상한 게 아니에요.","다음 비를 기다려요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#23','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C33',4,'essay','teacher','「노란 장화」에 감상 쪽지를 쓰세요. 어느 표현이 왜 좋았는지와 더 좋은 생각을 함께 넣으세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u6-C33","difficulty":4,"kind":"essay","stem":"「노란 장화」에 감상 쪽지를 쓰세요. 어느 표현이 왜 좋았는지와 더 좋은 생각을 함께 넣으세요.","answer_guide":{"answer":"예: 「웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다」가 좋았어. 장화를 신고 조심조심 걷는 모습이 오리처럼 귀엽게 떠올랐거든. 웅덩이에 비친 하늘 이야기도 한 줄 있으면 더 좋겠어.","scoring_points":["좋았던 표현을 골랐는가","왜 좋았는지 썼는가","더 좋은 생각을 적었는가"]},"explanation":["어느 표현인가요?","왜 좋았나요?","다음 시를 돕는 생각을 적어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#24','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C39',4,'essay','teacher','「마지막 주자」를 줄거리와 서림이의 마음 변화를 중심으로 세 문장으로 간추리세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u6-C39","difficulty":4,"kind":"essay","stem":"「마지막 주자」를 줄거리와 서림이의 마음 변화를 중심으로 세 문장으로 간추리세요.","answer_guide":{"answer":"예: 운동회 이어달리기에서 마지막 주자인 서림이는 우람이가 넘어져 맨 뒤로 처진 채 달렸다. 결승선을 지나 막막해하던 서림이에게 우람이가 다가와 끝까지 달려 줘서 고맙다며 손을 잡았다. 서림이는 그제야 위로받아 웃었다.","scoring_points":["일어난 일을 차례대로 썼는가","서림이의 마음 변화를 넣었는가","세 문장으로 간추렸는가"]},"explanation":["무슨 일이 있었나요?","마음은 어떻게 바뀌었나요?","세 문장으로 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_c#25','kor',5,1,'u6','','g5_1_kor_u6_review_c','unit_review','K5-1-u6-C58',4,'essay','teacher','나윤이의 듣기 태도에서 아쉬운 점을 쓰고, 잘 듣는 방법을 써서 나윤이의 속마음을 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u6-C58","difficulty":4,"kind":"essay","stem":"나윤이의 듣기 태도에서 아쉬운 점을 쓰고, 잘 듣는 방법을 써서 나윤이의 속마음을 고쳐 쓰세요.","answer_guide":{"answer":"예: 나윤이는 내용이 많다고 처음부터 흘려들으려 해서 재하가 서운했을 것이다. 「내용이 많으니 속으로 간추리며 듣고, 기억이 안 나는 부분은 다시 물어봐야지.」로 고쳐 쓸 수 있다.","scoring_points":["아쉬운 점을 썼는가","잘 듣는 방법을 썼는가","속마음을 고쳐 썼는가"]},"explanation":["나윤이는 어떻게 들었나요?","어떤 방법이 필요할까요?","속마음을 바꾸어 써요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"어제 왜 속상했다고 했지?"},{"who":"재하","text":"방금 전에 이야기했는데……."},{"who":"나윤","text":"(속으로) 내용이 너무 많아서 다 기억하기 힘드니까 그냥 흘려듣자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#1','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C57',1,'mc','auto','「확인하며 듣기」에 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u6-X58']::text[],false,'{"seq":1,"concept":"K5-1-u6-C57","difficulty":1,"kind":"mc","stem":"「확인하며 듣기」에 알맞은 말은 어느 것인가요?","options":[{"t":"「내가 이해한 게 맞아?」","correct":true},{"t":"「그건 틀렸어.」","mis":"K5-1-u6-X58"},{"t":"「나중에 들을게.」","mis":"K5-1-u6-X58"},{"t":"「응, 알겠어.」 하고 넘어가기","mis":"K5-1-u6-X58"}],"explanation":["따지는 말이에요.","흘려듣는 말이에요.","이해한 것을 되물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#2','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C11',1,'mc','auto','직유법에 쓰이는 견주는 말이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u6-X11']::text[],false,'{"seq":2,"concept":"K5-1-u6-C11","difficulty":1,"kind":"mc","stem":"직유법에 쓰이는 견주는 말이 아닌 것은 어느 것인가요?","options":[{"t":"그래서","correct":true},{"t":"같이","mis":"K5-1-u6-X11"},{"t":"만큼","mis":"K5-1-u6-X11"},{"t":"같은","mis":"K5-1-u6-X11"}],"explanation":["같이는 견주는 말이에요.","만큼도 견주는 말이에요.","그래서는 앞뒤를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#3','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C36',1,'mc','auto','「마지막 주자」 ②에서 비유적 표현은 어느 것인가요?',ARRAY['K5-1-u6-X36']::text[],false,'{"seq":3,"concept":"K5-1-u6-C36","difficulty":1,"kind":"mc","stem":"「마지막 주자」 ②에서 비유적 표현은 어느 것인가요?","options":[{"t":"우람이의 손은 갓 구운 빵처럼 따뜻했다","correct":true},{"t":"서림이는 그제야 고개를 들고 웃었다","mis":"K5-1-u6-X36"},{"t":"우람이가 서림이에게 다가왔다","mis":"K5-1-u6-X36"},{"t":"우람이 무릎에 흙이 묻었다","mis":"K5-1-u6-X36"}],"explanation":["있었던 일 그대로예요.","빗댄 것이 없어요.","손을 빵에 견주었어요."],"asset":{"type":"passage","lines":["결승선을 지나고 나니 운동장이 끝없는 사막 같았다.","그때 무릎에 흙이 묻은 우람이가 다가와 서림이의 손을 꼭 잡았다.","「네가 끝까지 달려 줘서 고마워.」","우람이의 손은 갓 구운 빵처럼 따뜻했다.","서림이는 그제야 고개를 들고 웃었다."],"title":"서림의 이야기 「마지막 주자」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#4','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C55',1,'ox','auto','「조개와 황새」의 신하는 이야기로 빗대어 말해 왕이 스스로 깨닫게 했어요.',ARRAY['K5-1-u6-X55']::text[],false,'{"seq":4,"concept":"K5-1-u6-C55","difficulty":1,"kind":"ox","stem":"「조개와 황새」의 신하는 이야기로 빗대어 말해 왕이 스스로 깨닫게 했어요.","answer":"O","reason_options":[{"t":"「싸우지 마십시오」라고 바로 말하는 대신 빗대어 말했기 때문에","correct":true},{"t":"신하가 조개와 황새를 정말 데려와 보여 주었기 때문에","mis":"K5-1-u6-X55"}],"mis":"K5-1-u6-X55","explanation":["이야기를 들려주었어요.","바로 말하지 않았어요.","빗대어 말하면 스스로 깨달아요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#5','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C25',1,'mc','auto','시를 낭송하기 전에 할 준비로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X25','K5-1-u6-X16']::text[],false,'{"seq":5,"concept":"K5-1-u6-C25","difficulty":1,"kind":"mc","stem":"시를 낭송하기 전에 할 준비로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 번 소리 내어 읽어 본다","correct":true},{"t":"한 번 눈으로만 훑어본다","mis":"K5-1-u6-X25"},{"t":"낱말 뜻만 외운다","mis":"K5-1-u6-X16"},{"t":"제목만 읽어 둔다","mis":"K5-1-u6-X25"}],"explanation":["한 번으로는 부족해요.","외우기가 목적이 아니에요.","여러 번 소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#6','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C43',1,'mc','auto','신화가 주로 풀어내는 것은 어느 것인가요?',ARRAY['K5-1-u6-X43']::text[],false,'{"seq":6,"concept":"K5-1-u6-C43","difficulty":1,"kind":"mc","stem":"신화가 주로 풀어내는 것은 어느 것인가요?","options":[{"t":"나라가 어떻게 세워졌는지나 세상이 어떻게 생겼는지","correct":true},{"t":"어제 학교에서 있었던 일","mis":"K5-1-u6-X43"},{"t":"물건을 만드는 방법","mis":"K5-1-u6-X43"},{"t":"날씨를 미리 알리는 방법","mis":"K5-1-u6-X43"}],"explanation":["요즘 일이 아니에요.","만드는 방법이 아니에요.","시작을 놀라운 일로 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#7','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C54',1,'mc','auto','하담이가 책갈피 계획의 소개할 말 칸에 넣을 것은 어느 것인가요?',ARRAY['K5-1-u6-X54']::text[],false,'{"seq":7,"concept":"K5-1-u6-C54","difficulty":1,"kind":"mc","stem":"하담이가 책갈피 계획의 소개할 말 칸에 넣을 것은 어느 것인가요?","options":[{"t":"고른 표현과 그것을 고른 까닭","correct":true},{"t":"책갈피를 만든 시간","mis":"K5-1-u6-X54"},{"t":"끈의 색깔","mis":"K5-1-u6-X54"},{"t":"친구들의 점수","mis":"K5-1-u6-X54"}],"explanation":["시간은 관계없어요.","끈 색은 관계없어요.","표현과 까닭을 말해요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#8','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C6',1,'mc','auto','인상적인 부분을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u6-X06']::text[],false,'{"seq":8,"concept":"K5-1-u6-C6","difficulty":1,"kind":"mc","stem":"인상적인 부분을 바르게 말한 것은 어느 것인가요?","options":[{"t":"읽고 나서 유난히 마음에 남은 곳","correct":true},{"t":"이야기에서 가장 긴 곳","mis":"K5-1-u6-X06"},{"t":"맨 처음 나오는 문장","mis":"K5-1-u6-X06"},{"t":"누구나 같은 정답","mis":"K5-1-u6-X06"}],"explanation":["길이와 관계없어요.","첫 문장이 아니어도 돼요.","마음이 움직인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#9','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C17',2,'mc','auto','시 「노란 장화」에서 말하는 이가 가장 즐거워하는 때는 언제인가요?',ARRAY['K5-1-u6-X17']::text[],false,'{"seq":9,"concept":"K5-1-u6-C17","difficulty":2,"kind":"mc","stem":"시 「노란 장화」에서 말하는 이가 가장 즐거워하는 때는 언제인가요?","options":[{"t":"비 오는 날 장화를 신고 웅덩이를 건널 때","correct":true},{"t":"맑은 날 집에 있을 때","mis":"K5-1-u6-X17"},{"t":"장화를 벗어 둘 때","mis":"K5-1-u6-X17"},{"t":"흙탕물이 발에 들어올 때","mis":"K5-1-u6-X17"}],"explanation":["비 오는 날의 시예요.","벗어 둘 때는 장화가 기다려요.","웅덩이를 건너는 장면을 보아요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#10','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C56',2,'match','auto','「조개와 황새」 속 등장하는 것과 그것이 나타내는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u6-C56","difficulty":2,"kind":"match","stem":"「조개와 황새」 속 등장하는 것과 그것이 나타내는 것을 알맞게 이으세요.","pairs":[{"l":"조개","r":"다투는 한 나라"},{"l":"황새","r":"그와 맞서 다투는 다른 나라"},{"l":"어부","r":"다툼을 지켜보다 이득을 보는 나라"}],"mis":"K5-1-u6-X56","explanation":["조개와 황새는 다투는 두 나라예요.","맞서 버티는 쪽이에요.","어부가 둘을 다 거두었어요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#11','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C41',2,'mc','auto','인상적인 부분을 말할 때 근거를 대면 좋은 점은 어느 것인가요?',ARRAY['K5-1-u6-X41','K5-1-u6-X49','K5-1-u6-X40']::text[],false,'{"seq":11,"concept":"K5-1-u6-C41","difficulty":2,"kind":"mc","stem":"인상적인 부분을 말할 때 근거를 대면 좋은 점은 어느 것인가요?","options":[{"t":"내 감상이 작품 내용에 기댄 내 의견이 된다","correct":true},{"t":"말이 길어져 멋있어 보인다","mis":"K5-1-u6-X41"},{"t":"친구의 감상이 틀렸음을 보여 준다","mis":"K5-1-u6-X49"},{"t":"정답을 맞힐 수 있다","mis":"K5-1-u6-X40"}],"explanation":["길이가 목적이 아니에요.","남을 틀리게 하려는 게 아니에요.","근거를 대면 의견이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#12','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C21',2,'mc','auto','「노란 장화」를 친구와 번갈아 가며 낭송할 때 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X22','K5-1-u6-X21']::text[],false,'{"seq":12,"concept":"K5-1-u6-C21","difficulty":2,"kind":"mc","stem":"「노란 장화」를 친구와 번갈아 가며 낭송할 때 알맞은 것은 어느 것인가요?","options":[{"t":"한 행씩 나누어 맡아 이어 가며 읽는다","correct":true},{"t":"누가 더 크게 읽는지 겨룬다","mis":"K5-1-u6-X22"},{"t":"둘이 서로 다른 시를 읽는다","mis":"K5-1-u6-X21"},{"t":"한 사람만 읽는다","mis":"K5-1-u6-X21"}],"explanation":["겨루기가 아니에요.","같은 시를 읽어요.","나누어 이어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#13','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C27',2,'mc','auto','예솜이가 장화를 시의 대상으로 고른 것이 알맞은 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X27']::text[],false,'{"seq":13,"concept":"K5-1-u6-C27","difficulty":2,"kind":"mc","stem":"예솜이가 장화를 시의 대상으로 고른 것이 알맞은 까닭은 어느 것인가요?","options":[{"t":"비 오는 날 직접 신고 겪어서 특징을 잘 떠올릴 수 있기 때문이다","correct":true},{"t":"장화는 아무도 본 적 없는 물건이기 때문이다","mis":"K5-1-u6-X27"},{"t":"거창하고 화려한 대상이기 때문이다","mis":"K5-1-u6-X27"},{"t":"친구의 비밀이기 때문이다","mis":"K5-1-u6-X27"}],"explanation":["누구나 본 물건이에요.","거창할 필요가 없어요.","겪은 일에서 왔어요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#14','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C55',2,'mc','auto','신하가 바로 「싸우지 마십시오」라고 말하지 않고 이야기를 들려준 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X56','K5-1-u6-X55']::text[],false,'{"seq":14,"concept":"K5-1-u6-C55","difficulty":2,"kind":"mc","stem":"신하가 바로 「싸우지 마십시오」라고 말하지 않고 이야기를 들려준 까닭은 어느 것인가요?","options":[{"t":"빗대어 말하면 왕이 스스로 깨닫게 되기 때문에","correct":true},{"t":"조개와 황새를 좋아해서","mis":"K5-1-u6-X56"},{"t":"왕이 이야기를 듣는 것만 좋아해서","mis":"K5-1-u6-X55"},{"t":"바로 말하는 것은 거짓말이라서","mis":"K5-1-u6-X55"}],"explanation":["좋아해서가 아니에요.","왕의 취미 이야기가 아니에요.","스스로 깨닫게 하려고요."],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#15','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C58',2,'mc','auto','「따지며 듣기」가 아쉬운 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X57']::text[],false,'{"seq":15,"concept":"K5-1-u6-C58","difficulty":2,"kind":"mc","stem":"「따지며 듣기」가 아쉬운 까닭은 어느 것인가요?","options":[{"t":"실수나 부족한 점만 찾느라 말하는 사람의 뜻을 놓치기 때문에","correct":true},{"t":"말하는 사람을 너무 오래 보기 때문에","mis":"K5-1-u6-X57"},{"t":"모르는 말을 물어보기 때문에","mis":"K5-1-u6-X57"},{"t":"이해한 것을 확인하기 때문에","mis":"K5-1-u6-X57"}],"explanation":["보며 듣는 건 좋아요.","묻는 것도 좋아요.","흠만 찾으면 뜻을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#16','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C15',2,'mc','auto','「내 장화는 작은 배 두 척이다」를 직유법으로 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u6-X14','K5-1-u6-X15']::text[],false,'{"seq":16,"concept":"K5-1-u6-C15","difficulty":2,"kind":"mc","stem":"「내 장화는 작은 배 두 척이다」를 직유법으로 바꾼 것은 어느 것인가요?","options":[{"t":"내 장화는 작은 배 두 척 같다","correct":true},{"t":"내 장화는 노랗다","mis":"K5-1-u6-X14"},{"t":"작은 배가 장화를 신었다","mis":"K5-1-u6-X15"},{"t":"내 장화는 배가 아니다","mis":"K5-1-u6-X15"}],"explanation":["빗대지 않았어요.","뜻이 바뀌었어요.","견주는 말을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#17','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C57',3,'error','auto','잘 듣기에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u6-X57']::text[],false,'{"seq":17,"concept":"K5-1-u6-C57","difficulty":3,"kind":"error","stem":"잘 듣기에 대해 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘 들으려면 아무 말 없이 가만히 앉아 있기만 하면 돼.」","correct":true,"mis_target":"K5-1-u6-X57"},{"t":"「모르는 말이 나오면 물어보며 들어야 해.」","mis":"K5-1-u6-X57"},{"t":"「이해한 게 맞는지 되물어 확인하면 좋아.」","mis":"K5-1-u6-X57"}],"explanation":["질문하며 듣기예요.","확인하며 듣기예요.","잘 듣기는 움직이는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#18','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C49',3,'mc','auto','나봄이가 같은 장면인데 느낌은 좀 다르다고 한 말에 대해 알맞은 생각은 어느 것인가요?',ARRAY['K5-1-u6-X49']::text[],false,'{"seq":18,"concept":"K5-1-u6-C49","difficulty":3,"kind":"mc","stem":"나봄이가 같은 장면인데 느낌은 좀 다르다고 한 말에 대해 알맞은 생각은 어느 것인가요?","options":[{"t":"한 장면을 두고도 다르게 새길 수 있으니 서로의 까닭을 들어 본다","correct":true},{"t":"같은 장면을 골랐으니 지담이를 따라야 한다","mis":"K5-1-u6-X49"},{"t":"둘 중 누구의 감상이 맞는지 가려야 한다","mis":"K5-1-u6-X49"},{"t":"다르게 느꼈다면 다른 장면을 다시 골라야 한다","mis":"K5-1-u6-X49"}],"explanation":["따라야 하는 게 아니에요.","맞고 틀림을 가리지 않아요.","다른 해석도 나누어요."],"asset":{"type":"speech","turns":[{"who":"지담","text":"나는 우람이가 손을 잡아 준 장면이 제일 마음에 남았어. 진 것보다 함께 달린 게 중요하다는 걸 알았거든."},{"who":"나봄","text":"나도 그 장면을 골랐는데 느낌은 좀 달라. 넘어진 우람이가 미안한 마음을 용기 내어 전한 것 같아서 찡했어."},{"who":"지담","text":"같은 장면인데 너는 우람이의 마음을 보았구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#19','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C29',3,'mc','auto','장화의 보이지 않는 특징을 살펴 새 비유를 만든다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X14','K5-1-u6-X29','K5-1-u6-X31']::text[],false,'{"seq":19,"concept":"K5-1-u6-C29","difficulty":3,"kind":"mc","stem":"장화의 보이지 않는 특징을 살펴 새 비유를 만든다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장화는 비 오는 날 내 발을 지키는 작은 집이다","correct":true},{"t":"장화는 노란 고무 신발이다","mis":"K5-1-u6-X14"},{"t":"장화는 무릎까지 오는 길이다","mis":"K5-1-u6-X29"},{"t":"장화는 노란색 크레파스다","mis":"K5-1-u6-X31"}],"explanation":["빗대지 않았어요.","길이는 보이는 특징이에요.","지켜 주는 일을 살렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#20','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C44',3,'mc','auto','주몽이 좋은 말에게 일부러 먹이를 조금만 준 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X44']::text[],false,'{"seq":20,"concept":"K5-1-u6-C44","difficulty":3,"kind":"mc","stem":"주몽이 좋은 말에게 일부러 먹이를 조금만 준 까닭은 어느 것인가요?","options":[{"t":"말이 볼품없어 보이게 해 왕이 그 말을 자기에게 주도록 하려고","correct":true},{"t":"말이 살찌는 것이 싫어서","mis":"K5-1-u6-X44"},{"t":"왕의 말을 해치려고","mis":"K5-1-u6-X44"},{"t":"먹이가 모자라서","mis":"K5-1-u6-X44"}],"explanation":["살찌는 게 싫어서가 아니에요.","해치려는 게 아니에요.","왕이 그 말을 주었어요."],"asset":{"type":"passage","lines":["주몽의 재주는 왕자들보다 단연 뛰어났다.","태자 대소는 주몽을 없애야 후환이 없다고 왕에게 말했다.","왕은 주몽에게 말 먹이는 일을 시켰다.","주몽은 가장 좋은 말에게 일부러 먹이를 조금씩만 주었다.","그 말은 갈대처럼 여위어 갔고, 왕은 볼품없어진 그 말을 주몽에게 주었다.","쫓기던 주몽 앞에 강이 나타나자 자라와 물고기가 다리를 놓았다.","강을 건넌 주몽은 졸본주를 도읍으로 삼고 고구려를 세웠다."],"title":"신화 「알에서 태어난 아이」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#21','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C50',3,'mc','auto','하담이가 책갈피 계획에서 다음으로 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u6-X50','K5-1-u6-X53','K5-1-u6-X54']::text[],false,'{"seq":21,"concept":"K5-1-u6-C50","difficulty":3,"kind":"mc","stem":"하담이가 책갈피 계획에서 다음으로 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뒷면 그림을 정하고 끈을 묶어 완성한다","correct":true},{"t":"작품을 다시 고르기 전에 끈부터 산다","mis":"K5-1-u6-X50"},{"t":"표현을 지우고 이야기 전체를 옮겨 적는다","mis":"K5-1-u6-X53"},{"t":"소개할 말 대신 점수를 적는다","mis":"K5-1-u6-X54"}],"explanation":["작품과 표현은 골랐어요.","한두 줄이 알맞아요.","그림과 끈이 남았어요."],"asset":{"type":"passage","lines":["고른 작품 — 서림의 이야기 「마지막 주자」","앞면 — 우람이의 손은 갓 구운 빵처럼 따뜻했다","뒷면 그림 — ?","소개할 말 — ?"],"title":"하담의 책갈피 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#22','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C8',3,'mc','auto','「내 장화는 작은 배 두 척이다」에서 「두 척」이라고 한 까닭은 어느 것인가요?',ARRAY['K5-1-u6-X08']::text[],false,'{"seq":22,"concept":"K5-1-u6-C8","difficulty":3,"kind":"mc","stem":"「내 장화는 작은 배 두 척이다」에서 「두 척」이라고 한 까닭은 어느 것인가요?","options":[{"t":"장화가 두 짝이라 배 두 척에 빗대었다","correct":true},{"t":"배가 두 번 나와서","mis":"K5-1-u6-X08"},{"t":"장화를 두 번 샀기 때문에","mis":"K5-1-u6-X08"},{"t":"웅덩이가 두 개라서","mis":"K5-1-u6-X08"}],"explanation":["배는 한 번 나와요.","산 이야기가 아니에요.","장화 한 켤레는 두 짝이에요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#23','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C26',4,'essay','teacher','「노란 장화」를 읽고 나와 관련지어 감상한 내용을 쓰고, 지금의 나를 비 오는 날의 물건에 빗대어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u6-C26","difficulty":4,"kind":"essay","stem":"「노란 장화」를 읽고 나와 관련지어 감상한 내용을 쓰고, 지금의 나를 비 오는 날의 물건에 빗대어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 나도 비 오는 날 웅덩이를 첨벙첨벙 밟으며 놀았던 일이 떠올라 즐거웠다. 지금의 나는 아직 펼치지 않은 우산이다. 비가 오면 언제든 활짝 펼칠 준비가 되어 있기 때문이다.","scoring_points":["나와 관련지어 감상했는가","나를 빗대어 한 문장으로 썼는가","빗댄 까닭을 썼는가"]},"explanation":["어떤 일이 떠올랐나요?","지금의 나는?","까닭을 함께 써요."],"asset":{"type":"passage","lines":["비 오는 날 현관에 선 노란 장화","내 장화는 작은 배 두 척이다","웅덩이를 만나면 오리처럼 뒤뚱뒤뚱 건너간다","흙탕물이 튀어도 내 발은 보송보송","집에 오면 장화는 현관에 엎드려","젖은 몸을 말리며 다음 비를 기다린다"],"title":"예솜의 시 「노란 장화」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#24','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C42',4,'essay','teacher','「마지막 주자」를 읽고 내 삶과 이어 떠오른 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u6-C42","difficulty":4,"kind":"essay","stem":"「마지막 주자」를 읽고 내 삶과 이어 떠오른 생각을 쓰세요.","answer_guide":{"answer":"예: 줄넘기 대회에서 내가 걸려 우리 모둠이 졌을 때 친구가 괜찮다고 말해 준 일이 떠올랐다. 그때 우람이처럼 나도 고마운 마음을 먼저 전했으면 좋았겠다는 생각이 들었다. 다음에는 내가 먼저 손을 내밀겠다.","scoring_points":["떠오른 내 경험을 썼는가","작품과 내 경험을 이었는가","앞으로의 생각이나 다짐을 썼는가"]},"explanation":["어떤 일이 떠올랐나요?","이야기와 어떻게 이어지나요?","어떤 생각이 들었나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u6_review_d#25','kor',5,1,'u6','','g5_1_kor_u6_review_d','unit_review','K5-1-u6-C56',4,'essay','teacher','「조개와 황새」에 담긴 뜻을 쓰고, 이 뜻이 우리 반 생활에서 필요한 상황을 하나 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u6-C56","difficulty":4,"kind":"essay","stem":"「조개와 황새」에 담긴 뜻을 쓰고, 이 뜻이 우리 반 생활에서 필요한 상황을 하나 들어 쓰세요.","answer_guide":{"answer":"예: 서로 물러서지 않고 다투면 둘 다 손해를 보고 다른 쪽만 이롭다는 뜻이다. 두 모둠이 운동장을 쓰는 차례를 두고 다투다 쉬는 시간이 다 지나 버려 아무도 못 노는 상황에서 이 뜻을 떠올리면 서로 양보할 수 있다.","scoring_points":["이야기에 담긴 뜻을 썼는가","우리 반 상황을 들었는가","뜻과 상황을 알맞게 이었는가"]},"explanation":["조개와 황새는 어떻게 되었나요?","비슷한 일이 있었나요?","뜻을 떠올리면 무엇이 달라지나요?"],"asset":{"type":"passage","lines":["여러 나라가 이웃해 있던 아주 오래전의 일이다.","옆 나라가 쳐들어오려 하자 한 나라 왕은 말솜씨 좋은 신하를 보냈다.","신하는 옆 나라 왕에게 이런 이야기를 들려주었다.","「강가에서 큰 조개가 입을 벌리고 햇볕을 쬐고 있었습니다.」","「황새가 돌팔매처럼 날아와 쪼자 조개는 덫처럼 입을 다물었습니다.」","「둘이 버티는 사이 지나가던 어부가 둘을 다 거두어 갔습니다.」","이야기를 들은 왕은 이웃 나라를 치려던 계획을 접었다."],"title":"이야기 「조개와 황새」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
